window.MAPLE_SEARCH_INDEX={"documents":[{"heading":"MAPLE Publications","level":2,"page":"articles.html","page_entry":true,"page_role":"content","section_order":0,"text":"Papers describing the MAPLE framework and its applications. ParmFit — September 14, 2026 · ChemRxiv","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-papers"},{"heading":"Leveraging Machine Learning Interatomic Potentials into Fitting Fast and Accurate AMBER-Compatible Precise Force Field","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":1,"text":"Introduces ParmFit, an automated MAPLE framework that uses machine-learning interatomic potentials to construct and refine AMBER/GAFF-compatible parameters for small molecules, modified biomolecular residues, and metal coordination environments. Read on ChemRxiv → Framework — April 30, 2026 · Chemical Science","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#leveraging-machine-learning-interatomic-potentials-into-fitting-fast-and-accurate-amber-compatible-precise-force-field"},{"heading":"MAPLE: A Machine-Learning Force-Field-Native Platform for Automated Reaction Modeling and Enzyme Design","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":2,"text":"Presents MAPLE as an MLFF-native molecular modeling platform with a tailored software framework and parallelized algorithms for large-scale, versatile reaction modeling and enzyme design. Read in Chemical Science →","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-a-machine-learning-force-field-native-platform-for-automated-reaction-modeling-and-enzyme-design"},{"heading":"News & Updates","level":2,"page":"articles.html","page_entry":false,"page_role":"content","section_order":3,"text":"Release announcements and project updates. See all releases on GitHub . Release — August 10, 2026","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#news"},{"heading":"MAPLE v0.1.5","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":4,"text":"Added ParmFit workflows for Refinement, NCAA, and MetalAA parameterization, native PDB handling, Direct MaxFlux transition-state searches, FeNNol/FeNNix-Bio1 support, and explicit-solvent compatibility updates. Release notes on GitHub → Release — June 4, 2026","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-v0-1-5"},{"heading":"MAPLE v0.1.4","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":5,"text":"Standardized optimization workflows, corrected optimization metrics and force handling, expanded SCAN methods, improved UMA and MD restart behavior, and introduced calculator plugins and explicit-solvent cluster generation. Release notes on GitHub → Release — April 1, 2026","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-v0-1-4"},{"heading":"MAPLE v0.1.3","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":6,"text":"Expanded MD workflows with NVT/NPT support, GROMACS-style MDP configuration, restart/trajectory improvements, task-aware UMA sizing, MACEPol integration, and IRC/debug cleanup. Release notes on GitHub → Release — February 7, 2026","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-v0-1-3"},{"heading":"MAPLE v0.1.1","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":7,"text":"Added AutoNEB with adaptive image insertion, NVE molecular dynamics, SDCG optimizer with GDIIS acceleration, new IRC integrators (EulerPC, HPC, LQA), rigid scan mode, and input/parser improvements. Release notes on GitHub → Release — December 31, 2025","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-v0-1-1"},{"heading":"MAPLE v0.1.0","level":3,"page":"articles.html","page_entry":false,"page_role":"content","section_order":8,"text":"First public release with frequency analysis, broad ML potential support (ANI, AIMNet2, MACE-OFF23, UMA), geometry optimization, transition state search, IRC, PES scan, solvation, constraints, GPU acceleration, and D4 dispersion. Release notes on GitHub →","title":"Articles & News — MAPLE","trail":["MAPLE","Articles & News"],"type":"Guide","url":"articles.html#maple-v0-1-0"},{"heading":"Changelog","level":2,"page":"development.html","page_entry":true,"page_role":"content","section_order":0,"text":"Recent release and development milestones are listed below. All Releases on GitHub →","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#changelog"},{"heading":"Version 0.1.5 — August 10, 2026","level":3,"page":"development.html","page_entry":false,"page_role":"content","section_order":1,"text":"August release expanding force-field parameterization, transition-state search, and model support. ParmFit workflows — Added Refinement, NCAA, and MetalAA parameterization routes with structured outputs and reusable work directories. Direct MaxFlux — Added a new transition-state search route for supported IPOPT-compatible environments. FeNNol support — Added FeNNol and FeNNix-Bio1 calculator configuration and documentation. Input and solvent compatibility — Expanded native PDB handling and maintained explicit-solvent workflow compatibility.","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#v0-1-5"},{"heading":"Version 0.1.4 — June 4, 2026","level":3,"page":"development.html","page_entry":false,"page_role":"content","section_order":2,"text":"June release standardizing optimization and expanding calculator, scan, and explicit-solvent workflows. Optimization updates — Standardized optimization workflows and corrected optimization metrics and force handling. Expanded SCAN methods — Added and documented additional scan optimizers and workflow controls. Calculator plugins — Introduced calculator registration and plugin support for custom backends. Explicit solvent tools — Added explicit-solvent cluster generation and related file-handling improvements.","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#v0-1-4"},{"heading":"Version 0.1.4 — May 2026 development","level":3,"page":"development.html","page_entry":false,"page_role":"content","section_order":3,"text":"Development milestone for calculator-layer hardening and documentation. This entry documents in-progress branch behavior and is not a GitHub release claim. Calculator registry contract — Backends declare model names, energy units, Hessian modes, charge/multiplicity support, PBC support, model-path behavior, and supported options before construction. Capability matrix — Added documentation for PBC, charge/spin, Hessian, implicit-solvent, D4, HVP, and checkpoint behavior across ANI, AIMNet2, MACE-family, and UMA backends. Energy API cleanup — Developer docs direct downstream code to ASE's atoms.get_potential_energy() pattern instead of legacy backend-specific get_energy() calls.","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#v0-1-4-dev"},{"heading":"Version 0.1.3 — April 1, 2026","level":3,"page":"development.html","page_entry":false,"page_role":"content","section_order":4,"text":"April monthly update with expanded MD workflows, better model integration, and release-line cleanup. Expanded MD workflow — Added experimental NVT and NPT support with Langevin and V-rescale thermostats, Berendsen and C-rescale barostats, and improved thermodynamic logging. GROMACS-style MDP support — MD jobs can now be configured through .mdp files and generated from the CLI with maple md . Restart and trajectory improvements — Added rst_file -based restart handling, RNG state persistence, final.xyz export, and binary DCD trajectory output. PBC and file-handling cleanup — Improved relative-path handling for XYZ / XYZTRAJ inputs and cleaner restart resolution from output directories. UMA and MACEPol updates — Added task-aware UMA sizing, broader fallback checkpoint support, and MACEPol integration with new examples. IRC and debug fixes — Merged parser stabilization, inline-coordinate fixes, and general IRC-related cleanup from the enhance branch.","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#v0-1-3"},{"heading":"Version 0.1.1 — February 7, 2026","level":3,"page":"development.html","page_entry":false,"page_role":"content","section_order":5,"text":"February monthly update introducing new reaction-path and optimization capabilities. AutoNEB — Added tree-based automated NEB with adaptive image insertion, branch splitting, and final global MEP refinement. NVE molecular dynamics — Introduced Velocity Verlet dynamics in the microcanonical ensemble with Maxwell-Boltzmann initialization and trajectory logging. SDCG optimizer — Added phased steepest-descent plus conjugate-gradient optimization with GDIIS acceleration. New IRC integrators — Added EulerPC, HPC, and LQA methods in addition to GS. Rigid scan mode — Added rigid-body scan support with fragment detection from bond connectivity. Input and parser improvements — Added trajectory single-point workflows, charge/multiplicity inline input, and centralized parameter handling.","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#v0-1-1"},{"heading":"Version 0.1.0 — December 31, 2025","level":3,"page":"development.html","page_entry":false,"page_role":"content","section_order":6,"text":"Initial public release of MAPLE with core computational chemistry capabilities. Frequency analysis — Normal mode analysis with mass-weighted Hessian diagonalization, RRHO thermochemistry corrections, and IR spectrum generation. ML potential support — ANI-2x, ANI-1x, ANI-1ccx, ANI-1xnr, AIMNet2, AIMNet2-NSE, MACE-OFF23 (s/m/l), and UMA. Geometry optimization — L-BFGS, RFO, steepest descent, conjugate gradient, DIIS, and bracketing L-BFGS methods. Transition state search — NEB, CI-NEB, P-RFO, Dimer, and Growing String methods. IRC — Intrinsic reaction coordinate with GS, LQA, HPC, and EulerPC integrators. PES scan — 1D, 2D, and 3D relaxed or rigid scans along bonds, angles, and dihedrals. Solvation — Experimental implicit solvent single-point energies and non-periodic explicit solvent clusters. Constraints — Fix atoms, bonds, angles, and dihedral angles during optimization. GPU acceleration — CUDA support for ML potential evaluations when the selected backend and runtime support GPU execution. D4 dispersion — Optional DFT-D4 dispersion correction where the selected calculator backend supports it.","title":"Development & Releases — MAPLE","trail":["MAPLE","Development & Releases"],"type":"Guide","url":"development.html#v0-1-0"},{"heading":"Source Code","level":2,"page":"downloads.html","page_entry":true,"page_role":"content","section_order":0,"text":"MAPLE is hosted on GitHub. Clone the public source repository for the published code line (see the license terms below). Source Code on GitHub → git clone https://github.com/ClickFF/MAPLE.git Documentation note: Public guidance targets the published release line. Pages that describe unreleased behavior are explicitly marked as development documentation.","title":"Downloads — MAPLE","trail":["MAPLE","Downloads"],"type":"Guide","url":"downloads.html#source-code"},{"heading":"Installation","level":2,"page":"downloads.html","page_entry":false,"page_role":"content","section_order":1,"text":"Follow the step-by-step guide to set up Python, PyTorch, and the ML potential dependencies. Installation Guide →","title":"Downloads — MAPLE","trail":["MAPLE","Downloads"],"type":"Guide","url":"downloads.html#installation"},{"heading":"License","level":2,"page":"downloads.html","page_entry":false,"page_role":"content","section_order":2,"text":"MAPLE is distributed under a modified BSD 3-Clause license with a non-commercial restriction: Academic & research use : free under Creative Commons Attribution (CC BY) in addition to BSD 3-Clause redistribution terms. Commercial use : prohibited without explicit written permission from the copyright holder (University of Pittsburgh). This is not a standard BSD 3-Clause license and is not OSI-approved \"open source\". See the full LICENSE on GitHub for complete terms.","title":"Downloads — MAPLE","trail":["MAPLE","Downloads"],"type":"Guide","url":"downloads.html#license"},{"heading":"Constraints","level":1,"page":"functions/constrain.html","page_entry":true,"page_role":"content","section_order":0,"text":"Constraints in MAPLE allow you to impose geometric restrictions on atoms or internal coordinates during optimization, scan, and dynamics calculations. They are specified in the post-processing section of the input file, which follows the coordinate block. Constraint commands fix specific degrees of freedom (atom positions, bond lengths, angles, or dihedrals) at their initial values, while scan commands define coordinate ranges to be systematically explored.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#constraints"},{"heading":"Atom Constraints (C Command)","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":1,"text":"The C command freezes an atom at its current position. The atom will not move during optimization or dynamics. This is useful for anchoring specific parts of a molecular system, such as fixing a metal center or holding boundary atoms in place. Format Description C i Fix the position of atom i C 3 This freezes atom 3 at its initial Cartesian coordinates. All three spatial components (x, y, z) are held fixed. You can fix multiple atoms by including multiple C commands: C 1 C 5 C 12","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#atom-constraints"},{"heading":"Bond Constraints (B Command)","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":2,"text":"The B command fixes the distance between two atoms at its initial value. During optimization, the bond length will remain constant while the rest of the system relaxes. Format Description B i j Fix the bond distance between atoms i and j B 1 5 This constrains the distance between atoms 1 and 5 at whatever value it has in the input geometry.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#bond-constraints"},{"heading":"Angle Constraints (A Command)","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":3,"text":"The A command fixes the bond angle formed by three atoms. The angle i-j-k (with j as the vertex atom) is held constant during the calculation. Format Description A i j k Fix the bond angle at vertex atom j between atoms i , j , and k A 2 1 4 This constrains the angle formed by atoms 2-1-4 at its initial value.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#angle-constraints"},{"heading":"Dihedral Constraints (D Command)","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":4,"text":"The D command fixes the dihedral (torsion) angle formed by four atoms. The torsion angle defined by the i-j-k-l atom sequence is held constant throughout the simulation. Format Description D i j k l Fix the dihedral angle formed by atoms i , j , k , l D 1 2 3 6 This constrains the torsion angle along the 1-2-3-6 atom chain at its initial value.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#dihedral-constraints"},{"heading":"Scan Coordinates (S Command)","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":5,"text":"The S command defines an internal coordinate to be scanned over a range of values. It is used exclusively with #scan tasks. The scan systematically varies the specified coordinate from its initial value, stepping by a fixed increment for the requested number of steps. Relaxed scans optimize the remaining degrees of freedom at each scan point; rigid scans move the detected connected fragment to satisfy the target coordinate without optimization. Coordinate Type Format Description Bond length S i j step nsteps Scan the distance between atoms i and j Bond angle S i j k step nsteps Scan the angle at vertex j Dihedral angle S i j k l step nsteps Scan the torsion angle along i-j-k-l The step parameter specifies the increment per step (in Angstroms for bond lengths, degrees for angles and dihedrals). MAPLE writes the initial point plus each requested step, so one S line produces nsteps + 1 scan points. S 1 2 0.05 10 This scans the bond length between atoms 1 and 2 over 11 points: the initial geometry plus 10 increments of 0.05 Angstroms. S 2 1 3 10.0 6 This scans the bond angle at atom 1 (between atoms 2, 1, and 3) over 7 points: the initial angle plus 6 increments of 10 degrees. Tip You can define up to three S commands for 1D, 2D, or 3D scans. MAPLE varies all scan coordinates as a Cartesian-product grid across the combined coordinate space.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#scan-coordinates"},{"heading":"POST Command","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":6,"text":"The POST command allows you to load constraint definitions from an external file instead of listing them inline. This is useful when you have a large number of constraints or want to reuse the same constraint set across multiple calculations. POST /path/to/constraints.txt The external file should contain constraint commands (one per line) in the same format as inline constraints: C 1 C 2 B 3 7 A 4 5 6 D 1 2 3 4","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#post-command"},{"heading":"Examples","level":2,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":7,"text":"","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#examples"},{"heading":"Constrained optimization: freeze atoms and fix a bond","level":3,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":8,"text":"#model = uma #device = gpu0 #opt(method=lbfgs, level=tight) 0 1 C 0.000000 0.000000 0.000000 C 1.540000 0.000000 0.000000 O 2.340000 1.100000 0.000000 H -0.392000 1.011000 0.000000 H -0.392000 -0.506000 0.875000 H -0.392000 -0.506000 -0.875000 H 1.932000 -0.506000 0.875000 H 1.932000 -0.506000 -0.875000 C 3 B 1 2 Atom 3 (oxygen) is frozen and the C-C bond (atoms 1-2) is held at its initial distance while everything else optimizes.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#constrained-optimization-freeze-atoms-and-fix-a-bond"},{"heading":"Constrained optimization: fix a dihedral angle","level":3,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":9,"text":"#model = aimnet2 #device = gpu0 #opt(method=lbfgs) 0 1 C 0.000000 0.000000 0.000000 C 1.540000 0.000000 0.000000 C 2.100000 1.450000 0.000000 C 3.640000 1.450000 0.000000 H -0.392000 1.011000 0.000000 H -0.392000 -0.506000 0.875000 H 1.932000 -0.506000 0.875000 H 1.932000 -0.506000 -0.875000 H 1.700000 1.956000 0.875000 H 1.700000 1.956000 -0.875000 H 4.032000 0.944000 0.875000 H 4.032000 0.944000 -0.875000 H 4.032000 2.461000 0.000000 D 5 1 2 3 The dihedral angle along H(5)-C(1)-C(2)-C(3) is fixed at its initial value while the rest of the geometry relaxes.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#constrained-optimization-fix-a-dihedral-angle"},{"heading":"1D bond scan","level":3,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":10,"text":"Checked-in MAPLE example: examples/scan/C18.inp . The full coordinate block is kept in the source example; the scan command belongs after that coordinate block: #model=aimnet2nse #scan(mode=rigid) #device=gpu0 [XYZ coordinates from examples/scan/C18.inp] S 1 36 0.1 50 Scans the atom 1–36 distance over 51 points: the initial geometry plus 50 increments of 0.1 Angstroms.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#1d-bond-scan"},{"heading":"2D scan: two distance coordinates","level":3,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":11,"text":"Checked-in MAPLE example: examples/scan/da.inp . It defines a two-coordinate relaxed scan with the default L-BFGS method. The long coordinate block is omitted here, but the S commands must remain after it: #model=ANI-1xnr #scan #device=gpu0 [XYZ coordinates from examples/scan/da.inp] S 11 52 -0.1 15 S 14 51 -0.1 15 Each coordinate gives 16 values, producing a 256-point 2D potential energy surface.","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#2d-scan-two-distance-coordinates"},{"heading":"Using the POST command for external constraints","level":3,"page":"functions/constrain.html","page_entry":false,"page_role":"content","section_order":12,"text":"#model = uma #device = gpu0 #opt(method=lbfgs) XYZ /path/to/molecule.xyz POST /path/to/constraints.txt","title":"Constraints - MAPLE Documentation","trail":["Functions","Constraints"],"type":"Function","url":"functions/constrain.html#using-the-post-command-for-external-constraints"},{"heading":"Solvation","level":1,"page":"functions/solvent.html","page_entry":true,"page_role":"content","section_order":0,"text":"The #solv(...) command adds solvent treatment before the requested MAPLE task. Current MAPLE exposes two separate modes: an experimental implicit GB-polar/QEq energy correction, or a coordinate-building explicit solvent cluster. Choose one mode per input; implicit and explicit solvent options are intentionally mutually exclusive. Current scope Implicit solvation is experimental, energy-only, and currently valid only for #sp . Explicit solvent creates a non-periodic coordinate-only cluster around one input structure; it does not create a periodic box, cell metadata, or automatic frozen outer-shell constraints.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#solvation"},{"heading":"Overview","level":2,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":1,"text":"Mode Use Required syntax Task support Implicit GB-polar/QEq Single-point energy correction from geometry-dependent QEq charges and a heuristic GB-polar model #solv(method=gbsa, implicit=water, experimental=true) #sp only Explicit solvent cluster Build solvent coordinates from a pure-solvent PDB template around the solute #solv(explicit=water) Pre-processing step before the selected task Do not combine implicit=<solvent> and explicit=<solvent> in the same #solv line. Explicit-solvent geometry options such as radius , shape , density , number , solvent_pdb , and clash settings are rejected for implicit jobs.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#overview"},{"heading":"Implicit GB-polar/QEq","level":2,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":2,"text":"Implicit solvation uses method=gbsa with an implicit solvent name. MAPLE computes QEq charges for the current geometry and adds an experimental GB-polar energy term. Because the QEq charges are geometry-dependent and not variationally coupled to the solvent expression, solvent forces, Hessians, stress, and HVPs are disabled . #model = uma #solv(method=gbsa, implicit=water, experimental=true) #sp The experimental=true flag is required so the input states that this is an energy-only experimental correction. Use it for single-point energy comparisons, not optimization, MD, transition-state searches, scans that require solvent forces, or frequency calculations.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#implicit-gbqeq"},{"heading":"Implicit solvent names","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":3,"text":"acetone acetonitrile benzene cs2 dichloromethane dmf dmso ether methanol nhexan thf toluene trichloromethane water","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#implicit-solvent-names"},{"heading":"Explicit solvent clusters","level":2,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":4,"text":"Explicit solvation reads a pure-solvent PDB template, tiles it in space, crops whole solvent molecules to the requested cluster geometry, removes solute-solvent and solvent-solvent clashes, and appends the accepted solvent coordinates to the solute. The resulting ASE atoms are marked as a non-periodic coordinate-only cluster with pbc=False and a zero cell; MAPLE also writes solvated XYZ/PDB sidecars without a periodic cell record. #model = uma #solv(explicit=water, radius=12.0) #opt(method=lbfgs) Explicit solvation currently supports exactly one input structure. Remove #pbc for explicit-solvent jobs. If you need to hold solute atoms or selected solvent atoms fixed during an optimization, use the normal constraint commands after the coordinate block; the solvent builder itself only generates coordinates. For documentation previews, use the generated *_solvated.xyz sidecars directly. The figures below come from the source examples in examples/opt/exp-solv/ before any optimization frames are used. Example 1 — water sphere cluster from solv1_solvated.xyz . Example 2 — toluene sphere cluster from solv2_solvated.xyz . Example 1 cube variant — same solute, shape=cube , box_size=20.0 , default water density.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#explicit-clusters"},{"heading":"Bundled explicit-solvent templates","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":5,"text":"The current MAPLE source ships the following explicit-solvent PDB template stems. Use exactly the filename stem as the explicit= value: 2methyl2propanol 2methylpyridine 4methyl2pentanone aceticacid acetone acetonitrile acetophenone aniline anisole benzene benzonitrile benzylalcohol bromobenzene bromoethane bromoform bromooctane butanol butanone butylacetate butylbenzene carbontet chlorobenzene chloroform chlorohexane cyclohexane cyclohexanone decalin decane decanol dibromoethane dibutylether dichloroethane diethylamine diisopropylether dimethylacetamide dimethylformamide dimethylpyridine dimethylsulfoxide dodecane ethanol ether ethoxybenzene ethylacetate ethylbenzene fluorobenzene fluoroctane heptane heptanol hexadecane hexadecyliodide hexane hexanol iodobenzene isobutanol isooctane isopropanol isopropylbenzene isopropyltoluene mcresol mesitylene methanol methoxyethanol methylenechloride methylformamide nitrobenzene nitroethane nitromethane nonane nonanol octane octanol odichlorobenzene old_aceticacid old_tributylphosphate onitrotoluene pentadecane pentane pentanol perfluorobenzene phenylether propanol pyridine secbutanol secbutylbenzene tbutylbenzene tetrachloroethene tetrahydrofuran tetrahydrothiophenedioxide tetralin toluene tributylphosphate triethylamine trimethylbenzene undecane water xylene Two legacy duplicate template stems, old_aceticacid and old_tributylphosphate , are bundled files too; prefer aceticacid and tributylphosphate for new inputs.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#bundled-explicit-solvent-templates"},{"heading":"Templates with default density values","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":6,"text":"MAPLE has built-in density values for these explicit-solvent names when neither density= nor number= is supplied: aceticacid acetone acetonitrile aniline benzene butanol carbontet chloroform cyclohexane dichloroethane dimethylacetamide dimethylformamide dimethylsulfoxide ethanol ether ethylacetate heptane hexane isopropanol methanol methylenechloride nitrobenzene nitromethane octane propanol pyridine tetrahydrofuran toluene water xylene For bundled templates, use the template filename stem as the explicit= value. For example, the bundled water.pdb template is selected with explicit=water . If a solvent has no tabulated density, provide density=<g/mL> or number=<int> .","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#templates-with-default-density-values"},{"heading":"Custom solvent PDB templates","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":7,"text":"Use solvent_pdb=path/to/template.pdb to provide a custom solvent template. In this mode, solvent_pdb selects the actual PDB file, while explicit=<name> declares the solvent identity represented by that file. MAPLE does not infer the solvent name from the custom PDB filename. Relative solvent_pdb paths are resolved from the input file directory. For example, the following input reads boxes/water_bulk.pdb because that is the solvent_pdb path. The explicit=water part means “treat this template as water” for the default density lookup, output labels, and water-specific template checks; it is not derived from the filename water_bulk.pdb . #model = uma #solv(explicit=water, solvent_pdb=boxes/water_bulk.pdb, density=0.997, radius=14.0) #opt(method=lbfgs) A custom template must be a pure-solvent bulk PDB, group one connected solvent molecule per residue, use the same molecular formula for every residue, and contain an orthorhombic CRYST1 record. For explicit=water , each residue must be one H 2 O molecule. MAPLE unwraps molecules that cross an orthorhombic box boundary before validating connectivity, so GROMACS/OpenMM-style water boxes are acceptable when residue grouping remains correct. If the density implied by CRYST1 does not match MAPLE's default density for the declared explicit=<name> , MAPLE refuses to infer the target density; add an explicit density= matching the template, or use number= to bypass density inference and request an explicit molecule-count target.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#custom-solvent-pdb-templates"},{"heading":"Parameters","level":2,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":8,"text":"","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#parameters"},{"heading":"Mode selection","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":9,"text":"Parameter Mode Meaning method=gbsa Implicit Required when using implicit=<solvent> implicit=<solvent> Implicit Solvent name for the experimental GB-polar/QEq energy correction experimental=true Implicit Required acknowledgement that implicit solvation is experimental and energy-only explicit=<solvent> Explicit Bundled solvent template name, or density label when used with solvent_pdb solvent=<name> Compatibility alias Interpreted as implicit when method=gbsa is present, otherwise as explicit; prefer implicit= or explicit=","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#mode-selection"},{"heading":"Explicit cluster geometry and density","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":10,"text":"Parameter Default Description shape sphere sphere crops by molecular-center radius; cube crops by molecular-center box extent radius 10.0 Sphere radius in Angstroms; valid only with shape=sphere box_size required for cube Cube side length in Angstroms; valid only with shape=cube density tabulated if available Mass density in g/mL used to compute the target solvent molecule count density_scale 1.0 Multiplier applied to the density-derived target count number unset Explicit target solvent molecule count; overrides density-based targeting solvent_pdb bundled template Path to a homogeneous pure-solvent bulk PDB template; relative paths are resolved from the input file directory","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#explicit-cluster-geometry-and-density"},{"heading":"Explicit clash handling and output controls","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":11,"text":"Parameter Default Description clash_method vdw vdw removes atoms closer than scaled van der Waals radii; distance uses a fixed distance tolerance vdw_scale 0.57 Scale factor for vdW clash thresholds when clash_method=vdw vdw_fallback_radius 1.05 Fallback vdW radius in Angstroms for elements without a tabulated radius tolerance 2.0 Fixed-distance clash cutoff in Angstroms when clash_method=distance clash_cutoff alias for tolerance Compatibility name that selects clash_method=distance randomize true Randomize template phase and rigid rotation before tiling seed 0 Reproducible random seed; use seed=-1 for non-reproducible sampling write_shell false Write additional solute-centered shell sidecars when set to true shell_cutoff required with write_shell=true Keep whole solvent molecules whose closest atom is within this distance of the solute in the shell output","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#explicit-clash-handling-and-output-controls"},{"heading":"Examples","level":2,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":12,"text":"","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#examples"},{"heading":"Energy-only implicit water single point","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":13,"text":"#model = uma #device = gpu0 #solv(method=gbsa, implicit=water, experimental=true) #sp 0 1 C 0.000000 0.000000 0.000000 C 1.501000 0.000000 0.000000 O 2.098000 1.060000 0.000000 H -0.392000 1.011000 0.000000 H -0.392000 -0.506000 0.875000 H -0.392000 -0.506000 -0.875000 H 1.960000 -1.003000 0.000000","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#energy-only-implicit-water-single-point"},{"heading":"Explicit water cluster for optimization","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":14,"text":"#model = uma #device = gpu0 #solv(explicit=water, radius=10.0, seed=0) #opt(method=lbfgs, level=medium) 0 1 C 0.000000 0.000000 0.000000 C 1.501000 0.000000 0.000000 O 2.098000 1.060000 0.000000 H -0.392000 1.011000 0.000000 H -0.392000 -0.506000 0.875000 H -0.392000 -0.506000 -0.875000 H 1.960000 -1.003000 0.000000","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#explicit-water-cluster-for-optimization"},{"heading":"Cube-shaped explicit cluster with a target count","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":15,"text":"#model = uma #solv(explicit=water, shape=cube, box_size=20.0, number=120, clash_method=vdw) #sp XYZ /path/to/solute.xyz","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#cube-shaped-explicit-cluster-with-a-target-count"},{"heading":"Write a smaller analysis shell sidecar","level":3,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":16,"text":"#model = uma #solv(explicit=water, radius=14.0, write_shell=true, shell_cutoff=5.0) #sp XYZ /path/to/solute.xyz The main solvated coordinate sidecars contain the generated full cluster. With write_shell=true , MAPLE also writes smaller _cluster.xyz and _cluster.pdb files containing the solute plus whole solvent molecules within shell_cutoff .","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#write-a-smaller-analysis-shell-sidecar"},{"heading":"Limitations and best practices","level":2,"page":"functions/solvent.html","page_entry":false,"page_role":"content","section_order":17,"text":"Pick one solvent mode: use implicit GB-polar/QEq or explicit solvent coordinates, not both in one job. Treat implicit as energy-only: run it with #sp and experimental=true ; do not use it for jobs that need solvent forces or Hessians. Keep explicit clusters non-periodic: remove #pbc ; MAPLE does not write cell metadata for explicit clusters. Control density deliberately: use the default density table for common solvents, or specify density= / number= for custom templates and unusual solvent names. Prefer vdW clash filtering: the default clash_method=vdw is usually safer than a single fixed distance across all elements; use clash_method=distance only when you intentionally want a fixed cutoff. Validate custom templates: the template should be homogeneous pure solvent, have one connected molecule per residue, and include an orthorhombic CRYST1 box consistent with the density you request or the explicit number= target. Expect finite clusters: small unconstrained solvent clusters may move during optimization. Increase the radius/count, write an analysis shell, or add ordinary MAPLE constraints when a specific region must remain fixed.","title":"Solvation - MAPLE Documentation","trail":["Functions","Solvation"],"type":"Function","url":"functions/solvent.html#limitations-best-practices"},{"heading":"What is MAPLE?","level":2,"page":"general.html","page_entry":true,"page_role":"content","section_order":0,"text":"MAPLE (Machine-learning Potential for Landscape Exploration) is a computational chemistry software package designed for molecular modeling and quantum chemical calculations. It provides a unified computational environment suitable for research at different theoretical levels, from small molecules to complex reaction networks. MAPLE leverages modern machine learning potentials to achieve near-DFT accuracy at a fraction of the computational cost of traditional quantum mechanical methods. Its modular design allows users to perform a wide variety of calculations within a consistent framework, with flexible control over computational parameters and accuracy requirements. All energy values in MAPLE are expressed in Hartree , and all distances are expressed in Angstroms .","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#what-is-maple"},{"heading":"Supported ML Potentials","level":2,"page":"general.html","page_entry":false,"page_role":"content","section_order":1,"text":"MAPLE supports a wide range of machine learning interatomic potentials. Each model offers different trade-offs between speed, accuracy, and element coverage. Backend support for periodic cells, charge/multiplicity, Hessians, implicit solvent, D4, HVP, and checkpoint loading is model-specific; see the calculator backend matrix before choosing a production backend.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#ml-potentials"},{"heading":"UMA — Universal Model","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":2,"text":"Universal","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#uma-universal-model"},{"heading":"UMA","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":3,"text":"Universal Machine-learning Architecture from Meta. A foundation model covering broad chemical space with a single unified potential — the most general-purpose ML potential in MAPLE.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#uma"},{"heading":"ANI Family","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":4,"text":"ANI Family","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#ani-family-2"},{"heading":"ANI-2x","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":5,"text":"General-purpose neural network potential supporting H, C, N, O, S, F, Cl. Trained on DFT data with active learning. ANI Family","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#ani-2x"},{"heading":"ANI-1x","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":6,"text":"Neural network potential for organic molecules containing H, C, N, and O. Trained on the ANI-1x data set. ANI Family","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#ani-1x"},{"heading":"ANI-1ccx","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":7,"text":"Coupled-cluster accuracy neural network potential for H, C, N, O molecules. Transfer-learned from ANI-1x to CCSD(T)/CBS data. ANI Family","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#ani-1ccx"},{"heading":"ANI-1xnr","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":8,"text":"Non-reactive variant of ANI-1x optimized for stable molecular geometries and vibrational properties.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#ani-1xnr"},{"heading":"AIMNet Family","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":9,"text":"AIMNet","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#aimnet-family-2"},{"heading":"AIMNet2","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":10,"text":"Atoms-in-Molecules network potential with broad element coverage and high accuracy for organic and drug-like molecules. AIMNet","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#aimnet2"},{"heading":"AIMNet2-NSE","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":11,"text":"Open-shell variant using neural spin-charge equilibration for systems with arbitrary charge and spin multiplicity, including radicals.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#aimnet2-nse"},{"heading":"FeNNol Family","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":12,"text":"FeNNol","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#fennol-family-2"},{"heading":"FeNNix-Bio1","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":13,"text":"Ion-aware FeNNix-Bio .fnx model series for biomolecular and molecular-cluster calculations, available in small and medium variants.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#fennix-bio1"},{"heading":"MACE Family","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":14,"text":"MACE","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#mace-family-2"},{"heading":"MACE-OFF23 (s/m/l)","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":15,"text":"Equivariant message-passing potentials for organic molecules. Available in small, medium, and large variants balancing speed and accuracy. MACE","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#mace-off23-s-m-l"},{"heading":"MACE-OMol","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":16,"text":"MACE potential trained on the OMol25 data set for broad organic molecular coverage with high accuracy. MACE","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#mace-omol"},{"heading":"EGRET","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":17,"text":"Equivariant graph neural network potential designed for reactive and non-reactive molecular simulations.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#egret"},{"heading":"Computational Capabilities","level":2,"page":"general.html","page_entry":false,"page_role":"content","section_order":18,"text":"MAPLE provides a comprehensive suite of computational chemistry methods, all driven by machine learning potentials for fast evaluation on GPU hardware.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#capabilities"},{"heading":"Supported Task Types","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":19,"text":"sp","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#task-types"},{"heading":"Single Point","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":20,"text":"Compute molecular energies and properties at fixed geometries. freq","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#single-point"},{"heading":"Frequency","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":21,"text":"Normal mode analysis, RRHO thermochemistry, and IR spectra via mass-weighted Hessian diagonalization. opt","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#frequency"},{"heading":"Optimization","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":22,"text":"Locate equilibrium geometries with L-BFGS, RFO, steepest descent, conjugate gradient, DIIS, or bracketing L-BFGS. ts","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#optimization"},{"heading":"Transition State","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":23,"text":"Saddle point search via NEB, CI-NEB, P-RFO, Dimer, Growing String, or AutoNEB methods. scan","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#transition-state"},{"heading":"PES Scan","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":24,"text":"1D, 2D, or 3D relaxed or rigid scans along chosen internal coordinates. irc","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#pes-scan"},{"heading":"IRC","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":25,"text":"Intrinsic reaction coordinate with GS, LQA, HPC, and EulerPC integrators. parmfit","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#irc"},{"heading":"ParmFit","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":26,"text":"Force-field parameterization for ligand/cofactor refinement, noncanonical amino-acid templates, and metal-site parameters.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#parmfit"},{"heading":"Additional Features","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":27,"text":"Function","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#additional-features"},{"heading":"Solvation","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":28,"text":"Experimental implicit solvent single-point energies and non-periodic explicit solvent clusters. Function","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#solvation"},{"heading":"Constraints","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":29,"text":"Fix atoms, bonds, angles, and dihedral angles during optimization and scanning. Runtime","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#constraints"},{"heading":"GPU Acceleration","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":30,"text":"CUDA acceleration for ML potential evaluation when the selected backend and runtime support GPU execution. Correction","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#gpu-acceleration"},{"heading":"D4 Dispersion","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":31,"text":"DFT-D4 dispersion correction for ANI-backed calculations where the calculator supports the D4 option. Reference","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#d4-dispersion"},{"heading":"Calculator Matrix","level":3,"page":"general.html","page_entry":false,"page_role":"content","section_order":32,"text":"Compare PBC, charge/spin, Hessian, solvent, D4, HVP, and model-file support across MAPLE backends.","title":"About MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE","About MAPLE"],"type":"Guide","url":"general.html#calculator-matrix"},{"heading":"MAPLE","level":1,"page":"index.html","page_entry":true,"page_role":"landing","section_order":0,"text":"Machine-learning Potential for Landscape Exploration A fast, GPU-accelerated computational chemistry toolkit that combines state-of-the-art machine learning potentials with practical workflows for structures, energies, reaction paths, and molecular landscapes. Get Started Documentation Download Ĥψ = Eψ E = ∫ ρ(r) V(r) dr F = −∇E","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#maple"},{"heading":"What is MAPLE?","level":2,"page":"index.html","page_entry":false,"page_role":"landing","section_order":1,"text":"MAPLE is a next-generation computational chemistry toolkit designed to make machine learning potentials practical and powerful for real-world research. By uniting accurate ML models, GPU acceleration, and an integrated workflow, MAPLE enables rapid and reliable exploration of molecular systems—from small molecules to complex landscapes. Open Source GPU Accelerated ML Powered Cross Platform Core features","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#what-is-maple"},{"heading":"Built for practical molecular landscape exploration","level":2,"page":"index.html","page_entry":false,"page_role":"landing","section_order":2,"text":"MAPLE brings the original toolkit highlights back to the front: models, optimization, transition states, reaction paths, spectra, scans, solvation, and GPU acceleration.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#feature-showcase-heading"},{"heading":"ML Potentials","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":3,"text":"Support for ANI, AIMNet2, MACE-OFF, UMA, and more, with backend-specific capabilities documented in the calculator matrix.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#ml-potentials"},{"heading":"Geometry Optimization","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":4,"text":"L-BFGS, RFO, steepest descent, conjugate gradient, DIIS, and bracketing L-BFGS methods.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#geometry-optimization"},{"heading":"Transition States","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":5,"text":"NEB, CI-NEB, P-RFO, Dimer, Growing String, AutoNEB methods for saddle point search.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#transition-states"},{"heading":"Reaction Paths","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":6,"text":"IRC with GS, LQA, HPC, and EulerPC integrators. Verify TS connectivity to reactants and products.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#reaction-paths"},{"heading":"Vibrational Analysis","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":7,"text":"Normal mode analysis, RRHO thermochemistry, IR spectra. Mass-weighted Hessian diagonalization.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#vibrational-analysis"},{"heading":"PES Scanning","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":8,"text":"1D, 2D, or 3D relaxed or rigid scans. Map energy landscapes along chosen coordinates.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#pes-scanning"},{"heading":"Solvation","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":9,"text":"Experimental implicit single-point solvent energies and non-periodic explicit solvent clusters.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#solvation"},{"heading":"GPU Accelerated","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":10,"text":"CUDA support for ML potential evaluation. Orders of magnitude faster than traditional QM.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#gpu-accelerated"},{"heading":"More Coming Soon","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":11,"text":"Additional features are actively under development. Stay tuned for future releases.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#more-coming-soon"},{"heading":"Supported ML Potentials","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":12,"text":"MAPLE integrates leading machine learning potentials to cover a broad range of systems. UMA — Universal UMA ANI ANI-2x ANI-1x ANI-1ccx ANI-1xnr AIMNet AIMNet2 AIMNet2-NSE FeNNol FeNNix-Bio1 MACE MACE-OFF23 MACE-OMol EGRET","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#supported-ml-potentials"},{"heading":"Computational Capabilities","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":13,"text":"Powerful tools for exploring structures, energies, and reaction pathways. Single Point Frequency Optimization Transition State PES Scan IRC ParmFit","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#computational-capabilities"},{"heading":"Additional Features","level":3,"page":"index.html","page_entry":false,"page_role":"landing","section_order":14,"text":"Advanced options that enhance control, accuracy, and performance. Solvation Constraints GPU Acceleration D4 Dispersion Calculator Matrix Latest updates","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#additional-features"},{"heading":"Articles & News","level":2,"page":"index.html","page_entry":false,"page_role":"landing","section_order":15,"text":"Recent publications and release milestones from the MAPLE project. View all news September 14, 2026 · ChemRxiv ParmFit preprint available on ChemRxiv MLIP-driven fitting of fast, accurate AMBER/GAFF-compatible precise force fields. August 10, 2026 MAPLE v0.1.5 released ParmFit workflows, Direct MaxFlux transition-state searches, and FeNNol/FeNNix-Bio1 support. June 4, 2026 MAPLE v0.1.4 released Standardized optimization, expanded SCAN methods, calculator plugins, and explicit-solvent tools. April 30, 2026 · Chemical Science MAPLE published in Chemical Science An MLFF-native platform for automated reaction modeling and enzyme design.","title":"MAPLE — Machine-learning Potential for Landscape Exploration","trail":["MAPLE"],"type":"Guide","url":"index.html#latest-news-heading"},{"heading":"How to Report an Issue","level":2,"page":"issues.html","page_entry":true,"page_role":"content","section_order":0,"text":"We use GitHub Issues to track bugs, feature requests, and questions. Reporting through GitHub keeps reports visible to the community and makes it easy for the development team to respond. Open an Issue on GitHub → Tip Before opening a new issue, search existing issues to check if your problem has already been reported. This avoids duplicates and may lead you to a solution faster.","title":"Report an Issue — MAPLE","trail":["MAPLE","Report an Issue"],"type":"Guide","url":"issues.html#how-to-report"},{"heading":"What to Include in a Bug Report","level":3,"page":"issues.html","page_entry":false,"page_role":"content","section_order":1,"text":"A good bug report helps us reproduce and fix the problem quickly. Please include: MAPLE version — run: python -c \"import maple; print(maple.__version__)\" Python version — run: python --version Operating system — e.g., Ubuntu 22.04, CentOS 8, macOS 14. GPU and CUDA version — run: nvidia-smi Input file — the .inp file (or a minimal reproduction) that triggers the issue. Full error message — the complete traceback or error output. Expected behavior — what you expected to happen. Actual behavior — what actually happened.","title":"Report an Issue — MAPLE","trail":["MAPLE","Report an Issue"],"type":"Guide","url":"issues.html#what-to-include"},{"heading":"Bug Report Template","level":3,"page":"issues.html","page_entry":false,"page_role":"content","section_order":2,"text":"Copy this template, fill in the placeholders, and paste it into your GitHub issue: Title: <one-line summary of the problem> Description: <describe what you were trying to do and what went wrong> MAPLE version: <e.g., 0.1.3> Python: <e.g., 3.11.5> OS: <e.g., Ubuntu 22.04> GPU / CUDA: <e.g., NVIDIA A100, CUDA 12.1> Input file: <paste the full .inp file, or a minimal reproduction> Error: <paste the complete traceback or error output> Expected behavior: <what you expected to happen> Actual behavior: <what actually happened> Note For general usage questions, check the tutorials and task reference pages first — many common questions are already answered there.","title":"Report an Issue — MAPLE","trail":["MAPLE","Report an Issue"],"type":"Guide","url":"issues.html#template"},{"heading":"Feature Requests","level":2,"page":"issues.html","page_entry":false,"page_role":"content","section_order":3,"text":"We welcome suggestions for new features and improvements. When submitting a feature request, please describe: The problem you are trying to solve or the workflow you want to improve. Your proposed solution or the behavior you would like to see. Any alternatives you have considered.","title":"Report an Issue — MAPLE","trail":["MAPLE","Report an Issue"],"type":"Guide","url":"issues.html#feature-requests"},{"heading":"Calculator Backends & Capability Matrix","level":1,"page":"setup/calculators.html","page_entry":true,"page_role":"content","section_order":0,"text":"This page summarizes the calculator layer documented for the MAPLE 0.1.4 development branch. It is a development capability guide, not a public release announcement. Use it to choose a backend and to understand the protocol expected from new calculators. Development note Backend capability gates are enforced before or during calculator construction: periodic inputs fail fast for molecular wrappers, unsupported Hessian modes are rejected, and typoed backend options fail loudly for shipped calculators.","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#calculator-backends-capability-matrix"},{"heading":"Backend Capability Matrix","level":2,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":1,"text":"Molecular / HVP","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#capability-matrix"},{"heading":"ANI","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":2,"text":"ani2x ani1x ani1ccx ani1xnr PBC no Charge no D4 yes HVP gas-phase PBC No; periodic atoms fail fast. Charge / mult No; values are not honored by the backend. Hessian Analytic and numerical (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is supported. Model files MAPLE-hosted checkpoints auto-download; explicit model_path is accepted. Charged molecules","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#ani"},{"heading":"AIMNet2","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":3,"text":"aimnet2 aimnet2nse PBC no Charge yes D4 no HVP no PBC No; periodic atoms fail fast. coulomb_method=ewald is disabled. Charge / mult Yes. Hessian Analytic and numerical (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is not supported. Model files MAPLE-hosted checkpoints auto-download; explicit model_path is accepted. FeNNol","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#aimnet2"},{"heading":"FeNNol","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":4,"text":"fennix-bio1s fennix-bio1m fennol(model_path=...) PBC no Charge singlet D4 no HVP yes PBC No; periodic atoms fail fast. Charge / mult FeNNix-Bio1 supports total charge from the coordinate block; external models may or may not honor charge. Multiplicity must be 1 . Hessian Analytic and numerical (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is not supported. Model files Built-in FeNNix-Bio .fnx files are resolved from MAPLE's model directory; generic fennol requires explicit model_path . Molecular MACE","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#fennol"},{"heading":"MACE-OFF / EGRET","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":5,"text":"maceoff23s maceoff23m maceoff23l egret PBC no Charge no D4 no HVP no PBC No; periodic atoms fail fast. Charge / mult No. Hessian Analytic and numerical (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is not supported. Model files maceoff23m and egret can auto-download; maceoff23s and maceoff23l require a local file or model_path . MACE-OMol","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#mace-off-egret"},{"heading":"MACE-OMol","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":6,"text":"maceomol PBC no Charge no D4 no HVP no PBC No; periodic atoms fail fast. Charge / mult No. Hessian Analytic and numerical (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is not supported. Model files Requires a local checkpoint in the model directory or explicit model_path . Development backend","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#mace-omol"},{"heading":"MACE-Polar","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":7,"text":"macepols macepolm macepoll PBC no Charge yes D4 no HVP no PBC No; periodic atoms fail fast. No external-field interface is exposed. Charge / mult Yes; multiplicity is converted to unpaired-electron spin as mult - 1 . Hessian Analytic and numerical (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is not supported. Model files Requires a local checkpoint in the model directory or explicit model_path . Periodic / FAIR-Chem","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#mace-polar"},{"heading":"UMA","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":8,"text":"uma PBC yes Charge omol D4 no HVP no PBC Yes through FAIR-Chem. Non-periodic input uses omol ; periodic input must specify a non- omol task. Stress / virial requests are rejected until validated. Charge / mult omol only; non- omol tasks reject non-default charge / multiplicity. FAIR-Chem receives spin multiplicity as mult . Hessian Numerical only (gas phase). Implicit-solvent Hessians are unsupported. Solvent / D4 Experimental GBSA, energy-only; D4 is not supported. Model files Resolved from checkpoint_path , a local maple/function/calculator/model/uma-*.pt file, or FAIR-Chem's official loading path.","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#uma"},{"heading":"Selection Rules","level":2,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":9,"text":"Periodic materials or catalysis: use uma and set an explicit FAIR-Chem task such as omat , oc20 , oc22 , oc25 , omc , or odac . Do not request stress or virial output yet. Charged or open-shell molecules: use aimnet2 for molecular systems, or uma with the omol task. Treat charged/open-shell UMA chemistry as a result to verify against references. D4 dispersion: use ANI. Other shipped backends reject or ignore D4 because it is not part of their MAPLE calculator contract. HVP-enabled Dimer: ANI and FeNNol are the shipped backends with get_hvp() , and both are gas-phase only. If a selected backend lacks HVP support, use a different transition-state method or a future finite-difference Dimer path once validated. Implicit-solvent Hessians: GBSA Hessians (analytic or numerical) are not supported; Hessians are available only in gas phase.","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#selection-rules"},{"heading":"Developer Backend Contract","level":2,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":10,"text":"MAPLE calculators are registered classes that satisfy a small ASE-style protocol. A backend does not have to inherit the shared base class as long as it exposes the same public surface and class attributes. Authoring source of truth This page is a website summary. The full developer checklist and runnable template live in the MAPLE source tree at maple/function/calculator/AUTHORING.md .","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#calculator-contract"},{"heading":"Registration is required","level":3,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":11,"text":"A custom calculator is not selectable by #model=... until its class is registered. Define lowercase MODEL_NAMES keys and decorate the class with @register_calculator ; plugin loading only imports the module so this registration code can run. from maple.function.calculator import CalcABC, register_calculator @register_calculator class MyCalculator(CalcABC): MODEL_NAMES = (\"mymodel\",) MODEL_ENERGY_UNIT = \"eV\" SUPPORTED_HESSIAN_MODES = (\"numerical\",) SUPPORTS_CHARGE_MULT = False SUPPORTS_PBC = False CHECKPOINT_FILENAME = None REQUIRES_LOCAL_MODEL_FILE = True OPTION_KEYS = () MODEL_PATH_OPTION = \"model_path\" Surface Contract calculate(atoms, properties, system_changes) ASE entry point. Store energy, free energy, forces, and optional Hessian in results through the shared finalization path where possible. get_hessian(atoms, delta=0.002) Returns a (3N, 3N) array in Hartree / Å². Numerical mode uses the shared finite-difference helper; analytic mode is backend-specific. get_hvp(atoms, n) Optional. Implement only for the HVP-enabled Dimer path and return (Hn, forces, energy) in Hartree units. The default raises NotImplementedError . MODEL_NAMES Lowercase registry keys. Duplicate registration is a real error and raises instead of overwriting. MODEL_ENERGY_UNIT Declare eV or hartree honestly. _finalize_results performs the energy/force conversion; custom calculators should not multiply by EV2HARTREE in the calculate path. SUPPORTED_HESSIAN_MODES Subset of analytic and numerical . Unsupported requested modes fail before production work begins. SUPPORTS_CHARGE_MULT / SUPPORTS_PBC Declare whether the backend honors charge / multiplicity and validated periodic inputs. Do not mark PBC true unless the backend builds a validated periodic graph or neighbor list. CHECKPOINT_FILENAME / REQUIRES_LOCAL_MODEL_FILE Tell the factory whether MAPLE can auto-download a checkpoint or must require a local file. OPTION_KEYS / MODEL_PATH_OPTION Reject misspelled backend options loudly, and route explicit user model paths to the constructor kwarg that actually consumes them.","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#registration-required"},{"heading":"Plugin Discovery and Model Paths","level":2,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":12,"text":"Input header: #model=mymodel(module=my_lab.maple_plugin, model_path=/tmp/m.pt) imports the plugin module, which must register a calculator class for mymodel , then passes the explicit model path through the backend contract. Environment variable: MAPLE_CALCULATOR_PLUGINS=my_lab.maple_plugin,other.plugin imports plugin modules once per process before calculator construction; each module must run its own @register_calculator registrations. Python entry points: [project.entry-points.\"maple.calculators\"] is documented as a preview shape for future packagers, not a current discovery layer.","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#plugin-discovery"},{"heading":"Energy API Migration","level":2,"page":"setup/calculators.html","page_entry":false,"page_role":"content","section_order":13,"text":"The old backend-specific calc.get_energy(...) entry points are not part of the public calculator API. Downstream code should use ASE's standard pattern: atoms.calc = calc energy = atoms.get_potential_energy() This keeps energy access consistent across backends whose legacy get_energy signatures did not agree.","title":"Calculator Backends - MAPLE Documentation","trail":["ML Models","Calculator Backends"],"type":"Setup","url":"setup/calculators.html#energy-migration"},{"heading":"Part II: Coordinate Input","level":1,"page":"setup/coordinates.html","page_entry":true,"page_role":"content","section_order":0,"text":"The coordinate section of a MAPLE input file defines the molecular geometry. Coordinates are specified in Cartesian format (Angstroms) and can be provided either inline within the input file or loaded from external files. An optional charge and multiplicity line may precede the atomic coordinates.","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#part-ii-coordinate-input"},{"heading":"Inline Coordinates","level":2,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":1,"text":"The simplest way to provide molecular geometry is to include Cartesian coordinates directly in the input file. Each atom is given on its own line with the element symbol followed by the x, y, and z coordinates in Angstroms. An optional first line specifying charge and multiplicity can precede the coordinate block. If omitted, MAPLE assumes a neutral singlet (charge=0, multiplicity=1).","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#inline-coordinates"},{"heading":"Basic format (neutral singlet assumed)","level":3,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":2,"text":"#model = ani2x #opt H 0.000000 0.000000 0.000000 O 0.000000 0.000000 0.960000 H 0.000000 0.757160 1.197280","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#basic-format-neutral-singlet-assumed"},{"heading":"With charge and multiplicity","level":3,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":3,"text":"#model = uma #opt 0 1 C 0.000000 0.000000 0.000000 C 1.540000 0.000000 0.000000 H -0.392000 1.011000 0.000000 H -0.392000 -0.506000 0.875000 H -0.392000 -0.506000 -0.875000 H 1.932000 0.506000 0.875000 H 1.932000 0.506000 -0.875000 H 1.932000 -1.011000 0.000000 Tip The charge/multiplicity line must contain exactly two integers separated by whitespace. MAPLE distinguishes this line from coordinate data by checking whether the first token is an element symbol or an integer.","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#with-charge-and-multiplicity"},{"heading":"External XYZ Files","level":2,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":4,"text":"For larger molecules or when reusing geometries across calculations, you can load coordinates from an external XYZ file using the XYZ keyword followed by the file path. #model = aimnet2 #opt(method=lbfgs, level=tight) XYZ /path/to/molecule.xyz You can also specify the charge and multiplicity before the XYZ line: #model = uma #freq -1 1 XYZ /path/to/anion.xyz The external XYZ file should follow the standard XYZ format: 3 Water molecule O 0.000000 0.000000 0.117300 H 0.000000 0.757160 -0.469200 H 0.000000 -0.757160 -0.469200","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#external-xyz"},{"heading":"Trajectory Files","level":2,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":5,"text":"For tasks that require multiple geometries (such as NEB or string methods for transition state searches), you can provide a trajectory file containing a sequence of structures using the XYZTRAJ keyword. #model = uma #ts(method=neb) XYZTRAJ /path/to/trajectory.xyz The trajectory file is a concatenation of standard XYZ frames. Each frame begins with the atom count, followed by a comment line and then the coordinate block: 3 Frame 1 - Reactant O 0.000000 0.000000 0.117300 H 0.000000 0.757160 -0.469200 H 0.000000 -0.757160 -0.469200 3 Frame 2 - Product O 0.000000 0.000000 0.117300 H 0.000000 0.900000 -0.350000 H 0.000000 -0.900000 -0.350000","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#trajectory-files"},{"heading":"Post-Processing Commands","level":2,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":6,"text":"After the coordinate block, you can add post-processing commands to apply constraints or define scan coordinates. These commands modify how specific internal coordinates are treated during the calculation. See the Constraints page for full details. Command Format Description C C i Fix the position of atom i (freeze in place) B B i j Fix the bond distance between atoms i and j A A i j k Fix the bond angle formed by atoms i , j , k D D i j k l Fix the dihedral angle formed by atoms i , j , k , l S S i j step nsteps Define a scan coordinate along atoms i , j (bond), i j k (angle), or i j k l (dihedral)","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#post-processing"},{"heading":"Example with constraints","level":3,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":7,"text":"#model = uma #opt(method=lbfgs) 0 1 C 0.000000 0.000000 0.000000 C 1.540000 0.000000 0.000000 O 2.340000 1.100000 0.000000 H -0.392000 1.011000 0.000000 H -0.392000 -0.506000 0.875000 H 1.932000 -0.506000 0.875000 C 3 B 1 2 In this example, atom 3 (oxygen) is frozen in place and the bond between atoms 1 and 2 (C-C) is constrained at its initial distance during optimization.","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#example-with-constraints"},{"heading":"Example with scan coordinate","level":3,"page":"setup/coordinates.html","page_entry":false,"page_role":"content","section_order":8,"text":"Checked-in MAPLE example: examples/scan/C18.inp . The full C18 coordinates are in that file; the scan coordinate is a post-processing line after the coordinates: #model=aimnet2nse #scan(mode=rigid) #device=gpu0 [XYZ coordinates from examples/scan/C18.inp] S 1 36 0.1 50 This scans the distance between atoms 1 and 36 over 51 points: the initial geometry plus 50 increments of 0.1 Angstroms.","title":"Coordinates - MAPLE Documentation","trail":["Input Setup","Coordinates"],"type":"Setup","url":"setup/coordinates.html#example-with-scan-coordinate"},{"heading":"AIMNet2","level":1,"page":"setup/model_aimnet.html","page_entry":true,"page_role":"content","section_order":0,"text":"AIMNet2 is a neural network potential that provides broad element coverage (14 elements) with ωB97M-D3BJ accuracy. It is a molecular, no-PBC backend that supports charge and multiplicity for charged or open-shell molecules.","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#aimnet2"},{"heading":"Variants","level":2,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":1,"text":"Model Keyword Elements Description AIMNet2 aimnet2 H, B, C, N, O, F, Si, P, S, Cl, As, Se, Br, I Standard variant with ωB97M-D3BJ accuracy AIMNet2-NSE aimnet2nse H, B, C, N, O, F, Si, P, S, Cl, As, Se, Br, I Open-shell variant using neural spin-charge equilibration for systems with arbitrary charge and spin multiplicity, including radicals.","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#variants"},{"heading":"Charge and Spin Support","level":2,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":2,"text":"AIMNet2 natively handles charged species and different spin multiplicities. Specify charge and multiplicity in the coordinate block: #model = aimnet2 #opt ( method = lbfgs ) -1 1 C 0.000000 0.000000 0.000000 O 1.250000 0.000000 0.000000 O -1.250000 0.000000 0.000000 The first line specifies charge multiplicity (here: charge = −1, multiplicity = 1 for a formate anion).","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#charge-spin"},{"heading":"Energy-only Implicit Solvation","level":2,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":3,"text":"AIMNet2 can use MAPLE's experimental implicit GB-polar/QEq correction for single-point energies. Add experimental=true and use #sp ; solvent forces, optimizations, Hessians, and frequency workflows are not supported for this correction. #model = aimnet2 #solv ( method = gbsa , implicit = water , experimental = true ) #sp -1 1 C 0.000000 0.000000 0.000000 O 1.250000 0.000000 0.000000 O -1.250000 0.000000 0.000000","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#solvation"},{"heading":"Calculator Capabilities","level":2,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":4,"text":"Hessian: analytic and numerical Hessians are available in gas phase. Implicit-solvent Hessians (analytic or numerical) are not supported. PBC: AIMNet2 is a no-PBC wrapper in MAPLE. Periodic atoms fail fast, and coulomb_method=ewald is disabled until validated cell/PBC/MIC support exists. HVP: AIMNet2 does not implement get_hvp() ; use non-HVP transition-state workflows such as P-RFO, NEB, or String instead. Model files: MAPLE can auto-download AIMNet2 checkpoints from the MAPLE model repository, or you can provide an explicit model_path . Supported Coulomb options are simple and dsf .","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#calculator-capabilities"},{"heading":"Usage Examples","level":2,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":5,"text":"","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#examples"},{"heading":"Optimization with heavy elements (Br, I)","level":3,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":6,"text":"#model = aimnet2 #device = gpu0 #opt ( method = lbfgs ) 0 1 C 0.000000 0.000000 0.000000 Br 1.940000 0.000000 0.000000 H -0.390000 0.000000 1.028000 H -0.390000 0.890000 -0.514000 H -0.390000 -0.890000 -0.514000","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#optimization-with-heavy-elements-br-i"},{"heading":"NSE variant using neural spin-charge equilibration","level":3,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":7,"text":"#model = aimnet2nse #device = gpu0 #opt ( method = lbfgs ) 0 1 C 0.000000 0.000000 0.000000 I 2.140000 0.000000 0.000000 H -0.390000 0.000000 1.028000 H -0.390000 0.890000 -0.514000 H -0.390000 -0.890000 -0.514000","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#nse-variant-using-neural-spin-charge-equilibration"},{"heading":"Limitations","level":2,"page":"setup/model_aimnet.html","page_entry":false,"page_role":"content","section_order":8,"text":"No D4 dispersion. The ωB97M-D3BJ training already includes dispersion corrections. No periodic systems. AIMNet2 does not support periodic boundary conditions. 14 elements only. Systems with elements outside the supported set (e.g., transition metals) require uma instead.","title":"AIMNet2 - MAPLE Documentation","trail":["ML Models","AIMNet2"],"type":"Setup","url":"setup/model_aimnet.html#limitations"},{"heading":"ANI Models","level":1,"page":"setup/model_ani.html","page_entry":true,"page_role":"content","section_order":0,"text":"The ANI (Accurate NeurAl networK engINe for Molecular Energies) family is a set of neural network potentials developed by the Roitberg group. ANI models are among the fastest ML potentials available, making them ideal for high-throughput screening and rapid prototyping of neutral organic molecular systems.","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#ani-models"},{"heading":"Available Variants","level":2,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":1,"text":"Model Keyword Elements Training Level Best For ANI-2x ani2x H, C, N, O, F, S, Cl ωB97X / 6-31G(d) General organic chemistry with halogens ANI-1x ani1x H, C, N, O ωB97X / 6-31G(d) Fast calculations on HCNO-only systems ANI-1ccx ani1ccx H, C, N, O CCSD(T)/CBS (transfer-learned) Publication-quality accuracy for small molecules ANI-1xnr ani1xnr H, C, N, O ωB97X / 6-31G(d) (non-reactive) Equilibrium geometries without bond-breaking","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#variants"},{"heading":"DFT-D4 Dispersion Correction","level":2,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":2,"text":"ANI models are the only models in MAPLE that support the DFT-D4 dispersion correction. D4 adds London dispersion (van der Waals) interactions, which is critical for non-covalent binding, molecular stacking, and conformational energetics. #model = ani2x #d4 #opt ( method = lbfgs ) Tip Always enable #d4 when studying systems with significant non-covalent interactions (hydrogen bonds, pi-stacking, host-guest complexes). The computational overhead is minimal.","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#d4-dispersion"},{"heading":"Calculator Capabilities","level":2,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":3,"text":"Hessian: analytic and numerical Hessians are available in gas phase. Implicit-solvent Hessians (analytic or numerical) are not supported. HVP: ANI is the only shipped backend that implements get_hvp() for the HVP-enabled Dimer path. ANI HVP is gas-phase only. Implicit solvent: MAPLE's experimental GB-polar/QEq correction is energy-only ( #sp with experimental=true ); solvent forces, HVP, and Hessians are not supported. Model files: MAPLE can auto-download ANI checkpoints from the MAPLE model repository, or you can provide an explicit model_path .","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#calculator-capabilities"},{"heading":"Usage Examples","level":2,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":4,"text":"","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#examples"},{"heading":"General organic optimization","level":3,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":5,"text":"#model = ani2x #device = gpu0 #opt ( method = lbfgs ) 0 1 C 0.000000 0.000000 0.000000 O 1.200000 0.000000 0.000000 H -0.540000 0.940000 0.000000 H -0.540000 -0.940000 0.000000","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#general-organic-optimization"},{"heading":"High-accuracy with coupled-cluster potential","level":3,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":6,"text":"#model = ani1ccx #device = gpu0 #opt ( method = lbfgs , level = extratight ) 0 1 O 0.000000 0.000000 0.117300 H 0.000000 0.756900 -0.469200 H 0.000000 -0.756900 -0.469200","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#high-accuracy-with-coupled-cluster-potential"},{"heading":"With D4 dispersion for non-covalent interactions","level":3,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":7,"text":"#model = ani2x #d4 #device = gpu0 #opt ( method = lbfgs , level = tight ) XYZ /path/to/dimer_complex.xyz","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#with-d4-dispersion-for-non-covalent-interactions"},{"heading":"Limitations","level":2,"page":"setup/model_ani.html","page_entry":false,"page_role":"content","section_order":8,"text":"No charge/multiplicity support. ANI models assume neutral, singlet ground state; use AIMNet2 or UMA omol for charged/open-shell inputs. Limited elements. ANI-2x covers 7 elements; ANI-1x/1ccx/1xnr cover only H, C, N, O. No periodic systems. ANI models do not support periodic boundary conditions. Implicit solvation is energy-only. MAPLE's experimental GB-polar/QEq correction can be requested for #sp with experimental=true ; solvent forces, optimization, MD, TS, scan, and frequency workflows remain unsupported for that correction.","title":"ANI Models - MAPLE Documentation","trail":["ML Models","ANI"],"type":"Setup","url":"setup/model_ani.html#limitations"},{"heading":"Bring Your Own Model","level":1,"page":"setup/model_custom.html","page_entry":true,"page_role":"content","section_order":0,"text":"MAPLE is not limited to its shipped backends. You can plug in your own machine-learning potential — trained in your group, exported as a TorchScript .pt / .jpt or an ordinary PyTorch .pt / .model checkpoint — without editing MAPLE's source code . A custom backend is just a small Python class that exposes a few methods; once registered, it works with every task (single point, optimization, frequency, TS search, IRC, scan, MD). Before you start This is the hands-on tutorial. The reference contract (full capability matrix, every class attribute, plugin-discovery internals) lives on the Calculator Backends page. A complete, copy-runnable example ships in the repository at examples/calculator_plugin/ .","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#bring-your-own-model"},{"heading":"How it works","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":1,"text":"If you already have a FeNNix .fnx file, use the FeNNol model page instead of writing a Python plugin. For Python plugin calculators, two header keys do all the wiring: module= — the import path of your plugin file/package. MAPLE imports it, which runs the @register_calculator decorator and adds your model name to the registry. model_path= — the checkpoint file MAPLE validates (it must exist) and hands to your class. Your code decides how to load it — this is where your .pt / .jpt / .model comes in. #model = mymodel ( module = my_lab.maple_plugin , model_path = /abs/path/model.jpt ) #sp #device = cpu","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#how-it-works"},{"heading":"Step 1 — Write the backend class","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":2,"text":"A backend inherits CalcABC and declares its capabilities as class attributes. You fill in three things: (a) the capability attributes, (b) how to load your model in __init__ , and (c) the forward pass in _forward . Everything else — unit conversion, implicit-solvent hook, results bookkeeping, the analytic-Hessian loop — is handled for you. import numpy as np import torch from ase.calculators.calculator import all_changes from maple.function.calculator.calculator_base import ( CalcABC, EV2HARTREE, hessian_via_double_autograd, register_calculator, ) @register_calculator class MyCalculator(CalcABC): # (a) Capability declaration, read by the factory before construction MODEL_NAMES = ('mymodel',) # input-header routing keys, lowercase MODEL_ENERGY_UNIT = 'eV' # 'eV' or 'hartree' -- declare honestly SUPPORTED_HESSIAN_MODES = ('analytic', 'numerical') SUPPORTS_CHARGE_MULT = False SUPPORTS_PBC = False # fail-fast on periodic atoms CHECKPOINT_FILENAME = None # no HuggingFace auto-download REQUIRES_LOCAL_MODEL_FILE = False OPTION_KEYS = () # extra model_options keys you accept MODEL_PATH_OPTION = 'model_path' # kwarg that consumes model_path implemented_properties = ['energy', 'forces', 'free_energy', 'hessian'] @classmethod def build_kwargs_from_options(cls, model, options, *, resolved_model_path=None): # Route the factory-resolved checkpoint path into __init__ kwargs kwargs = {} if resolved_model_path is not None: kwargs['model_path'] = resolved_model_path return kwargs def __init__(self, device, model='mymodel', *, model_path=None, implicit='none', solvent='none', **_ignored): super().__init__() self.device = device self.dtype = torch.float64 self.hessian = 'analytic' # (b) Load YOUR model here -- see Step 2 self.model = load_my_model(model_path, device) # Keep this hook (no-op unless implicit='gbsa') self.implicit_solv_init(implicit=implicit, solvent=solvent) # (c) Single private forward: atoms -> scalar energy (in MODEL_ENERGY_UNIT) def _forward(self, atoms, *, requires_grad): positions = torch.tensor( atoms.get_positions(), dtype=self.dtype, device=self.device, requires_grad=requires_grad, ) numbers = torch.tensor(atoms.get_atomic_numbers(), dtype=torch.long, device=self.device) energy_eV = self.model(numbers, positions) # YOUR forward signature return energy_eV, positions def calculate(self, atoms=None, properties=['energy'], system_changes=all_changes): properties = self._normalize_properties(properties) atoms = super().calculate(atoms, properties, system_changes) # PBC/solvent guards needs_forces = 'forces' in properties energy_eV, positions = self._forward(atoms, requires_grad=needs_forces) forces_np = None if needs_forces: forces = -torch.autograd.grad(energy_eV, positions)[0] forces_np = forces.detach().cpu().numpy() hessian = None if 'hessian' in properties: hessian = self.get_hessian(atoms) # _finalize_results owns eV->Hartree + solvent + writing self.results. # Do NOT multiply by EV2HARTREE yourself in this path. self._finalize_results(atoms, energy=energy_eV.item(), forces=forces_np, hessian=hessian) def _analytic_hessian(self, atoms) -> np.ndarray: # The Hessian path converts units itself: multiply by EV2HARTREE here. energy_eV, positions = self._forward(atoms, requires_grad=True) return hessian_via_double_autograd(lambda: energy_eV * EV2HARTREE, positions) The unit rule Declare MODEL_ENERGY_UNIT honestly and let _finalize_results convert the calculate() path to Hartree. Never multiply by EV2HARTREE yourself in calculate() . The Hessian path is the one exception — it converts internally, so you multiply by EV2HARTREE inside _analytic_hessian .","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#step1"},{"heading":"Step 2 — Load your model file","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":3,"text":"MAPLE hands you a validated, existing file path; how you turn it into a model object is entirely yours. The two common formats:","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#step2"},{"heading":"TorchScript ( .pt / .jpt )","level":3,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":4,"text":"If your model was saved with torch.jit.script / trace , load it directly — this matches MAPLE's shipped ANI/MACE/AIMNet2 backends: def load_my_model(model_path, device): model = torch.jit.load(model_path, map_location=device).eval() for p in model.parameters(): p.requires_grad_(False) return model","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#torchscript-pt-jpt"},{"heading":"Plain checkpoint / state_dict ( .pt / .model )","level":3,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":5,"text":"For an ordinary (non-scripted) PyTorch model, rebuild the architecture and load weights: def load_my_model(model_path, device): ckpt = torch.load(model_path, map_location=device, weights_only=False) net = MyNetwork(**ckpt['hparams']) # your nn.Module net.load_state_dict(ckpt['state_dict']) net = net.to(device).double().eval() for p in net.parameters(): p.requires_grad_(False) return net","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#plain-checkpoint-state-dict-pt-model"},{"heading":"Step 3 — Run it","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":6,"text":"Make your plugin importable (put its directory on PYTHONPATH or install it as a package), then point an input file at it. The example below mirrors examples/calculator_plugin/sp_jit.inp : #model = mymodel ( module = my_calculator_plugin , model_path = model.jpt ) #sp #device = cpu 0 1 O 0.000 0.000 0.000 H 0.960 0.000 0.000 H -0.240 0.930 0.000 export PYTHONPATH=\"$PWD:$PYTHONPATH\" maple sp.inp # -> Energy: ... Hartree The same backend now works for any task — just change the task header: #model = mymodel ( module = my_calculator_plugin , model_path = model.jpt ) #opt ( method = lbfgs ) #device = gpu0 XYZ /path/to/molecule.xyz","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#step3"},{"heading":"Alternative: register process-wide","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":7,"text":"Instead of repeating module= in every input, register the plugin once via an environment variable. MAPLE imports each listed module at start-up: export MAPLE_CALCULATOR_PLUGINS=my_calculator_plugin,other_lab.plugin After this, #model=mymodel(model_path=...) resolves without the module= key.","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#registering"},{"heading":"Capability checklist","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":8,"text":"Set each attribute to what your model actually supports — MAPLE enforces them so misuse fails loudly instead of producing wrong numbers: Attribute Set to MODEL_NAMES Your lowercase header keyword(s), e.g. ('mymodel',) MODEL_ENERGY_UNIT 'eV' or 'hartree' — your model's native energy unit SUPPORTS_PBC True only if you build a validated periodic graph; otherwise False (periodic atoms fail fast) SUPPORTS_CHARGE_MULT True if you honor atoms.info['charge'] / ['mult'] SUPPORTED_HESSIAN_MODES ('analytic', 'numerical') , ('numerical',) , etc. MODEL_PATH_OPTION 'model_path' so an explicit checkpoint path is accepted Numerical Hessian for free If your model cannot autodiff a Hessian, set SUPPORTED_HESSIAN_MODES = ('numerical',) and omit _analytic_hessian . CalcABC provides a finite-difference Hessian that only needs your calculate() forces. Frequency and P-RFO still work.","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#checklist"},{"heading":"See also","level":2,"page":"setup/model_custom.html","page_entry":false,"page_role":"content","section_order":9,"text":"Runnable example: examples/calculator_plugin/ — two complete backends (TorchScript and torch.load ), a toy-model builder, and ready input files. Calculator Backends — the full developer contract, capability matrix, and plugin-discovery layers. maple/function/calculator/AUTHORING.md and CALCULATOR_REVIEW.md in the source tree.","title":"Custom Model - MAPLE Documentation","trail":["ML Models","Custom Model"],"type":"Setup","url":"setup/model_custom.html#more"},{"heading":"FeNNol Models","level":1,"page":"setup/model_fennol.html","page_entry":true,"page_role":"content","section_order":0,"text":"FeNNol (Force-field-enhanced Neural Networks optimized library) is MAPLE's framework for FENNIX-format .fnx machine-learning potential files. MAPLE ships the FeNNix-Bio1 family of foundation models for condensed-phase biomolecular simulations, and also supports loading external .fnx models through model_path . Runtime note FeNNol uses a JAX/Flax runtime for .fnx programs and does not use the PyTorch calculator runtime. GPU execution, when available, is controlled by the installed JAX runtime and its platform configuration.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#fennol-models"},{"heading":"FeNNix-Bio1 Family","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":1,"text":"FeNNix-Bio1 is a family of scalable foundation models for reactive condensed-phase molecular dynamics, built on the FeNNol library within the Jax framework. Two sizes are available with different accuracy and throughput trade-offs: Model Keyword Best For FeNNix-Bio1S fennix-bio1s Light-weight high-throughput model for rapid screening FeNNix-Bio1M fennix-bio1m Higher-accuracy model for production-quality condensed-phase simulations Important The medium variant ( fennix-bio1m ) requires more computational resources than the small variant. Start with fennix-bio1s for high-throughput screening and switch to fennix-bio1m for production-quality simulations.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#fennix-bio1"},{"heading":"External .fnx Models","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":2,"text":"Use the generic fennol keyword to load an external .fnx model file. This works with any valid .fnx program. #model = fennol ( model_path = /path/to/model.fnx ) #sp XYZ /path/to/structure.xyz The generic fennol keyword always requires model_path . The element coverage, cutoff, and energy terms are determined by the supplied .fnx program.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#external-fnx"},{"heading":"Model Files","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":3,"text":"The built-in FeNNix-Bio1 checkpoints are resolved from MAPLE's model directory: fennix-bio1s → fennix-bio1S-finetuneIons.fnx fennix-bio1m → fennix-bio1M-finetuneIons.fnx The generic fennol keyword requires an explicit model_path pointing to a valid .fnx file.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#model-files"},{"heading":"Model Options","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":4,"text":"Option Default Description model_path built-in for fennix-bio1s / fennix-bio1m Path to an external .fnx file. Required for #model=fennol . use_float64 false Enable JAX float64 execution when tighter numerical precision is needed.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#parameters"},{"heading":"Charge and Multiplicity","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":5,"text":"Charge support in FeNNol depends on the loaded .fnx model architecture. The FeNNix-Bio1 family supports total molecular charge from the coordinate block and passes it to the FENNIX charge model. External .fnx models may or may not support charge — consult the model's documentation. The current MAPLE runtime has no spin/multiplicity input, so multiplicity must always be 1 regardless of the model. #model = fennix-bio1s #opt ( method = lbfgs ) 0 1 C 0.000000 0.000000 0.000000 O 1.230000 0.000000 0.000000 H -0.540000 0.940000 0.000000 H -0.540000 -0.940000 0.000000","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#charge-spin"},{"heading":"Calculator Capabilities","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":6,"text":"Units: FeNNol models commonly report energies in eV internally; MAPLE converts final energies and forces to Hartree and Hartree per Angstrom. Hessian: analytic and numerical Hessians are available in gas phase. Implicit-solvent Hessians are not supported. HVP: FeNNol implements get_hvp() in gas phase, which can be used by HVP-enabled workflows. PBC: FeNNol is exposed as a no-PBC molecular calculator in MAPLE. Periodic atoms fail fast. Solvent / D4: MAPLE's experimental GB-polar/QEq correction is energy-only ( #sp with experimental=true ); D4 is not supported for FeNNol.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#calculator-capabilities"},{"heading":"Usage Examples","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":7,"text":"","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#examples"},{"heading":"High-throughput screening with FeNNix-Bio1S","level":3,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":8,"text":"#model = fennix-bio1s #device = gpu0 #opt ( level = loose ) XYZ /path/to/structure.xyz","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#high-throughput-screening-with-fennix-bio1s"},{"heading":"Production-quality simulation with FeNNix-Bio1M","level":3,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":9,"text":"#model = fennix-bio1m #device = gpu0 #opt ( method = lbfgs , level = tight ) XYZ /path/to/structure.xyz","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#production-quality-simulation-with-fennix-bio1m"},{"heading":"Load an external .fnx model","level":3,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":10,"text":"#model = fennol ( model_path = /path/to/custom_model.fnx , use_float64 = true ) #sp XYZ /path/to/structure.xyz","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#load-an-external-fnx-model"},{"heading":"Limitations","level":2,"page":"setup/model_fennol.html","page_entry":false,"page_role":"content","section_order":11,"text":"No periodic systems. The FeNNol wrapper rejects PBC inputs. Singlet multiplicity only. Total charge may be supported depending on the model, but multiplicity must always be 1 . Runtime-specific GPU behavior. FeNNol GPU execution depends on the installed JAX build and platform configuration. External model coverage is model-defined. MAPLE can load a valid .fnx file, but the chemistry supported by that file is determined by its training and program contents.","title":"FeNNol - MAPLE Documentation","trail":["ML Models","FeNNol"],"type":"Setup","url":"setup/model_fennol.html#limitations"},{"heading":"MACE & EGRET Models","level":1,"page":"setup/model_mace.html","page_entry":true,"page_role":"content","section_order":0,"text":"MACE (Multi-ACE) is a family of equivariant message-passing neural network potentials that achieves excellent accuracy through higher-order many-body interactions. EGRET is a related graph-based equivariant model with competitive accuracy for drug-like molecules. The MAPLE hand-wrapped MACE and EGRET backends are molecular no-PBC calculators.","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#mace-egret-models"},{"heading":"MACE-OFF23 Family","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":1,"text":"The MACE-OFF23 models are trained on the SPICE dataset for organic molecules containing H, C, N, O, F, S, Cl. Three sizes are available with increasing accuracy and cost: Model Keyword Parameters Best For MACE-OFF23 (Small) maceoff23s ~0.5M Fast screening, large systems, speed-critical workflows MACE-OFF23 (Medium) maceoff23m ~2M Balanced speed/accuracy for production calculations MACE-OFF23 (Large) maceoff23l ~8M Publication-quality results, final geometries Important maceoff23l requires significantly more GPU memory than the smaller variants. If you encounter out-of-memory errors, switch to maceoff23m or maceoff23s , or use #device=cpu .","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#mace-off23"},{"heading":"MACE-OMol","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":2,"text":"MACE-OMol extends element coverage beyond OFF23, supporting 17 elements including alkali and alkaline earth metals: Elements: H, Li, B, C, N, O, F, Na, Mg, Si, P, S, Cl, K, Ca, Br, I #model = maceomol #device = gpu0 #opt ( method = lbfgs ) 0 1 Li 0.000000 0.000000 0.000000 F 1.570000 0.000000 0.000000","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#mace-omol"},{"heading":"EGRET","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":3,"text":"EGRET is a graph-based equivariant model with competitive accuracy for drug-like molecules. It covers the same elements as MACE-OFF23 (H, C, N, O, F, S, Cl). #model = egret #device = gpu0 #opt ( method = lbfgs ) XYZ /path/to/drug_molecule.xyz","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#egret"},{"heading":"Model Files","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":4,"text":"MAPLE can auto-download maceoff23m and egret checkpoints from the MAPLE model repository. maceoff23s , maceoff23l , maceomol , and the MACE-Polar development backends require a local checkpoint in maple/function/calculator/model/ or an explicit model_path .","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#model-files"},{"heading":"Calculator Capabilities","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":5,"text":"Hessian: analytic and numerical Hessians are available in gas phase. Implicit-solvent Hessians (analytic or numerical) are not supported. Implicit solvent: MAPLE's experimental GB-polar/QEq correction is energy-only ( #sp with experimental=true ); solvent forces and Hessians are not supported. PBC and stress: the MAPLE MACE wrappers build no-PBC molecular graphs and do not provide validated stress or virial output. HVP: MACE and EGRET do not implement get_hvp() . MACE-Polar: development keywords macepols , macepolm , and macepoll support charge/multiplicity through spin = mult - 1 , but remain no-PBC and local-checkpoint backends.","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#calculator-capabilities"},{"heading":"Usage Examples","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":6,"text":"","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#examples"},{"heading":"Quick screening with MACE-OFF23 Small","level":3,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":7,"text":"#model = maceoff23s #device = gpu0 #opt ( level = loose ) XYZ /path/to/molecule.xyz","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#quick-screening-with-mace-off23-small"},{"heading":"Publication-quality optimization with MACE-OFF23 Large","level":3,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":8,"text":"#model = maceoff23l #device = gpu0 #opt ( method = lbfgs , level = tight ) XYZ /path/to/optimized_guess.xyz","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#publication-quality-optimization-with-mace-off23-large"},{"heading":"Frequency calculation","level":3,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":9,"text":"#model = maceoff23m #device = gpu0 #freq XYZ /path/to/optimized_geometry.xyz","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#frequency-calculation"},{"heading":"CPU fallback for large systems","level":3,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":10,"text":"#model = maceoff23s #device = cpu #opt ( level = loose ) XYZ /path/to/large_system.xyz","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#cpu-fallback-for-large-systems"},{"heading":"Limitations","level":2,"page":"setup/model_mace.html","page_entry":false,"page_role":"content","section_order":11,"text":"No charge/multiplicity support for MACE-OFF, MACE-OMol, or EGRET. Use AIMNet2, UMA omol , or a validated MACE-Polar checkpoint for charged/open-shell molecular inputs. No D4 dispersion. D4 correction is not available for MACE or EGRET models. No periodic systems. These wrappers do not support periodic boundary conditions; periodic atoms fail fast. Limited elements. MACE-OFF23 and EGRET cover 7 elements; MACE-OMol covers 17 elements. For broader coverage, use uma .","title":"MACE & EGRET - MAPLE Documentation","trail":["ML Models","MACE & EGRET"],"type":"Setup","url":"setup/model_mace.html#limitations"},{"heading":"UMA — Universal Models for Atoms","level":1,"page":"setup/model_uma.html","page_entry":true,"page_role":"content","section_order":0,"text":"UMA is a family of universal machine-learning interatomic potentials developed by Meta's FAIR Chemistry team. Trained on approximately 500 million unique 3D atomic structures spanning molecules, materials, and catalysts, UMA is designed to serve as a single universal model that handles diverse chemical domains without requiring fine-tuning. MAPLE defaults to the small UMA v1.1 checkpoint ( uma-s-1p1 ) for compatibility. You can explicitly select newer or larger checkpoints, choose the FAIR Chemistry inference interface for speed-critical GPU workloads, or provide a checkpoint through checkpoint_path .","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#uma-universal-models-for-atoms"},{"heading":"Configuration","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":1,"text":"Basic usage with all defaults (task = inferred from the system, size = uma-s-1p1 , inference = default ): #model = uma Specify task and/or size explicitly: #model = uma ( task = omat , size = uma-s-1p2 ) The task , size , and inference parameters are optional and can be used independently: # Only change task (size stays at default uma-s-1p1) #model = uma ( task = oc20 ) # Only change size (task remains auto-selected) #model = uma ( size = uma-m-1p1 ) # Only change the FAIR Chemistry inference interface #model = uma ( inference = turbo )","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#configuration"},{"heading":"Model Sizes","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":2,"text":"Three checkpoints are available, offering different tradeoffs between speed and accuracy: Checkpoint Version Active Params Total Params Notes uma-s-1p2 v1.2 6.6M ~150M Latest and fastest; ~50% faster, ~40% more accurate than v1.1 on molecular benchmarks uma-s-1p1 v1.1 6.6M ~150M Default. Compatibility-first small checkpoint uma-m-1p1 v1.1 ~50M ~1.4B Higher accuracy across all benchmarks; slower and more GPU memory Tip The default uma-s-1p1 is the compatibility-first choice. Select uma-s-1p2 when you want the newer v1.2 checkpoint, or uma-m-1p1 when you need higher accuracy and can tolerate slower evaluation.","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#model-sizes"},{"heading":"Inference Interface","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":3,"text":"The inference option selects the FAIR Chemistry inference interface used by UMA. The MAPLE input keyword is inference ; \"interface\" here describes the backend path being selected. Mode Use case Notes default General-purpose calculations and CPU runs Default. Safest for short jobs and changing-composition workflows. turbo CUDA runs with repeated fixed-composition evaluations Opt-in fast path for workloads such as NEB, TS, and frequency calculations; short jobs may not recover the startup cost. # Explicitly request the CUDA turbo inference interface #model = uma ( inference = turbo ) #device = gpu0 # Combine task, size, and inference options #model = uma ( task = omat , size = uma-s-1p2 , inference = turbo ) Note On CPU, MAPLE falls back to inference=default even if turbo is requested, because the turbo path depends on CUDA-oriented FAIR Chemistry kernels.","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#inference-interface"},{"heading":"Task Domains","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":4,"text":"UMA is a multi-task model trained on different DFT methodologies. The task parameter selects which domain-specific head to use, matching the DFT level of theory for your system type: Task Domain DFT Method Typical Applications omol Organic Molecules ωB97M-V / def2-TZVPD Drug design, polymers, biochemistry omat Inorganic Materials PBE / PBE+U Photovoltaics, batteries, superconductors oc20 Heterogeneous Catalysis RPBE Fuel cells, renewable energy, surface reactions odac MOFs / Direct Air Capture PBE+D3 Carbon capture, gas adsorption, porous materials omc Molecular Crystals PBE+D3 Organic electronics, pharmaceutical crystals oc22 Oxide Catalysis PBE+U (spin-polarized) Oxide surfaces, electrocatalysis on oxides oc25 Electrolyte Interfaces RPBE+D3 Electrochemistry, solid-liquid interfaces Important The oc22 and oc25 tasks are only available with UMA v1.2 checkpoints ( uma-s-1p2 ). Using these tasks with v1.1 checkpoints will result in an error.","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#task-domains"},{"heading":"Charge and Spin","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":5,"text":"UMA supports charge and spin multiplicity for the omol task. Specify them in the coordinate block: #model = uma #opt ( method = lbfgs ) -1 2 O 0.000000 0.000000 0.000000 O 1.210000 0.000000 0.000000 The first line of the coordinate block is charge multiplicity (here: charge = −1, multiplicity = 2 for a doublet superoxide anion). Warning Charge and spin are only accepted for the omol task. Other tasks (materials, catalysis) reject non-default charge or multiplicity. Treat charged/open-shell UMA results as values that need reference validation.","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#charge-spin"},{"heading":"PBC and Stress","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":6,"text":"UMA is the only shipped MAPLE backend that supports periodic boundary conditions. Non-periodic systems use the molecular omol task by default; periodic systems must select an explicit non- omol task such as omat , oc20 , oc22 , oc25 , omc , or odac . Important MAPLE currently rejects UMA stress and virial requests until stress-unit conversion is validated. Use UMA PBC for energies and forces, not for production stress/NPT claims.","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#pbc-and-stress"},{"heading":"Usage Examples","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":7,"text":"","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#examples"},{"heading":"Default: molecular geometry optimization","level":3,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":8,"text":"# Default: uma-s-1p1 checkpoint, omol task for this molecular system #model = uma #device = gpu0 #opt ( method = lbfgs ) 0 1 C 0.000000 0.000000 0.000000 O 1.200000 0.000000 0.000000 H -0.540000 0.940000 0.000000 H -0.540000 -0.940000 0.000000","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#default-molecular-geometry-optimization"},{"heading":"Inorganic material optimization (omat)","level":3,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":9,"text":"#model = uma ( task = omat ) #device = gpu0 #opt ( method = lbfgs ) XYZ /path/to/material.xyz","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#inorganic-material-optimization-omat"},{"heading":"Catalysis with medium model for higher accuracy","level":3,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":10,"text":"#model = uma ( task = oc20 , size = uma-m-1p1 ) #device = gpu0 #opt ( method = lbfgs ) XYZ /path/to/catalyst_surface.xyz","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#catalysis-with-medium-model-for-higher-accuracy"},{"heading":"Molecular crystal with v1.1 fallback","level":3,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":11,"text":"#model = uma ( task = omc , size = uma-s-1p1 ) #device = gpu0 #opt ( method = lbfgs ) XYZ /path/to/crystal.xyz","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#molecular-crystal-with-v1-1-fallback"},{"heading":"Transition state search with UMA","level":3,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":12,"text":"#model = uma #device = gpu0 #ts ( method = neb ) XYZ /path/to/reactant.xyz XYZ /path/to/product.xyz","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#transition-state-search-with-uma"},{"heading":"With energy-only implicit solvation","level":3,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":13,"text":"#model = uma #device = gpu0 #solv ( method = gbsa , implicit = water , experimental = true ) #sp 0 1 C 0.000000 0.000000 0.000000 O 1.200000 0.000000 0.000000 H -0.540000 0.940000 0.000000 H -0.540000 -0.940000 0.000000","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#with-energy-only-implicit-solvation"},{"heading":"Compatibility Notes","level":2,"page":"setup/model_uma.html","page_entry":false,"page_role":"content","section_order":14,"text":"D4 dispersion: Not supported with UMA. The model's training data already includes dispersion-corrected DFT for relevant tasks (PBE+D3 for omc, odac, oc25). Experimental implicit solvation: Available for energy-only #sp calculations with #solv(method=gbsa, implicit=<solvent>, experimental=true) . Solvent forces, Hessians, optimization, MD, TS, scan, and frequency workflows are disabled for this correction. All MAPLE job types are compatible with UMA without implicit solvent: single point, optimization, transition state search, IRC, frequency, PES scan, and molecular dynamics. Hessian-vector products: UMA does not implement get_hvp() ; use a non-HVP transition-state path or a backend that implements HVP. UMA inference interface: use inference=turbo only when you explicitly want the CUDA fast path; otherwise keep the default interface. Requires a FAIR-Chem release with UMA support, installed after the PyTorch build that matches your CPU/CUDA runtime.","title":"UMA - MAPLE Documentation","trail":["ML Models","UMA"],"type":"Setup","url":"setup/model_uma.html#compatibility"},{"heading":"Machine Learning Potentials","level":1,"page":"setup/models.html","page_entry":true,"page_role":"landing","section_order":0,"text":"MAPLE uses machine learning interatomic potentials (MLIPs) to compute energies and forces instead of traditional quantum mechanical methods. This approach provides near-DFT accuracy at a fraction of the computational cost, enabling rapid geometry optimizations, frequency calculations, and molecular dynamics simulations. The #model command in the settings block selects which potential to use.","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#machine-learning-potentials"},{"heading":"Available Models","level":2,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":1,"text":"The table below lists the primary user-facing machine learning potentials in MAPLE, along with their keyword, element coverage, and accuracy characteristics. For periodic, charge/spin, Hessian, solvent, D4, HVP, and development backends such as MACE-Polar, see the calculator backend capability matrix . Model Name Keyword Supported Elements Accuracy ANI-2x ani2x H, C, N, O, F, S, Cl Trained on wB97X/6-31G(d); good general-purpose accuracy for organic molecules. Details → ANI-1x ani1x H, C, N, O Trained on wB97X/6-31G(d); limited to four elements but well-validated ANI-1ccx ani1ccx H, C, N, O Transfer-learned to CCSD(T)/CBS; high accuracy for small organic molecules ANI-1xnr ani1xnr H, C, N, O Non-reactive variant of ANI-1x; trained without bond-breaking data AIMNet2 aimnet2 H, B, C, N, O, F, Si, P, S, Cl, As, Se, Br, I Broad element coverage with wB97M-D3BJ accuracy; supports charged species. Details → AIMNet2-NSE aimnet2nse H, B, C, N, O, F, Si, P, S, Cl, As, Se, Br, I Open-shell variant using neural spin-charge equilibration for systems with arbitrary charge and spin multiplicity, including radicals. FeNNix-Bio1S fennix-bio1s H, Li, B, C, N, O, F, Na, Mg, Si, P, S, Cl, K, Ca, Br, I, Zn Small FeNNix-Bio .fnx model for fast biomolecular and molecular-cluster calculations. FeNNix-Bio1M fennix-bio1m H, Li, B, C, N, O, F, Na, Mg, Si, P, S, Cl, K, Ca, Br, I, Zn Medium FeNNix-Bio .fnx model for higher-capacity biomolecular calculations. External .fnx fennol(model_path=...) Whatever the supplied .fnx model supports Load another FeNNix .fnx model through MAPLE's JAX/Flax runtime. MACE-OFF23 (Small) maceoff23s H, C, N, O, F, S, Cl Fast equivariant model; suitable for quick screening of organic molecules. Details → MACE-OFF23 (Medium) maceoff23m H, C, N, O, F, S, Cl Balanced speed and accuracy for organic chemistry applications MACE-OFF23 (Large) maceoff23l H, C, N, O, F, S, Cl Highest accuracy MACE-OFF variant; recommended for publication-quality results MACE-OMol maceomol H, Li, B, C, N, O, F, Na, Mg, Si, P, S, Cl, K, Ca, Br, I Extended organic-molecular MACE model; broader element support than OFF23 EGRET egret H, C, N, O, F, S, Cl Graph-based equivariant model; competitive accuracy for drug-like molecules UMA uma Broad periodic table coverage (83+ elements) Universal model from Meta FAIR; supports 7 task domains, 3 model sizes, and inference=default|turbo . Details → Your own model module=... Whatever your model supports Plug in your own TorchScript or PyTorch checkpoint ( .pt / .jpt / .model ) with no source edits. Tutorial →","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#available-models"},{"heading":"Model Selection Guide","level":2,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":2,"text":"Choosing the right model depends on your molecular system, required accuracy, and available computational resources. Here are general recommendations: Organic molecules (H, C, N, O only): Start with ani2x for general use or ani1ccx when coupled-cluster accuracy is needed for small molecules. Organic molecules with halogens (F, S, Cl): Use ani2x , maceoff23m , or egret . For the highest accuracy, try maceoff23l . Systems with heavier elements (Br, I, P, Si, etc.): Use aimnet2 or maceomol , which support a broader range of elements. Diverse or unknown systems: Use uma as a reliable general-purpose potential with the widest element coverage. Specify a task domain for best accuracy. Periodic materials / catalysis: Use uma with an explicit periodic-capable task such as omat , oc20 , oc22 , oc25 , omc , or odac . Stress and virial output are not yet validated. Charged or open-shell molecules: Use aimnet2 or uma with the omol task. Molecular wrappers such as ANI and MACE-OFF do not honor charge or multiplicity. Speed-critical workflows: Use maceoff23s or ani2x for the fastest evaluation times. The ANI models are particularly fast on GPUs. Publication-quality results: Use maceoff23l or ani1ccx for the highest available accuracy within their element ranges.","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#model-selection"},{"heading":"Physical Corrections","level":2,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":3,"text":"ML potentials can be augmented with physical corrections to improve accuracy for specific interactions that are challenging for neural network models. Support is backend-specific; do not assume a correction is available for every model.","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#physical-corrections"},{"heading":"DFT-D4 Dispersion Correction","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":4,"text":"The D4 dispersion correction adds London dispersion interactions (van der Waals forces) to the ML potential energy. In the current MAPLE calculator layer, D4 is supported for ANI backends only. #model = ani2x #d4 #opt","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#d4-dispersion"},{"heading":"Experimental Implicit Solvation","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":5,"text":"MAPLE's current implicit solvent path is an experimental GB-polar/QEq correction for single-point energies. It is configured through the #solv command with method=gbsa , an implicit solvent name, and experimental=true . See the Solvation page for details. #model = uma #solv(method=gbsa, implicit=water, experimental=true) #sp","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#gbsa-solvation"},{"heading":"QEq Charges","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":6,"text":"The charge equilibration (QEq) method computes atomic partial charges used internally by the experimental implicit solvent correction. QEq charges are computed automatically when implicit solvation is enabled and do not require a separate command. Important Large models such as maceoff23l and maceomol require significantly more GPU memory than smaller models. If you encounter out-of-memory errors, try switching to a smaller model variant (e.g., maceoff23s ) or use #device = cpu for systems that exceed your GPU memory.","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#qeq-charges"},{"heading":"Usage Examples","level":2,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":7,"text":"Below are complete input file examples demonstrating model selection for various scenarios.","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#usage-examples"},{"heading":"General-purpose optimization with UMA (default: small v1.1 checkpoint, omol task)","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":8,"text":"# Uses uma-s-1p1 checkpoint and default inference interface #model = uma #opt ( method = lbfgs , level = tight ) 0 1 C 0.000000 0.000000 0.000000 O 1.200000 0.000000 0.000000 H -0.540000 0.940000 0.000000 H -0.540000 -0.940000 0.000000","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#general-purpose-optimization-with-uma-default-small-v1-1-checkpoint-omol-task"},{"heading":"UMA for inorganic materials (omat task)","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":9,"text":"#model = uma ( task = omat ) #opt ( method = lbfgs ) XYZ /path/to/material.xyz","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#uma-for-inorganic-materials-omat-task"},{"heading":"UMA with CUDA turbo inference","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":10,"text":"# Opt in to the FAIR Chemistry turbo inference interface for repeated GPU evaluations #model = uma ( inference = turbo ) #ts ( method = neb ) XYZ /path/to/reactant.xyz XYZ /path/to/product.xyz","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#uma-with-cuda-turbo-inference"},{"heading":"Charged-molecule calculation with AIMNet2","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":11,"text":"#model = aimnet2 #opt(method=lbfgs, level=extratight) -1 1 C 0.000000 0.000000 0.000000 O 1.250000 0.000000 0.000000 O -1.250000 0.000000 0.000000","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#charged-molecule-calculation-with-aimnet2"},{"heading":"Frequency calculation with MACE-OFF23","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":12,"text":"#model = maceoff23m #freq XYZ /path/to/optimized_geometry.xyz","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#frequency-calculation-with-mace-off23"},{"heading":"CPU-based calculation for large systems","level":3,"page":"setup/models.html","page_entry":false,"page_role":"landing","section_order":13,"text":"#model = maceoff23s #device = cpu #opt(level=loose) XYZ /path/to/large_molecule.xyz","title":"ML Models - MAPLE Documentation","trail":["Input Setup","ML Models"],"type":"Setup","url":"setup/models.html#cpu-based-calculation-for-large-systems"},{"heading":"Part I: Settings Block","level":1,"page":"setup/settings.html","page_entry":true,"page_role":"content","section_order":0,"text":"MAPLE input files ( .inp ) begin with a settings block that configures the calculation type, selects the machine learning potential model, specifies the computational device, and sets global options. All control commands in this block start with the # symbol. During input processing, these commands are parsed first to determine the calculation task and its parameter settings. Tip If the input file does not define any task type, MAPLE automatically performs a single point energy calculation ( sp ) using default settings. Parameters left unspecified within any task command will also use their defaults.","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#part-i-settings-block"},{"heading":"Header Commands","level":2,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":1,"text":"The following header commands control the core behavior of a MAPLE calculation. Each command begins with # and can appear in any order within the settings block.","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#header-commands"},{"heading":"#model","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":2,"text":"Specifies the machine learning potential model used for the calculation. See the ML Models page for a complete list of supported potentials and guidance on choosing one. #model = ani2x #model = uma #model = aimnet2 #model = maceoff23m","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#model"},{"heading":"#opt","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":3,"text":"Requests a geometry optimization. Parameters such as the optimization method and convergence level can be supplied in parentheses. #opt #opt(method=lbfgs) #opt(method=lbfgs, level=tight)","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#opt"},{"heading":"#ts","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":4,"text":"Requests a transition state search. The method parameter is required; convergence levels and method-specific refinement keywords can also be supplied in parentheses. #ts(method=prfo) #ts(method=neb, level=tight, refine=nebts) #ts(method=string, refine=stringts)","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#ts"},{"heading":"#freq","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":5,"text":"Requests a vibrational frequency calculation. This computes the Hessian matrix and derives harmonic frequencies, zero-point energy, and thermochemical properties. #freq","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#freq"},{"heading":"#irc","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":6,"text":"Requests an intrinsic reaction coordinate (IRC) calculation, tracing the minimum energy path from a transition state toward reactants and products. #irc #irc(method=gs, direction=both) #irc(method=lqa, steps=50)","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#irc"},{"heading":"#scan","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":7,"text":"Requests a potential energy surface (PES) scan along one to three internal coordinates. Scan coordinates are defined in the post-processing section of the input file. #scan #scan(mode=rigid) #scan(method=lbfgs, mode=relaxed, level=tight) #scan(method=rfo, mode=relaxed, level=tight) Current runtime support: relaxed scans reuse the optimization dispatcher and support lbfgs , rfo , sd , cg , and sdcg . Rigid scans bypass optimization and ignore optimizer settings.","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#scan"},{"heading":"#device","level":3,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":8,"text":"Specifies the hardware device on which the calculation will run. See Device Selection below for details. #device = cpu #device = gpu0 #device = cuda","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#device"},{"heading":"Job Types","level":2,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":9,"text":"The table below summarizes all supported job types, their command syntax, and default methods. Job Type Command Description Default / Required Single Point #sp Computes energy at the current geometry; verbose=1 adds gradients N/A Optimization #opt Minimizes the molecular geometry L-BFGS Frequency #freq Computes vibrational frequencies and thermochemistry Numerical Hessian Transition State #ts Locates first-order saddle points Required via method IRC #irc Traces the minimum energy path from a TS GS PES Scan #scan Scans along internal coordinates L-BFGS Tip Task commands accept parameters in parentheses using the format #taskname(param1=value1, param2=value2) . If no parameters are given, MAPLE uses the default settings for that job type.","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#job-types"},{"heading":"Device Selection","level":2,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":10,"text":"MAPLE can run on CPUs or NVIDIA GPUs. Use the #device command to select the target hardware. When multiple GPUs are available, you can target a specific one by index. Device Command Description CPU #device = cpu Run on the CPU (default if no GPU is detected) GPU 0 #device = gpu0 Run on the first GPU (CUDA device 0) GPU 1 #device = gpu1 Run on the second GPU (CUDA device 1) CUDA (auto) #device = cuda Automatically select an available CUDA GPU","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#device-selection"},{"heading":"Convergence Levels","level":2,"page":"setup/settings.html","page_entry":false,"page_role":"content","section_order":11,"text":"MAPLE provides several predefined convergence levels for geometry optimizations and transition state searches. These control the thresholds for maximum force ( f_max ), RMS force ( f_rms ), maximum displacement ( dp_max ), and RMS displacement ( dp_rms ). Force thresholds are in Hartree/Angstrom and displacement thresholds are in Angstrom. Level f_max f_rms dp_max dp_rms extratight 3.0e-04 2.0e-04 3.0e-04 2.0e-04 tight 8.5e-04 5.5e-04 1.1e-03 7.5e-04 medium 2.85e-03 1.90e-03 3.15e-03 2.10e-03 loose 3.80e-03 2.50e-03 6.00e-03 4.00e-03 extraloose 7.55e-03 5.00e-03 1.20e-02 8.00e-03 superloose 8.50e-02 5.50e-02 1.45e-01 9.50e-02 Set the convergence level inside the task command parentheses: #opt(method=lbfgs, level=tight) #ts(method=prfo, level=extratight) Tip The default convergence level is medium . For high-accuracy work such as computing thermochemical corrections, consider using tight or extratight . For quick preliminary scans, loose or extraloose can dramatically reduce computation time.","title":"Settings - MAPLE Documentation","trail":["Input Setup","Settings"],"type":"Setup","url":"setup/settings.html#convergence-levels"},{"heading":"Vibrational Frequency Analysis","level":1,"page":"tasks/frequency.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#vibrational-frequency-analysis"},{"heading":"Overview","level":2,"page":"tasks/frequency.html","page_entry":false,"page_role":"content","section_order":1,"text":"The frequency analysis module computes vibrational normal modes by constructing and diagonalizing the mass-weighted Hessian matrix (the matrix of second derivatives of the energy with respect to nuclear coordinates, weighted by atomic masses). Each eigenvalue corresponds to the square of a vibrational frequency, and each eigenvector defines a normal mode of vibration. From the computed normal mode frequencies, MAPLE derives thermochemical quantities using the rigid rotor-harmonic oscillator (RRHO) approximation, including zero-point vibrational energy (ZPVE), thermal corrections, enthalpy, entropy, and Gibbs free energy at the specified temperature and pressure. Warning The input structure should be properly optimized before running a frequency analysis. Frequencies computed at non-stationary points are not physically meaningful and will not yield correct thermochemical data.","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#overview"},{"heading":"Usage","level":2,"page":"tasks/frequency.html","page_entry":false,"page_role":"content","section_order":2,"text":"The frequency analysis task is invoked by including the #freq header command in the input file: #freq When called without parameters, MAPLE uses the default settings: mass-weighted Hessian diagonalization at 298.15 K and 101.325 kPa (1 atm).","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#usage"},{"heading":"Input Example","level":2,"page":"tasks/frequency.html","page_entry":false,"page_role":"content","section_order":3,"text":"Below is a complete input file for a frequency calculation on a previously optimized structure: #model=ani1xnr #freq #device=gpu0 XYZ /path/to/optimized_structure.xyz The XYZ directive reads atomic coordinates from an external file. This is convenient when using geometries produced by a prior optimization run.","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#input-example"},{"heading":"Parameters","level":2,"page":"tasks/frequency.html","page_entry":false,"page_role":"content","section_order":4,"text":"The following parameters can be adjusted for the frequency analysis task. Default values are shown. Parameter Type Default Description method str mw Hessian diagonalization method: mw (mass-weighted), nonmw (unweighted), or both . temperature float 298.15 Temperature in Kelvin for thermochemical evaluation. ilowfreq int 2 Low-frequency treatment: 0 = RRHO (no special treatment), 1 = Truhlar quasi-harmonic, 2 = Grimme quasi-RRHO, 3 = Minenkov interpolation. verbose int 1 Output verbosity level. treat_imag_as_real bool false Treat imaginary frequencies as real for thermochemistry. pressure_kpa float 101.325 Pressure in kPa (101.325 = 1 atm). device str cpu Compute device for Hessian evaluation.","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#parameters"},{"heading":"Output","level":2,"page":"tasks/frequency.html","page_entry":false,"page_role":"content","section_order":5,"text":"The frequency analysis output file reports the following quantities: Normal mode frequencies -- all 3N-6 (or 3N-5 for linear molecules) vibrational frequencies in cm -1 . Imaginary frequencies are printed as negative values. Zero-point vibrational energy (ZPVE) -- the sum of half-quanta for all real vibrational modes, reported in Hartree and kcal/mol. Thermal corrections -- contributions from translational, rotational, and vibrational degrees of freedom at the specified temperature. Enthalpy (H) -- total enthalpy including electronic energy, ZPVE, and thermal corrections. Entropy (S) -- total entropy from translational, rotational, vibrational, and electronic partition functions. Gibbs free energy (G) -- computed as G = H - TS at the specified temperature. Important Imaginary frequencies (printed as negative values) indicate that the structure is not a true minimum. One imaginary frequency corresponds to a transition state; multiple imaginary frequencies suggest the structure is a higher-order saddle point or has not been properly optimized. Re-optimize the structure before repeating the frequency analysis.","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#output"},{"heading":"Thermochemistry","level":2,"page":"tasks/frequency.html","page_entry":false,"page_role":"content","section_order":6,"text":"MAPLE evaluates thermochemical properties using the rigid rotor-harmonic oscillator (RRHO) approximation, which partitions the molecular partition function into independent contributions: Translational partition function -- derived from the ideal gas model, depends on molecular mass, temperature, and pressure. Rotational partition function -- computed from the principal moments of inertia assuming a rigid rotor, with separate handling for linear and nonlinear molecules. Vibrational partition function -- each normal mode is treated as an independent quantum harmonic oscillator. Modes below the ilowfreq threshold are handled with a free-rotor interpolation to avoid numerical instability. Electronic partition function -- assumes the electronic ground state dominates (multiplicity = 1 for closed-shell systems). The total internal energy, enthalpy, entropy, and Gibbs free energy are assembled from these partition function components. All thermochemical values are reported at the user-specified temperature and pressure.","title":"Vibrational Frequency Analysis - MAPLE","trail":["Tasks","Frequency"],"type":"Task","url":"tasks/frequency.html#thermochemistry"},{"heading":"Intrinsic Reaction Coordinate (IRC)","level":1,"page":"tasks/irc/irc.html","page_entry":true,"page_role":"landing","section_order":0,"text":"","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#intrinsic-reaction-coordinate-irc"},{"heading":"Overview","level":2,"page":"tasks/irc/irc.html","page_entry":false,"page_role":"landing","section_order":1,"text":"The Intrinsic Reaction Coordinate (IRC) module follows the minimum energy path (MEP) from a transition state (TS) geometry downhill toward both the reactant and product minima. The IRC path is defined as the mass-weighted steepest descent path originating from the TS saddle point. If the model is sufficient to describe your system, it provides definitive verification that a given transition state connects the expected reactant and product structures. Starting from the TS, the IRC integrator displaces the geometry along the unique imaginary vibrational mode (the eigenvector corresponding to the single negative eigenvalue of the mass-weighted Hessian) and then follows the gradient downhill in both the forward and backward directions until local minima are reached or the maximum number of path points is exceeded.","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#overview"},{"heading":"Available Methods","level":2,"page":"tasks/irc/irc.html","page_entry":false,"page_role":"landing","section_order":2,"text":"MAPLE supports four IRC integration algorithms: Method Full Name Description GS The second-order method of Gonzalez–Schlegel Default method. Mass-weighted coordinates with pivot-step and constrained optimization on a hypersphere. Robust and well-tested. LQA Local Quadratic Approximation Fits a local quadratic surface to the PES at each point. Can be faster than GS on smooth surfaces. HPC Hessian Predictor–Corrector Building upon the LQA, the evaluation and correction steps are executed. EulerPC Euler Predictor–Corrector Simplest predictor-corrector approach using Euler integration.","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#available-methods"},{"heading":"General Usage","level":2,"page":"tasks/irc/irc.html","page_entry":false,"page_role":"landing","section_order":3,"text":"The IRC task is invoked with the #irc keyword, specifying the desired method: #model=ani1xnr #irc(method=gs) #device=gpu0 XYZ /path/to/transition_state.xyz The input geometry must be a valid transition-state structure with exactly one imaginary vibrational frequency. The IRC module reads this geometry, identifies the imaginary mode from the Hessian, and integrates the reaction path in both directions. Important The input structure must be a converged transition state with exactly one imaginary frequency. Running IRC on a geometry that is not a true first-order saddle point will produce unreliable results. Always verify the TS with a frequency calculation before running IRC.","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#general-usage"},{"heading":"Output Files","level":2,"page":"tasks/irc/irc.html","page_entry":false,"page_role":"landing","section_order":4,"text":"The IRC module produces the following output files: *_forward.xyz — Multi-frame XYZ trajectory of the forward IRC path (from TS toward one minimum). *_backward.xyz — Multi-frame XYZ trajectory of the backward IRC path (from TS toward the other minimum). *_full.xyz — Combined trajectory containing both forward and backward paths, with the TS at the center. *.out — Main text output with step-by-step energy, gradient, and convergence information.","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#output-files"},{"heading":"Standard Output","level":3,"page":"tasks/irc/irc.html","page_entry":false,"page_role":"landing","section_order":5,"text":"The *.out file is the main text record of the IRC task. It is usually the first file to inspect when you want to confirm that the transition state was recognized correctly, that both directions converged, and that the expected trajectory files were written. Imaginary-Mode Selection Near the beginning of the IRC section, MAPLE reports which negative Hessian eigenmode was selected as the reaction coordinate. This is the first sanity check: if the wrong mode is chosen, the IRC path may not correspond to the chemistry you want to verify. [INFO] HPC-IRC: Selected negative eigenmode #1 with lambda = -6.112941e-01 (MW basis) Forward IRC Block The forward branch then prints an iteration table containing the energy, relative energy change, maximum gradient, and RMS gradient at each step. This block is useful for checking whether the path is descending smoothly and whether the run reaches the stated convergence thresholds. ************************************************************* * FORWARD HPC-IRC * ************************************************************* Iteration E(Eh) dE(kcal/mol) max(|G|) RMS(G) Convergence thresholds 0.002850 0.001900 0 -29.607559 -0.130441 0.010456 0.004570 ... 29 -29.709985 -64.403189 0.002386 0.001000 *** THE HPC-IRC HAS CONVERGED *** Backward IRC Block MAPLE then repeats the same style of report for the backward branch. In a successful IRC job, both directions should normally converge, and comparing the two blocks helps you see whether one side of the path is significantly more difficult than the other. ************************************************************* * BACKWARD HPC-IRC * ************************************************************* Iteration E(Eh) dE(kcal/mol) max(|G|) RMS(G) Convergence thresholds 0.002850 0.001900 0 -29.607604 -0.158502 0.014370 0.005674 ... 34 -29.680446 -45.867334 0.002657 0.001401 *** THE HPC-IRC HAS CONVERGED *** IRC Path Summary After the two directional runs, the output collects the full IRC path into a single summary table. This is usually the most convenient section for checking the overall energy profile, because the transition-state row is explicitly marked with <= TS . --------------------------------------------------------------- HPC-IRC PATH SUMMARY --------------------------------------------------------------- Step E(Eh) dE(kcal/mol) max(|G|) RMS(G) 1 -29.709985 0.000000 0.002386 0.001000 ... 30 -29.607559 64.272748 0.010456 0.004570 <= TS ... 65 -29.680446 18.535855 0.002657 0.001401 Written Trajectory Files and Timing At the end of the run, MAPLE reports the generated XYZ trajectories and the timing summary. These lines confirm where the forward, backward, and full IRC paths were saved. [INFO] HPC-IRC forward trajectory written to: /path/to/inp1_forward.xyz [INFO] HPC-IRC backward trajectory written to: /path/to/inp1_backward.xyz [INFO] HPC-IRC full trajectory written to: /path/to/inp1_full.xyz ====================================================================== TIMING SUMMARY ====================================================================== Job Dispatching..................................... 8.295 s IRC Calculation................................... 8.294 s Total wall time: 8.504 s","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#standard-output"},{"heading":"Workflow","level":2,"page":"tasks/irc/irc.html","page_entry":false,"page_role":"landing","section_order":6,"text":"The recommended workflow for verifying a transition state using IRC is: TS Search — Locate the transition state using one of the TS methods (P-RFO, NEB, Dimer, String/GSM). Frequency Check — Run a frequency calculation on the optimized TS. Confirm that there is exactly one imaginary frequency and that its vibrational mode corresponds to the expected reaction coordinate. IRC Calculation — Run IRC from the verified TS geometry. Verify Endpoints — Inspect the forward and backward IRC endpoints to confirm they correspond to the expected reactant and product structures.","title":"Intrinsic Reaction Coordinate (IRC) - MAPLE","trail":["Tasks","IRC"],"type":"Task","url":"tasks/irc/irc.html#workflow"},{"heading":"IRC: Euler Predictor–Corrector (EulerPC)","level":1,"page":"tasks/irc/irc_eulerpc.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#irc-euler-predictor-corrector-eulerpc"},{"heading":"Overview","level":2,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":1,"text":"EulerPC (Euler predictor-corrector) is a first-order predictor-corrector IRC integrator designed to achieve a favorable trade-off between computational cost and accuracy. Due to the first-order nature of the predictor step, EulerPC often requires smaller step sizes or a higher density of path points to reach a level of precision comparable to higher-order or Hessian-based methods (such as GS or HPC), which may lead to reduced efficiency in certain cases. However, it serves as a robust and practical alternative when Hessian-based methods are unavailable, computationally prohibitive, or numerically ill-behaved. Like HPC, it uses the Modified Bulirsch-Stoer integrator on a DWI surface to refine the path.","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#overview"},{"heading":"Algorithm","level":2,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":2,"text":"At each IRC step, the EulerPC method proceeds in three phases: Predictor — Following an initial displacement along the transition vector corresponding to the imaginary frequency, an Euler predictor step is performed in mass-weighted coordinates. Evaluation — The potential energy surface derivatives are evaluated at the predicted point, and a locally fitted PES is constructed using information from both the starting and predicted points. Corrector — A correction integration is performed on this local surface to mitigate path deviations resulting from finite step sizes.","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#algorithm"},{"heading":"Parameters","level":2,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":3,"text":"The complete EulerPCParams dataclass: Parameter Type Default Description target_mode int 1 Index of the imaginary mode to follow. step_length_bohr float 0.10 Step length in Bohr. max_steps int 50 Maximum IRC steps per direction. max_pred_steps int 500 Maximum predictor sub-steps. loose_cycles int 3 Number of initial cycles with loosened convergence. hessian_recalc int None Recalculate Hessian every N steps. hessian_update str bofill Hessian update: \"bfgs\" or \"bofill\" . dwi_n int 4 Distance-weighted interpolation points. mbs_max_k int 15 Max polynomial order for MBS. mbs_points int 20 Number of MBS integration points. mbs_tol float 1e-5 MBS convergence tolerance. f_max_th float 2e-3 Max force convergence threshold. f_rms_th float 5e-4 RMS force convergence threshold. print_each bool True Print details at each IRC point. write_traj bool True Write trajectory XYZ files.","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#parameters"},{"heading":"Example: Radical isomerization","level":2,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":4,"text":"In this example, we will perform the calculations for the H2COH -> H3CO reaction involved in the original EulerPC reference. The TS structure is derived via the String method and the explicit water is considered to assist the reaction, with the system having a spin multiplicity of 2.","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#example"},{"heading":"Input Example","level":3,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":5,"text":"#model=aimnet2nse #irc(method=eulerpc) #device=gpu0 XYZ 0 2 /path/to/transition_state.xyz","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#input-example"},{"heading":"Output Visualization","level":3,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":6,"text":"After a brief wait for the calculation to complete, we can visualize the reaction path and the energy profile along the reaction coordinate. Trajectory: Simplified view of the reaction path Graph: Energy trend along the IRC path","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#example-visuals"},{"heading":"Ref Structure","level":3,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":7,"text":"Transition State 8 Image 0 Energy = -191.55241663 C 0.2707493323 -0.8839208040 0.0593391556 H 0.8065677208 -2.2033699236 0.4439009220 H 0.8020890579 -0.6010813154 -0.8576257232 H -0.8079751217 -1.0413748042 -0.0556802194 O 0.7091869188 -0.3944101545 1.2167602799 O 1.3829694247 -2.5998174092 1.4932190528 H 2.3408200175 -2.6386038898 1.3632820341 H 1.1873343825 -1.4974192399 1.7123875960","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#structures"},{"heading":"Comparison of IRC Methods","level":2,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":8,"text":"Method Speed Robustness Best For GS Moderate High General use and path curvature sensitive LQA Fast Moderate Smooth surfaces HPC Moderate High Balanced speed/accuracy EulerPC Fast Moderate Wish to use Euler's integral","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#comparison-of-irc-methods"},{"heading":"When to Use","level":2,"page":"tasks/irc/irc_eulerpc.html","page_entry":false,"page_role":"content","section_order":9,"text":"The EulerPC method is recommended as a fallback when other IRC methods have difficulty: When the default HPC method , LQA , or GS fail to converge along the IRC path. For reactions involving large-amplitude motions or irregular PES regions. For routine IRC calculations on well-behaved surfaces, the default GS method or the HPC method are generally preferred.","title":"IRC: Euler Predictor-Corrector (EulerPC) - MAPLE","trail":["Tasks","IRC","EulerPC"],"type":"Task","url":"tasks/irc/irc_eulerpc.html#when-to-use"},{"heading":"IRC: Gonzalez–Schlegel (GS) Method","level":1,"page":"tasks/irc/irc_gs.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#irc-gonzalez-schlegel-gs-method"},{"heading":"Overview","level":2,"page":"tasks/irc/irc_gs.html","page_entry":false,"page_role":"content","section_order":1,"text":"The second-order method of Gonzalez–Schlegel (GS) has been implemented in MAPLE. It operates in mass-weighted Cartesian coordinates and uses a two-phase pivot-step plus constrained-optimization approach at each IRC point: Pivot step — A steepest-descent step is taken along the negative gradient direction in mass-weighted coordinates to produce a trial point on a hypersphere centered at the current IRC point. Constrained optimization — The trial point is refined by minimizing the energy on the surface of the hypersphere, using the perpendicular component of the gradient, until the corrector converges. The Hessian is updated along the path using BFGS/Bofill update formulas, avoiding full Hessian recomputation at every step. Adaptive step-size control adjusts the arc length based on path curvature, and an optional parabolic fit detects when the path has descended into a minimum basin. The GS method integrates both the forward and backward IRC paths, starting from the transition state.","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/irc/irc_gs.html","page_entry":false,"page_role":"content","section_order":2,"text":"All GS parameters can be specified in the #irc(...) header line. The complete GSParams dataclass: Parameter Type Default Description target_mode int 1 Index of the imaginary vibrational mode to follow (1-based). step_length_bohr float 0.10 Step length along the IRC path in Bohr. max_steps int 50 Maximum number of IRC steps in each direction. max_micro_cycles int 20 Maximum micro-iterations per IRC macro-step (constrained optimization on hypersphere). micro_step_thresh float 1e-3 Convergence threshold for micro-iterations. hessian_recalc int None Recalculate the full Hessian every N steps. None means never recalculate. hessian_update str bofill Hessian update method: \"bfgs\" or \"bofill\" . f_max_th float 2e-3 Max force convergence threshold (Hartree/Bohr). f_rms_th float 5e-4 RMS force convergence threshold. print_each bool True Print step details for each IRC point. write_traj bool True Write trajectory XYZ files.","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#parameters"},{"heading":"Example: SN2 reaction","level":2,"page":"tasks/irc/irc_gs.html","page_entry":false,"page_role":"content","section_order":3,"text":"In this example, we will perform the calculations for the F- + CH3F -> FCH3 + F- reaction involved in the original GS reference. The TS structure is derived via the P-RFO method. Note that the system carries a net charge of -1 in this case.","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#example"},{"heading":"Input Example","level":3,"page":"tasks/irc/irc_gs.html","page_entry":false,"page_role":"content","section_order":4,"text":"#model=aimnet2 #irc(method=gs) #device=gpu0 XYZ -1 1 /path/to/transition_state.xyz","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#input-example"},{"heading":"Output Visualization","level":3,"page":"tasks/irc/irc_gs.html","page_entry":false,"page_role":"content","section_order":5,"text":"After a brief wait for the calculation to complete, we can visualize the reaction path and the energy profile along the reaction coordinate. Trajectory: Simplified view of the reaction path Graph: Energy trend along the IRC path","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#example-visuals"},{"heading":"Ref Structure","level":3,"page":"tasks/irc/irc_gs.html","page_entry":false,"page_role":"content","section_order":6,"text":"Transition State 6 Iteration 26 Energy = -239.7111960742 H 0.0064725364 1.0714480485 -0.8400337833 H 0.9377518596 -0.5437668524 -0.8426007651 H -0.9267066183 -0.5426693610 -0.8429760387 C 0.0058392639 -0.0049960268 -0.8418701156 F 0.0054541606 -0.0082444202 1.0624162248 F 0.0062246908 -0.0017475723 -2.7461566766","title":"IRC: Gonzalez-Schlegel (GS) - MAPLE","trail":["Tasks","IRC","GS"],"type":"Task","url":"tasks/irc/irc_gs.html#structure"},{"heading":"IRC: Hessian Predictor–Corrector (HPC)","level":1,"page":"tasks/irc/irc_hpc.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#irc-hessian-predictor-corrector-hpc"},{"heading":"Overview","level":2,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":1,"text":"The HPC method is a predictor–corrector IRC integrator in which the predictor step is based on second-order Hessian information. HPC combines a second-order local quadratic approximation (LQA) predictor with a high-accuracy corrector integration on a locally fitted potential-energy surface. This gives a favorable balance between computational cost and path quality.","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#overview"},{"heading":"Algorithm","level":2,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":2,"text":"At each IRC step, the HPC method proceeds in three phases: Predictor — Starting from the current IRC point, a predictor step is generated using the second-order LQA integrator in mass-weighted coordinates. Evaluation — The energy and derivative information are evaluated at the predicted point. Together with the data from the previous point, this information is used to construct a local fitted potential-energy surface. Corrector — A high-accuracy corrector integration is then performed on the fitted local surface, using a modified Bulirsch–Stoer scheme, to reduce finite-step deviation and obtain a point that more closely follows the IRC. The Hessian is updated between steps using BFGS/Bofill update formulas to avoid expensive full Hessian recomputations at every IRC point.","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#algorithm"},{"heading":"Parameters","level":2,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":3,"text":"The complete HPCParams dataclass: Parameter Type Default Description target_mode int 1 Index of the imaginary mode to follow. step_length_bohr float 0.10 Step length in Bohr. max_steps int 50 Maximum IRC steps per direction. euler_n int 5000 Number of Euler sub-steps for the predictor. hessian_recalc int None Recalculate Hessian every N steps. hessian_update str bofill Hessian update: \"bfgs\" or \"bofill\" . dwi_n int 4 Number of distance-weighted interpolation points. mbs_max_k int 15 Maximum polynomial order for modified Bulirsch-Stoer. mbs_points int 20 Number of MBS integration points. mbs_tol float 1e-5 MBS convergence tolerance. f_max_th float 2e-3 Max force convergence threshold. f_rms_th float 5e-4 RMS force convergence threshold. print_each bool True Print details at each IRC point. write_traj bool True Write trajectory XYZ files.","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#parameters"},{"heading":"Example: Dehydrohalogenation","level":2,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":4,"text":"In this example, we will perform the calculations for the CH3CH2F -> CH2CH2 + HF reaction involved in the original HPC reference. The TS structure is derived via the String method. To speed up the calculation, a larger step size of 0.15 was used.","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#example"},{"heading":"Input Example","level":3,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":5,"text":"#model=aimnet2 #irc(method=hpc,step_length_bohr=0.15) #device=gpu0 XYZ /path/to/transition_state.xyz","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#input-example"},{"heading":"Output Visualization","level":3,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":6,"text":"After a brief wait for the calculation to complete, we can visualize the reaction path and the energy profile along the reaction coordinate. Trajectory: Simplified view of the reaction path Graph: Energy trend along the IRC path","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#example-visuals"},{"heading":"Ref Structure","level":3,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":7,"text":"Transition State 8 Image 0 Energy = -179.06046123 C -2.0232059669 -0.0727959625 0.0125441382 H -2.5203834295 -1.0371318543 0.0792584332 H -1.4508729125 0.0518015848 -0.9031470609 H -2.8291660857 0.9415420231 0.2594518458 C -1.5340413625 0.5058439206 1.1864655006 H -1.8281739484 0.1363239914 2.1573191103 H -0.7434990832 1.2406972886 1.1609842489 F -2.9083899697 1.8448367975 1.1744474484","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#structures"},{"heading":"When to Use","level":2,"page":"tasks/irc/irc_hpc.html","page_entry":false,"page_role":"content","section_order":8,"text":"The HPC method is recommended when: The GS method is too slow due to the number of constrained optimization required at each IRC point. You want a good balance between efficiency and path quality. The PES has moderate curvature changes along the reaction path, where Hessian-based integration provides a clear advantage over simpler gradient-only methods. For very smooth surfaces where maximum speed is desired, consider LQA . For extremely difficult or anharmonic surfaces where robustness is paramount, consider GS .","title":"IRC: Hessian Predictor-Corrector (HPC) - MAPLE","trail":["Tasks","IRC","HPC"],"type":"Task","url":"tasks/irc/irc_hpc.html#when-to-use"},{"heading":"IRC: Local Quadratic Approximation (LQA)","level":1,"page":"tasks/irc/irc_lqa.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#irc-local-quadratic-approximation-lqa"},{"heading":"Overview","level":2,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":1,"text":"The Local Quadratic Approximation (LQA) method is an IRC integration algorithm that approximates the potential energy surface locally by a second-order expansion in mass-weighted coordinates. the LQA method solves the differential equation of motion analytically on this quadratic surface using the eigenvalues and eigenvectors of the mass-weighted Hessian. This allows the path to \"curve\" correctly within a single step. On smooth, well-behaved potential energy surfaces, LQA can be more efficient than GS because the local quadratic model often captures the nearby curvature reasonably well.","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#overview"},{"heading":"Algorithm","level":2,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":2,"text":"At each IRC step, the LQA method proceeds as follows: Construct a local quadratic model of the potential energy surface in mass-weighted coordinates using the current gradient and Hessian. Integrate the steepest-descent path on this quadratic surface to obtain the next IRC point. Evaluate the gradient at the new point for the next integration step. The Hessian is updated between steps using BFGS/Bofill update formulas to avoid expensive full Hessian recomputations at every IRC point.","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#algorithm"},{"heading":"Parameters","level":2,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":3,"text":"The complete LQAParams dataclass: Parameter Type Default Description target_mode int 1 Index of the imaginary mode to follow. step_length_bohr float 0.10 Step length along the IRC path in Bohr. max_steps int 50 Maximum IRC steps per direction. euler_n int 5000 Number of Euler integration sub-steps per IRC step. hessian_recalc int None Recalculate Hessian every N steps. hessian_update str bofill Hessian update: \"bfgs\" or \"bofill\" . f_max_th float 2e-3 Max force convergence threshold. f_rms_th float 5e-4 RMS force convergence threshold. print_each bool True Print details at each IRC point. write_traj bool True Write trajectory XYZ files.","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#parameters"},{"heading":"Example: Isomerization reaction","level":2,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":4,"text":"In this example, we will perform the classic isomerization calculation case of the HCN -> HNC. The TS structure is derived via the PRFO method. To speed up the calculation, a larger step size of 0.15 was used.","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#example"},{"heading":"Input Example","level":3,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":5,"text":"#model=aimnet2nse #irc(method=lqa,step_length_bohr=0.15) #device=gpu0 XYZ 0 1 /path/to/transition_state.xyz","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#input-example"},{"heading":"Output Visualization","level":3,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":6,"text":"After a brief wait for the calculation to complete, we can visualize the reaction path and the energy profile along the reaction coordinate. Trajectory: Simplified view of the reaction path Graph: Energy trend along the IRC path","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#example-visuals"},{"heading":"Ref Structure","level":3,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":7,"text":"Transition State 3 Iteration 6 Energy = -93.3911999898 C 0.4147189982 0.0090611094 -0.5547979606 N 0.0319422836 -0.0048546467 0.5850722629 H 1.3836904902 -0.1619564366 0.2436923366","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#structures"},{"heading":"Comparison with GS","level":2,"page":"tasks/irc/irc_lqa.html","page_entry":false,"page_role":"content","section_order":8,"text":"The LQA and GS methods differ primarily in how they determine each IRC step: GS uses a pivot-step followed by constrained optimization on a hypersphere. It does not rely on the quadratic approximation for the step direction, making it more robust on surfaces where the quadratic model breaks down. LQA uses the full quadratic model (gradient + Hessian) to analytically predict the next point, which can be faster when the quadratic approximation is accurate. In practice, LQA tends to be faster on smooth, harmonic-like surfaces, while GS is more robust for highly anharmonic or strongly curved reaction paths. If LQA has convergence difficulties, switching to GS or HPC is recommended.","title":"IRC: Local Quadratic Approximation (LQA) - MAPLE","trail":["Tasks","IRC","LQA"],"type":"Task","url":"tasks/irc/irc_lqa.html#comparison-with-gs"},{"heading":"Conjugate Gradient (CG)","level":1,"page":"tasks/opt/opt_cg.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"CG Optimization - MAPLE","trail":["Tasks","Optimization","CG"],"type":"Task","url":"tasks/opt/opt_cg.html#conjugate-gradient-cg"},{"heading":"Overview","level":2,"page":"tasks/opt/opt_cg.html","page_entry":false,"page_role":"content","section_order":1,"text":"The conjugate gradient optimizer builds a search direction that is conjugate to all previous directions, avoiding the zigzagging characteristic of steepest descent. Each step reuses gradient history through a scalar coefficient β (the beta formula), making CG substantially more efficient than pure SD on smooth energy surfaces. Invoked with method=cg inside #opt() . MAPLE implements the Polak–Ribière-Plus (PRP+) formula by default, with automatic direction restart when the gradient changes significantly. Optional DIIS acceleration can be applied periodically to further speed convergence.","title":"CG Optimization - MAPLE","trail":["Tasks","Optimization","CG"],"type":"Task","url":"tasks/opt/opt_cg.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/opt/opt_cg.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description max_step float 0.2 Maximum step length in Angstrom. max_iter int 256 Maximum number of optimization cycles. cg_restart_threshold float 0.2 Restart CG directions when the gradient change ratio exceeds this value. cg_beta_method str \"prp+\" Conjugate gradient beta formula. prp+ (Polak–Ribière-Plus) is recommended for molecular optimization. diis_enabled bool True Enable DIIS extrapolation acceleration. diis_store_every int 5 Store a DIIS snapshot every N steps. diis_min_snapshots int 3 Minimum snapshots required before DIIS extrapolation is attempted. diis_memory int 6 Maximum number of DIIS snapshots stored. verbose int 1 Output verbosity level.","title":"CG Optimization - MAPLE","trail":["Tasks","Optimization","CG"],"type":"Task","url":"tasks/opt/opt_cg.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/opt/opt_cg.html","page_entry":false,"page_role":"content","section_order":3,"text":"#model=uma #opt(method=cg) #device=gpu0 C -0.77812600 -1.06756100 0.32105900 C 1.30255300 0.05212000 -0.02829900 C -0.97199300 1.45624900 0.82365700 C 1.98122900 -0.41843300 1.25017500 C 2.26403300 0.43516800 -1.13310700 N 0.29116400 -0.87682100 -0.50039900 N -2.01916300 -1.37200600 -0.23311200 O -1.66473400 1.63022300 -0.40183700 H -2.25863200 0.87013900 -0.47589900 H 0.02784900 -0.67831200 -1.45849500 H -0.60975900 -1.36785600 1.34117800 H 0.68126400 0.91830000 0.28694100 H -2.57326300 -2.05736100 0.25741200 H -2.05242800 -1.50454200 -1.23382300 H -0.36899300 2.35139200 0.99174700 H -1.63960900 1.29421500 1.67465300 H 2.76444900 0.29146200 1.52284600 H 1.72511400 0.73069500 -2.03779400 H 2.43559300 -1.40609800 1.13421500 H 1.27300500 -0.44722400 2.08057900 H 2.85034500 1.29869700 -0.81432200 H 2.96000900 -0.36880600 -1.38891000","title":"CG Optimization - MAPLE","trail":["Tasks","Optimization","CG"],"type":"Task","url":"tasks/opt/opt_cg.html#input-example"},{"heading":"When to Use","level":2,"page":"tasks/opt/opt_cg.html","page_entry":false,"page_role":"content","section_order":4,"text":"Smooth energy surfaces: CG converges much faster than SD on well-behaved surfaces by exploiting gradient history to build conjugate search directions. Memory-constrained environments: CG stores only the previous gradient vector, making it more memory-efficient than L-BFGS for very large systems. Starting from a reasonable geometry: CG is most effective when the initial forces are moderate. For severely distorted structures, consider starting with SD or the automatic SD/CG fusion.","title":"CG Optimization - MAPLE","trail":["Tasks","Optimization","CG"],"type":"Task","url":"tasks/opt/opt_cg.html#when-to-use"},{"heading":"Convergence Behaviour","level":2,"page":"tasks/opt/opt_cg.html","page_entry":false,"page_role":"content","section_order":5,"text":"The figures below show a typical CG run on a 22-atom organic molecule (UMA model). Compared to steepest descent, CG avoids zigzagging by building conjugate search directions, leading to smoother convergence near the minimum. Fig. 1 — Energy convergence (CG) Fig. 2 — Force convergence (CG) Note For most use cases, SD/CG (which runs SD first and automatically switches to CG) is preferable to pure CG, as it combines robust initial descent with efficient final convergence. Pure CG is best when the starting geometry is already reasonable.","title":"CG Optimization - MAPLE","trail":["Tasks","Optimization","CG"],"type":"Task","url":"tasks/opt/opt_cg.html#convergence"},{"heading":"L-BFGS Optimization","level":1,"page":"tasks/opt/opt_lbfgs.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"L-BFGS Optimization - MAPLE","trail":["Tasks","Optimization","L-BFGS"],"type":"Task","url":"tasks/opt/opt_lbfgs.html#l-bfgs-optimization"},{"heading":"Overview","level":2,"page":"tasks/opt/opt_lbfgs.html","page_entry":false,"page_role":"content","section_order":1,"text":"L-BFGS (Limited-memory Broyden–Fletcher–Goldfarb–Shanno) is a quasi-Newton optimization method that approximates the inverse Hessian matrix using information from a limited number of previous gradient evaluations. By storing only a small set of vector pairs rather than the full Hessian, it achieves near-Newton convergence rates while requiring minimal memory. L-BFGS is the default and recommended optimizer in MAPLE. It is well suited for the vast majority of molecular systems, providing fast and stable convergence for both small molecules and large biomolecular structures.","title":"L-BFGS Optimization - MAPLE","trail":["Tasks","Optimization","L-BFGS"],"type":"Task","url":"tasks/opt/opt_lbfgs.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/opt/opt_lbfgs.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description memory int 5 Number of past gradient/position pairs stored for the inverse Hessian approximation. curvature float 70.0 Initial diagonal Hessian estimate (inverse curvature scaling). max_step float 0.2 Maximum step length in Angstrom per atom per cycle. max_iter int 256 Maximum number of optimization cycles. verbose int 1 Output verbosity level (0=energy only, 1=detailed).","title":"L-BFGS Optimization - MAPLE","trail":["Tasks","Optimization","L-BFGS"],"type":"Task","url":"tasks/opt/opt_lbfgs.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/opt/opt_lbfgs.html","page_entry":false,"page_role":"content","section_order":3,"text":"A minimal input file using L-BFGS optimization with default parameters: #model=uma #opt(method=lbfgs) #device=gpu0 C -0.77812600 -1.06756100 0.32105900 C 1.30255300 0.05212000 -0.02829900 C -0.97199300 1.45624900 0.82365700 C 1.98122900 -0.41843300 1.25017500 C 2.26403300 0.43516800 -1.13310700 N 0.29116400 -0.87682100 -0.50039900 N -2.01916300 -1.37200600 -0.23311200 O -1.66473400 1.63022300 -0.40183700 H -2.25863200 0.87013900 -0.47589900 H 0.02784900 -0.67831200 -1.45849500 H -0.60975900 -1.36785600 1.34117800 H 0.68126400 0.91830000 0.28694100 H -2.57326300 -2.05736100 0.25741200 H -2.05242800 -1.50454200 -1.23382300 H -0.36899300 2.35139200 0.99174700 H -1.63960900 1.29421500 1.67465300 H 2.76444900 0.29146200 1.52284600 H 1.72511400 0.73069500 -2.03779400 H 2.43559300 -1.40609800 1.13421500 H 1.27300500 -0.44722400 2.08057900 H 2.85034500 1.29869700 -0.81432200 H 2.96000900 -0.36880600 -1.38891000","title":"L-BFGS Optimization - MAPLE","trail":["Tasks","Optimization","L-BFGS"],"type":"Task","url":"tasks/opt/opt_lbfgs.html#input-example"},{"heading":"Convergence Behaviour","level":2,"page":"tasks/opt/opt_lbfgs.html","page_entry":false,"page_role":"content","section_order":4,"text":"The figures below illustrate a typical L-BFGS run on a 22-atom organic molecule (UMA model). Energy is reported relative to the converged value; forces are on a logarithmic scale with convergence thresholds shown as dashed lines. Fig. 1 — Energy convergence (L-BFGS) Fig. 2 — Force convergence (L-BFGS) Fig. 3 — Optimization trajectory (L-BFGS)","title":"L-BFGS Optimization - MAPLE","trail":["Tasks","Optimization","L-BFGS"],"type":"Task","url":"tasks/opt/opt_lbfgs.html#convergence"},{"heading":"Tips","level":2,"page":"tasks/opt/opt_lbfgs.html","page_entry":false,"page_role":"content","section_order":5,"text":"Increase memory (e.g., to 10 or 20) for systems with many soft degrees of freedom, such as large flexible molecules or weakly bound complexes. A larger history window provides a better Hessian approximation and can reduce the total number of steps needed to converge. Reduce max_step (e.g., to 0.1 or 0.05) when the optimization oscillates or the energy increases between steps. Smaller step limits prevent the optimizer from moving too far in a single cycle, which is especially helpful for strained or highly anharmonic geometries. Lower curvature (e.g., to 30) for systems where the initial steps are too aggressive, or raise it (e.g., to 100) if the first few steps are unnecessarily small. Note L-BFGS is a minimization algorithm and will converge to the nearest local minimum. It should not be used to locate transition states. For transition-state searches, see the Transition State methods.","title":"L-BFGS Optimization - MAPLE","trail":["Tasks","Optimization","L-BFGS"],"type":"Task","url":"tasks/opt/opt_lbfgs.html#tips"},{"heading":"RFO Optimization","level":1,"page":"tasks/opt/opt_rfo.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"RFO Optimization - MAPLE","trail":["Tasks","Optimization","RFO"],"type":"Task","url":"tasks/opt/opt_rfo.html#rfo-optimization"},{"heading":"Overview","level":2,"page":"tasks/opt/opt_rfo.html","page_entry":false,"page_role":"content","section_order":1,"text":"RFO (Rational Function Optimization) is a second-order optimization method that uses a trust-radius strategy to control step sizes. Rather than relying solely on the gradient direction, RFO constructs a rational function model of the potential energy surface and determines the optimal step within a dynamically adjusted trust region. At each iteration, the algorithm compares the predicted energy change from its model with the actual energy change. If the model prediction is accurate, the trust radius is expanded to allow larger steps. If the prediction is poor, the step is rejected and the trust radius is contracted. This adaptive behavior makes RFO more robust than L-BFGS for systems with strong curvature or difficult potential energy surfaces.","title":"RFO Optimization - MAPLE","trail":["Tasks","Optimization","RFO"],"type":"Task","url":"tasks/opt/opt_rfo.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/opt/opt_rfo.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description max_iter int 256 Maximum number of optimization cycles. trust_radius_init float 0.2 Initial trust radius in Angstrom. trust_radius_min float 1e-3 Minimum trust radius. trust_radius_max float 1.0 Maximum trust radius. eta_shrink float 0.75 Trust radius shrink factor when step quality is poor. eta_expand float 1.75 Trust radius expansion factor when step quality is good. evals_eps float 1e-10 Eigenvalue epsilon for numerical stability. mu_margin float 1e-8 Margin for the level-shift parameter mu. max_bisect_it int 60 Maximum bisection iterations for level-shift optimization.","title":"RFO Optimization - MAPLE","trail":["Tasks","Optimization","RFO"],"type":"Task","url":"tasks/opt/opt_rfo.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/opt/opt_rfo.html","page_entry":false,"page_role":"content","section_order":3,"text":"A minimal input file using RFO optimization: #model=uma #opt(method=rfo) #device=gpu0 C -0.77812600 -1.06756100 0.32105900 C 1.30255300 0.05212000 -0.02829900 C -0.97199300 1.45624900 0.82365700 C 1.98122900 -0.41843300 1.25017500 C 2.26403300 0.43516800 -1.13310700 N 0.29116400 -0.87682100 -0.50039900 N -2.01916300 -1.37200600 -0.23311200 O -1.66473400 1.63022300 -0.40183700 H -2.25863200 0.87013900 -0.47589900 H 0.02784900 -0.67831200 -1.45849500 H -0.60975900 -1.36785600 1.34117800 H 0.68126400 0.91830000 0.28694100 H -2.57326300 -2.05736100 0.25741200 H -2.05242800 -1.50454200 -1.23382300 H -0.36899300 2.35139200 0.99174700 H -1.63960900 1.29421500 1.67465300 H 2.76444900 0.29146200 1.52284600 H 1.72511400 0.73069500 -2.03779400 H 2.43559300 -1.40609800 1.13421500 H 1.27300500 -0.44722400 2.08057900 H 2.85034500 1.29869700 -0.81432200 H 2.96000900 -0.36880600 -1.38891000","title":"RFO Optimization - MAPLE","trail":["Tasks","Optimization","RFO"],"type":"Task","url":"tasks/opt/opt_rfo.html#input-example"},{"heading":"When to Use RFO","level":2,"page":"tasks/opt/opt_rfo.html","page_entry":false,"page_role":"content","section_order":4,"text":"RFO is a good alternative when L-BFGS struggles to converge. Consider switching to RFO in the following situations: Systems near a minimum with strong curvature: RFO uses full Hessian information (built up over iterations) and a trust-radius mechanism, which handles regions of high curvature more reliably than the limited-memory approximation in L-BFGS. Difficult or sensitive potential energy surfaces: When L-BFGS oscillates or fails to reduce the energy monotonically, the trust-radius step acceptance/rejection logic in RFO provides a built-in safeguard against bad steps. Small to medium-sized molecules: RFO stores and manipulates the full Hessian matrix, so its memory and computational cost scale quadratically with system size. For very large systems (thousands of atoms), L-BFGS is generally more efficient. Pre-optimization before frequency calculations: When a tight convergence is needed, RFO can be more reliable for the final stages of optimization because its trust-radius approach adapts naturally to the curvature near the minimum.","title":"RFO Optimization - MAPLE","trail":["Tasks","Optimization","RFO"],"type":"Task","url":"tasks/opt/opt_rfo.html#when-to-use-rfo"},{"heading":"Convergence Behaviour","level":2,"page":"tasks/opt/opt_rfo.html","page_entry":false,"page_role":"content","section_order":5,"text":"The figures below show a typical RFO run on the same 22-atom molecule used for the L-BFGS example. The comparison plot (Fig. 3) overlays both methods to illustrate how RFO adapts its step size with the trust-radius mechanism. Fig. 1 — Energy convergence (RFO) Fig. 2 — Force convergence (RFO) Fig. 3 — L-BFGS vs RFO energy convergence comparison Tip For large systems where RFO is too expensive, try L-BFGS with a reduced max_step as a compromise between robustness and efficiency.","title":"RFO Optimization - MAPLE","trail":["Tasks","Optimization","RFO"],"type":"Task","url":"tasks/opt/opt_rfo.html#convergence"},{"heading":"Steepest Descent (SD)","level":1,"page":"tasks/opt/opt_sd.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"SD Optimization - MAPLE","trail":["Tasks","Optimization","SD"],"type":"Task","url":"tasks/opt/opt_sd.html#steepest-descent-sd"},{"heading":"Overview","level":2,"page":"tasks/opt/opt_sd.html","page_entry":false,"page_role":"content","section_order":1,"text":"The steepest descent optimizer moves each step directly along the negative gradient direction, scaled by a fixed maximum step length. It is the simplest first-order method and requires no history or Hessian information. Invoked with method=sd inside #opt() . Because each step is independent and the direction is always the steepest downhill direction, SD is highly robust for severely distorted geometries but converges slowly near a minimum due to its tendency to zigzag. For better convergence after the initial descent, consider switching to CG or using the automatic SD/CG fusion.","title":"SD Optimization - MAPLE","trail":["Tasks","Optimization","SD"],"type":"Task","url":"tasks/opt/opt_sd.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/opt/opt_sd.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description max_step float 0.2 Maximum step length in Angstrom. max_iter int 256 Maximum number of optimization cycles. sd_max_iter int 50 Maximum SD iterations before stopping (when used as a standalone method). verbose int 1 Output verbosity level.","title":"SD Optimization - MAPLE","trail":["Tasks","Optimization","SD"],"type":"Task","url":"tasks/opt/opt_sd.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/opt/opt_sd.html","page_entry":false,"page_role":"content","section_order":3,"text":"#model=uma #opt(method=sd) #device=gpu0 C -0.77812600 -1.06756100 0.32105900 C 1.30255300 0.05212000 -0.02829900 C -0.97199300 1.45624900 0.82365700 C 1.98122900 -0.41843300 1.25017500 C 2.26403300 0.43516800 -1.13310700 N 0.29116400 -0.87682100 -0.50039900 N -2.01916300 -1.37200600 -0.23311200 O -1.66473400 1.63022300 -0.40183700 H -2.25863200 0.87013900 -0.47589900 H 0.02784900 -0.67831200 -1.45849500 H -0.60975900 -1.36785600 1.34117800 H 0.68126400 0.91830000 0.28694100 H -2.57326300 -2.05736100 0.25741200 H -2.05242800 -1.50454200 -1.23382300 H -0.36899300 2.35139200 0.99174700 H -1.63960900 1.29421500 1.67465300 H 2.76444900 0.29146200 1.52284600 H 1.72511400 0.73069500 -2.03779400 H 2.43559300 -1.40609800 1.13421500 H 1.27300500 -0.44722400 2.08057900 H 2.85034500 1.29869700 -0.81432200 H 2.96000900 -0.36880600 -1.38891000","title":"SD Optimization - MAPLE","trail":["Tasks","Optimization","SD"],"type":"Task","url":"tasks/opt/opt_sd.html#input-example"},{"heading":"When to Use","level":2,"page":"tasks/opt/opt_sd.html","page_entry":false,"page_role":"content","section_order":4,"text":"Severely distorted geometries: When the starting structure has large steric clashes or unreasonable bond lengths, SD rapidly reduces the worst forces without requiring Hessian information. Pre-optimization pass: A short SD run can stabilise a structure before handing off to a more efficient method such as L-BFGS or RFO. Diagnostic runs: Because each step is independent and the algorithm is transparent, SD is useful for isolating convergence problems.","title":"SD Optimization - MAPLE","trail":["Tasks","Optimization","SD"],"type":"Task","url":"tasks/opt/opt_sd.html#when-to-use"},{"heading":"Convergence Behaviour","level":2,"page":"tasks/opt/opt_sd.html","page_entry":false,"page_role":"content","section_order":5,"text":"The figures below show a typical SD run on a 22-atom organic molecule (UMA model). Energy drops steeply in the early iterations but the characteristic zigzagging of SD slows convergence near the minimum. Fig. 1 — Energy convergence (SD) Fig. 2 — Force convergence (SD) Note Pure SD is rarely the best choice for a complete optimization. Consider SD/CG to automatically transition to conjugate gradient once the large initial forces have been reduced, or L-BFGS for production runs.","title":"SD Optimization - MAPLE","trail":["Tasks","Optimization","SD"],"type":"Task","url":"tasks/opt/opt_sd.html#convergence"},{"heading":"SD/CG Optimization","level":1,"page":"tasks/opt/opt_sdcg.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"SD/CG Optimization - MAPLE","trail":["Tasks","Optimization","SD/CG"],"type":"Task","url":"tasks/opt/opt_sdcg.html#sd-cg-optimization"},{"heading":"Overview","level":2,"page":"tasks/opt/opt_sdcg.html","page_entry":false,"page_role":"content","section_order":1,"text":"The SD/CG optimizer is a hybrid steepest-descent / conjugate-gradient method with optional DIIS acceleration. It begins with a steepest descent phase to rapidly reduce large forces, then automatically switches to conjugate gradient for more efficient convergence near a minimum. This is the recommended choice when a starting geometry may be significantly distorted. Invoked with method=sdcg (or simply the keyword sdcg , which defaults to this mode). The switch from SD to CG is controlled by sd_max_iter and cg_switch_fmax : the optimizer moves to CG once either the SD iteration limit is reached or the maximum force drops below the specified threshold. With the default cg_switch_fmax=0.0 , MAPLE sets an automatic threshold equal to 0.5 × the initial maximum force. The parameters sd_enabled and cg_enabled are derived internally from the method keyword and are not intended to be set directly.","title":"SD/CG Optimization - MAPLE","trail":["Tasks","Optimization","SD/CG"],"type":"Task","url":"tasks/opt/opt_sdcg.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/opt/opt_sdcg.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description max_step float 0.2 Maximum step length in Angstrom. max_iter int 256 Maximum number of optimization cycles. sd_max_iter int 50 Maximum iterations in the initial SD phase before switching to CG. cg_switch_fmax float 0.0 Switch from SD to CG when the maximum force drops below this value (Hartree/Angstrom). The default 0.0 enables the runtime auto-threshold: 0.5 × the initial maximum force. cg_restart_threshold float 0.2 Restart CG directions when the gradient change ratio exceeds this value. cg_beta_method str \"prp+\" Conjugate gradient beta formula. diis_enabled bool True Enable DIIS extrapolation acceleration. diis_store_every int 5 Store a DIIS snapshot every N steps. diis_min_snapshots int 3 Minimum snapshots required before DIIS extrapolation is attempted. diis_memory int 6 Maximum number of DIIS snapshots stored. verbose int 1 Output verbosity level.","title":"SD/CG Optimization - MAPLE","trail":["Tasks","Optimization","SD/CG"],"type":"Task","url":"tasks/opt/opt_sdcg.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/opt/opt_sdcg.html","page_entry":false,"page_role":"content","section_order":3,"text":"#model=uma #opt(method=sdcg) #device=gpu0 C -0.77812600 -1.06756100 0.32105900 C 1.30255300 0.05212000 -0.02829900 C -0.97199300 1.45624900 0.82365700 C 1.98122900 -0.41843300 1.25017500 C 2.26403300 0.43516800 -1.13310700 N 0.29116400 -0.87682100 -0.50039900 N -2.01916300 -1.37200600 -0.23311200 O -1.66473400 1.63022300 -0.40183700 H -2.25863200 0.87013900 -0.47589900 H 0.02784900 -0.67831200 -1.45849500 H -0.60975900 -1.36785600 1.34117800 H 0.68126400 0.91830000 0.28694100 H -2.57326300 -2.05736100 0.25741200 H -2.05242800 -1.50454200 -1.23382300 H -0.36899300 2.35139200 0.99174700 H -1.63960900 1.29421500 1.67465300 H 2.76444900 0.29146200 1.52284600 H 1.72511400 0.73069500 -2.03779400 H 2.43559300 -1.40609800 1.13421500 H 1.27300500 -0.44722400 2.08057900 H 2.85034500 1.29869700 -0.81432200 H 2.96000900 -0.36880600 -1.38891000","title":"SD/CG Optimization - MAPLE","trail":["Tasks","Optimization","SD/CG"],"type":"Task","url":"tasks/opt/opt_sdcg.html#input-example"},{"heading":"When to Use","level":2,"page":"tasks/opt/opt_sdcg.html","page_entry":false,"page_role":"content","section_order":4,"text":"Distorted starting geometries: The SD phase rapidly reduces large forces without requiring any history, then hands off to CG for efficient final convergence — combining the robustness of SD with the speed of CG. When L-BFGS oscillates: If L-BFGS enters a cycle of large oscillating steps, SD/CG can provide a more stable convergence path. General-purpose fallback: SD/CG is a reliable choice whenever L-BFGS or RFO fails to converge, without requiring manual tuning of which phase to use.","title":"SD/CG Optimization - MAPLE","trail":["Tasks","Optimization","SD/CG"],"type":"Task","url":"tasks/opt/opt_sdcg.html#when-to-use"},{"heading":"Convergence Behaviour","level":2,"page":"tasks/opt/opt_sdcg.html","page_entry":false,"page_role":"content","section_order":5,"text":"The figures below show a typical SD/CG run on a 22-atom organic molecule (UMA model). The vertical dotted line marks the automatic switch from the SD phase to the CG phase. Energy drops steeply during SD, then the CG phase refines to convergence. Fig. 1 — Energy convergence (SD/CG) Fig. 2 — Force convergence (SD/CG) Note For production-quality geometry optimizations, L-BFGS (the default) is generally preferred due to its superior convergence near minima. SD/CG is most useful as a pre-optimizer for severely distorted structures or when L-BFGS has difficulty converging.","title":"SD/CG Optimization - MAPLE","trail":["Tasks","Optimization","SD/CG"],"type":"Task","url":"tasks/opt/opt_sdcg.html#convergence"},{"heading":"Geometry Optimization","level":1,"page":"tasks/opt/optimization.html","page_entry":true,"page_role":"landing","section_order":0,"text":"","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#geometry-optimization"},{"heading":"Overview","level":2,"page":"tasks/opt/optimization.html","page_entry":false,"page_role":"landing","section_order":1,"text":"Geometry optimization minimizes the molecular energy by iteratively adjusting nuclear positions until the forces acting on all atoms fall below predefined convergence thresholds. Starting from an initial structure, the optimizer walks downhill on the potential energy surface to locate the nearest local minimum. MAPLE provides several optimization algorithms suited to different problem types, ranging from efficient quasi-Newton methods to simple gradient-based approaches. The default optimizer, L-BFGS, is appropriate for the vast majority of systems.","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#overview"},{"heading":"Available Methods","level":2,"page":"tasks/opt/optimization.html","page_entry":false,"page_role":"landing","section_order":2,"text":"Method Keyword Description L-BFGS lbfgs Limited-memory BFGS quasi-Newton method. Default and recommended for most systems. RFO rfo Rational Function Optimization with trust radius control. More robust for difficult cases. SD sd Steepest descent. Simplest first-order method; follows the negative gradient. CG cg Conjugate gradient. Improved convergence over SD with minimal additional cost. SD/CG sdcg Hybrid steepest-descent / conjugate-gradient. Starts with SD, switches to CG automatically.","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#available-methods"},{"heading":"Quick Usage","level":2,"page":"tasks/opt/optimization.html","page_entry":false,"page_role":"landing","section_order":3,"text":"To run a geometry optimization, add the #opt directive to your input file. The method can be specified in parentheses: #opt(method=lbfgs) If no method is specified, L-BFGS is used by default: #opt","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#quick-usage"},{"heading":"Input Example","level":2,"page":"tasks/opt/optimization.html","page_entry":false,"page_role":"landing","section_order":4,"text":"A complete input file for a geometry optimization using the UMA model on a GPU device: #model=uma #opt(method=lbfgs) #device=gpu0 C -0.77812600 -1.06756100 0.32105900 C 1.30255300 0.05212000 -0.02829900 C -0.97199300 1.45624900 0.82365700 C 1.98122900 -0.41843300 1.25017500 C 2.26403300 0.43516800 -1.13310700 N 0.29116400 -0.87682100 -0.50039900 N -2.01916300 -1.37200600 -0.23311200 O -1.66473400 1.63022300 -0.40183700 H -2.25863200 0.87013900 -0.47589900 H 0.02784900 -0.67831200 -1.45849500 H -0.60975900 -1.36785600 1.34117800 H 0.68126400 0.91830000 0.28694100 H -2.57326300 -2.05736100 0.25741200 H -2.05242800 -1.50454200 -1.23382300 H -0.36899300 2.35139200 0.99174700 H -1.63960900 1.29421500 1.67465300 H 2.76444900 0.29146200 1.52284600 H 1.72511400 0.73069500 -2.03779400 H 2.43559300 -1.40609800 1.13421500 H 1.27300500 -0.44722400 2.08057900 H 2.85034500 1.29869700 -0.81432200 H 2.96000900 -0.36880600 -1.38891000","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#input-example"},{"heading":"Common Parameters","level":2,"page":"tasks/opt/optimization.html","page_entry":false,"page_role":"landing","section_order":5,"text":"These parameters are shared across all optimization methods. Individual methods may accept additional method-specific parameters. Parameter Default Description method lbfgs Optimization algorithm to use (see table above). level medium Convergence level preset. Options: extratight , tight , medium (default), loose , extraloose , superloose . max_iter 256 Maximum number of optimization cycles before the calculation is terminated.","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#common-parameters"},{"heading":"Output Files","level":2,"page":"tasks/opt/optimization.html","page_entry":false,"page_role":"landing","section_order":6,"text":"A successful optimization produces the following output files: *_opt.xyz — The final optimized geometry in XYZ format. This is the primary result file. *_opt_traj.xyz — The optimization trajectory containing geometries written during the run. Useful for visualizing the optimization path in molecular viewers. *.out — The main output log containing energies, forces, convergence diagnostics, and timing information at each step. Tip For routine optimizations, the default L-BFGS method with level=medium is sufficient. Switch to level=tight when computing vibrational frequencies on the optimized geometry to ensure accurate Hessian evaluation.","title":"Geometry Optimization - MAPLE","trail":["Tasks","Optimization"],"type":"Task","url":"tasks/opt/optimization.html#output-files"},{"heading":"ParmFit","level":1,"page":"tasks/parmfit/parmfit.html","page_entry":true,"page_role":"landing","section_order":0,"text":"","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#parmfit"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":1,"text":"ParmFit is the MAPLE force-field parameterization task. It turns MAPLE calculator results, existing topology files, and optional external QM references into Amber-style parameters for ligand/cofactor correction, noncanonical amino-acid templates, and metal-site parameterization. ParmFit has three public method keywords. method=refinement refines parameters for an existing mol2 topology. method=ncaa parameterizes noncanonical amino-acid residues and method=metalaa parameterizes a metal site; both read a hydrogenated PDB block. ParmFit calls AmberTools utilities to handle parameter assignment and template generation; the required tools are listed under Requirements . Before running MD with a ParmFit topology, follow each route’s deployment checks — the tleap validation must report Errors: 0 , the fitted charges must match their targets, and MAPLE-typed topologies go through a ParmEd pass before SHAKE. Fig. 1 — The three ParmFit routes. Dashed boxes are optional stages (config switches). Each column lists the engines that route actually calls.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#overview"},{"heading":"Routes","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":2,"text":"Route Keyword Target Main Products Refinement refinement Ligand, cofactor, or small molecule with existing mol2 topology Refined Amber mol2/frcmod and GROMACS top/gro NCAA ncaa Protein residue in a PDB file Residue prepin/frcmod, processed PDB, tleap validation files MetalAA metalaa Ion in a PDB metal site Metal-site mol2, metal frcmod, tleap deployment files The method keyword selects the route; without an explicit method (and without input= ), ParmFit defaults to refinement . The input for each route — its header keys and the required structure block (a coordinate block for Refinement, a PDB block for NCAA and MetalAA) — is specified in that route’s manual. The ParmFit Tutorials work through each route on a real system.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#routes"},{"heading":"Requirements","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":3,"text":"All routes need a working MAPLE installation and AmberTools on PATH — a run invokes whichever utilities it needs: parmchk2 , antechamber , prepgen , espgen , resp , and tleap . Refinement relies on GAFF2 atom typing: supply a pre-generated mol2 ( antechamber -at gaff2 ... ), or omit mol2= and ParmFit does the typing itself at runtime, building the mol2 from the molecule recorded in the input file. That generated mol2 exists only to carry the GAFF2 types — its charge column holds zero placeholders, and chg_fit therefore defaults to abcg2 (see the Refinement page ). In both cases the mol2 atoms must appear in the same order as the coordinate block, hydrogens included — the auto-generated mol2 satisfies this by construction; MAPLE checks only that the atom counts match and then pairs atoms by position. NCAA and MetalAA read exactly one PDB block and need no separate atomic-charge input. Refinement may preserve the charges already stored in the input mol2 when chg_fit=none ; the other charge routes derive charges at runtime (see ChargeFit below). When RESP charges are needed. They always take their ESP from Gaussian: g16 or g09 must be on PATH for Refinement and NCAA runs with chg_fit=resp (the NCAA default) and for every MetalAA run. QM reference jobs ( iqm=true ) use qm_engine , which defaults to g16 ; set qm_engine=orca to run them with ORCA instead. A Refinement or NCAA run therefore needs no Gaussian when chg_fit is not resp and the run keeps iqm=false or sets qm_engine=orca ; MetalAA always needs Gaussian. How MAPLE reads PDB structures. The PDB must be explicitly hydrogenated; MAPLE neither adds nor removes hydrogens. While reading the PDB, MAPLE builds a connectivity graph and matches standard protein residues against the active pro_ff Amber templates using element composition, topology, explicit hydrogens, and chirality. Matched residues receive canonical atom names, atom types, partial charges, residue net charges, and Amber connectivity — the atom names are rewritten to the canonical template names before tleap export — so standard input atom names are not required. Cysteine states are resolved in two steps: explicit SG–H connectivity distinguishes protonated CYS from the deprotonated CYM / CYX candidates, and the graph-equivalent CYM / CYX pair is decided by disulfide-bond detection — a cysteine participating in an S–S bond is assigned CYX (net charge 0), otherwise CYM (net charge −1). Alternate conformations resolve by default to the altloc A set, or to the highest-occupancy set when A is absent; keep chooses among them when a listed residue carries several alternate conformations — append the altloc letter ( A181B ) to build that residue from its altloc-B atoms, while a letterless entry ( A181 ) keeps the default choice. Residues without a complete standard template are reported, not guessed: backbone-only matches (NCAA candidates) and unmatched nonprotein residues, which should be declared via lig_resids / ncaa_resids in MetalAA or parameterized in separate NCAA runs. Read the tleap validation warnings. Errors: 0 is the gate; the warnings decide whether the topology is safe to use. Most are routine — terminal-name conversions ( NTHR -> THR ) and an addIons request after neutralization. The tutorials list and explain the warnings of their verified runs.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#requirements"},{"heading":"General Settings","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":4,"text":"These parameters apply across all ParmFit routes. For iqm behavior, qm_mode , and levels of theory ( opt_level / sp_level / chg_level ), see the QM Reference section below. Parameter Default Description qm_engine g16 External QM engine: g16 , g09 , gaussian , or orca qm_nproc 8 Number of processors for QM jobs qm_mem 24 Memory in GB for QM jobs; adjust this according to the available memory and the size of the selected QM reference model. opt_max_iter 256 Maximum LBFGS iterations for MLIP geometry optimization. In Refinement, use max_iter instead. opt_max_step 0.2 Maximum LBFGS step size in Å for MLIP geometry optimization. In Refinement, use max_step instead.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#general-settings"},{"heading":"ChargeFit","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":5,"text":"chg_fit selects the atomic-charge source independently of iqm and qm_compare . Refinement defaults to none ; the input mol2 charges are kept as they are. NCAA defaults to resp ; none is invalid because the PDB route has no reusable input charges. MetalAA derives site charges through a fixed RESP-only workflow and does not expose chg_fit . chg_fit Behavior none Refinement only. Preserve the input mol2 charges without creating a charge-fitting work directory. resp Derive charges at runtime: Gaussian evaluates the ESP, AmberTools ( espgen + resp ) performs the two-stage RESP fitting. chg_level defaults to HF/6-31G(d) for Refinement and NCAA, and the resp_backend key accepts only its default, gaussian . Charge-capable MLIP Use AIMNet2 ( aimnet2 ), AIMNet2-NSE ( aimnet2nse ), or MACE-POLAR ( macepols , macepolm , or macepoll ). A recognized MLIP must provide atomic charges; otherwise ParmFit reports a capability error. Unrecognized value Pass the value verbatim to antechamber -c , for example abcg2 , bcc , or gas . ParmFit does not maintain an Antechamber charge-method whitelist. RESP derivation always runs the same two-tool pipeline — Gaussian for the ESP, AmberTools for the RESP stages — whether iqm is enabled or disabled; its Gaussian jobs reuse the configured qm_nproc and qm_mem . The charge-capable MLIP may differ from the main #model . If it matches the main model, ParmFit reuses the active calculator and its configured options. A different charge-capable MLIP is initialized once on the active device with its default options.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#chargefit"},{"heading":"TorsionFit","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":6,"text":"TorsionFit refines proper torsion parameters in two stages. Stage 1 uses a spectral shared-group restrained linear least-squares solver: torsion instances that share the same chemical environment (atom types plus one-hop neighbors) are grouped and fitted together, with a spectral helper providing phase seeds. Stage 2 takes the Stage 1 parameters and performs direct global kPhi / phase optimization against the scan reference profile. torsion_refine_rounds controls how many Stage 1→Stage 2 fast-MM cycles are attempted. Each cycle refreshes the MM reference profiles — the first from the Stage 0 parameters (the mSeminario-refined starting point), later ones from the previous round’s accepted parameters — and re-runs Stage 1 and Stage 2. A cycle is accepted only if total loss improves; otherwise the workflow rolls back and stops. With torsion_refine_rounds=0 , only Stage 1 runs. TorsionFit applies to Refinement and NCAA routes. The fitted dihedrals differ by route: Refinement auto-selects rotatable single bonds from the mol2 topology; NCAA restricts fitting to sidechain dihedrals and disables torsion ensemble terms internally. Parameter Default Description torsionfit true Enable proper torsion fitting after the bond/angle stage torsion_bonds Auto Explicit rotatable bonds as atom pairs, order-insensitive ( 6-10 = 10-6 ; e.g. 6-8,12-14 ); otherwise auto-selected from mol2 topology. In NCAA, entries are residue-local 1-based atom indices within the target residue (ACE/NME caps not counted) and per-residue groups are separated with ; torsion_steps 36 Scan steps for a full 360° rotation of a torsion; the step size is 360° divided by this value stage1_weights true Weight scan frames by reference energy in the Stage 1 least-squares fit; false gives all frames equal weight torsion_refine_rounds 3 Maximum Stage 1→Stage 2 fast-MM cycles torsion_refine_max_iter 256 Maximum iterations for the Stage 2 global optimizer torsion_refine_tol 1.0e-6 Convergence tolerance for Stage 2 torsion_ensemble false Add rigid rotor ensemble frames as extra Stage 2 constraints in Refinement; NCAA disables this internally torsion_ensemble_ratio 0.3 Target ensemble frame ratio relative to rotatable bonds × steps in Refinement torsion_ensemble_weight 0.5 Weight of ensemble loss relative to scan loss in Refinement Stage 2 backend cgbs TorsionFit scan optimizer backend: cgbs , cgws , or lbfgs constraint_mode projected Scan constraint mode: projected or fixinternals (not recommended to change)","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#torsionfit"},{"heading":"Scan Reuse","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":7,"text":"Before each scan, TorsionFit looks under <base>_work/torsionfit/ for the scan file that an earlier run wrote for the same target. If that file has the expected number of frames and the same elements, and its scan angles match those of the current starting geometry, TorsionFit reads and reuses it, and the log does not report the reuse. The check ignores the model and the QM level of theory, so delete <base>_work/torsionfit/ before you rerun with either of them changed.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#scan-reuse"},{"heading":"QM Reference (iqm)","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":8,"text":"iqm controls whether external QM jobs provide reference-quality geometry, Hessian, and torsion data. When iqm=false , all optimization, Hessian evaluation, and torsion reference work use the MAPLE MLIP calculator exclusively. When iqm=true , MAPLE runs QM reference jobs whose scope depends on the route. QM RESP does not require iqm Setting iqm=false does not disable QM charge derivation. Refinement and NCAA still derive charges through Gaussian ESP and AmberTools RESP when chg_fit=resp , and MetalAA always runs its fixed RESP workflow. iqm controls only whether external QM supplies reference geometry, Hessian, and torsion data. Route iqm=false iqm=true Refinement MLIP opt + MLIP Hessian (+ MLIP TorsionFit if enabled) QM opt_frequency → QM geometry + QM Hessian (+ QM-referenced TorsionFit via qm_mode ). If bonded=none but torsionfit=true , only a QM geometry optimization is run—no Hessian is computed. NCAA MLIP capped-model opt + MLIP Hessian QM reference job on the capped model, but only when bonded≠none or torsionfit=true : bonded≠none runs QM opt_frequency (geometry + Hessian); bonded=none with torsionfit=true runs only a QM geometry optimization. MetalAA MLIP large-model opt + MLIP Hessian QM opt_frequency after MLIP opt → QM geometry + QM Hessian for bonded fitting. No TorsionFit, no qm_mode .","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#iqm"},{"heading":"Levels of Theory","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":9,"text":"Parameter Refinement NCAA MetalAA chg_level HF/6-31G(d) ; RESP ESP when chg_fit=resp HF/6-31G(d) ; RESP ESP when chg_fit=resp PBE1PBE/def2SVP ; RESP ESP in the fixed workflow opt_level QM opt/opt_freq/constrained_opt when iqm=true QM opt/opt_freq when iqm=true QM opt_freq when iqm=true sp_level QM single-point via qm_mode when iqm=true ; defaults to opt_level QM single-point via qm_mode when iqm=true ; defaults to opt_level Unused (no TorsionFit) Level strings are passed to the QM engine verbatim, so write them the way the selected engine expects: B3LYP/def2SVP for Gaussian, B3LYP/def2-SVP for ORCA. A mismatched spelling — for example the hyphenated form with qm_engine=g16 — fails at the first QM job with a route syntax error. RESP chg_level values always follow Gaussian syntax. The built-in defaults of opt_level and sp_level are written B3LYP/def2-SVP , the ORCA spelling, while the default engine is g16 . Set opt_level explicitly (for example B3LYP/def2SVP ) before enabling iqm with Gaussian.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#levels-of-theory"},{"heading":"TorsionFit qm_mode","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":10,"text":"qm_mode controls how QM reference data is used inside TorsionFit (Refinement and NCAA; mode 1 is the default). It has no effect on MetalAA. Mode Description 1 MLIP drives the torsion scan, then QM single-point energies are calculated at each frame 2 MLIP pre-optimization, then QM constrained torsion optimization at each frame 3 QM engine evaluates energy and forces at each scan step; the built-in optimizer of MAPLE drives the scan","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#qm-mode"},{"heading":"qm_compare (Refinement only)","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":11,"text":"When iqm=true , qm_compare=true , and refinement is enabled, Refinement runs an additional MLIP-only comparison branch alongside the QM path. The MLIP branch produces _mlip -suffixed output files, so its parameters can be compared against the QM-referenced ones without re-running the workflow. Charge fitting uses the same configured chg_fit method independently on the QM and MLIP branch geometries, so each branch reports its own charged work mol2.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#qm-compare"},{"heading":"External ParmFit Config","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":12,"text":"For more complex jobs, use a separate key-value text file and reference it from the input header. Any plain text file with key=value lines and optional # comments is accepted. The config file accepts parmfit parameters only; do not place global MAPLE keys in it. Declare the method inline together with the input= reference, for example #parmfit(method=ncaa,input=...) . #model=uma(size=uma-s-1p1) #parmfit(method=ncaa,input=NCAA.parmfit) PDB MaDA.pdb Note An external config must not set method= , pdb= , input= , or frcmod= ; declare method in the inline #parmfit(...) header and provide PDB structures through the PDB <path> block of the input file. Refinement frcmod files are generated automatically.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#external-config"},{"heading":"Output Layout","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":13,"text":"ParmFit writes a main .out file and a <base>_work/ directory. Next to the .out file, every route also writes a <base>.parmfitrun.in snapshot of the resolved configuration (user entries with defaults filled in); unrecognized keys are reported as warnings in the log. The excerpts below illustrate key sections of the .out file for each route.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#output-layout"},{"heading":"Refinement","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":14,"text":"The setup header echoes the input mol2, bonded refinement method, QM reference state, and TorsionFit configuration: ====================================================================== Parmfit Refinement Setup ====================================================================== Input mol2: toluene_ff.mol2 Initial frcmod: Toluene_work/Toluene_original.frcmod Topology atoms: ... Topology bonds: ... Bonded refinement: mSeminario QM reference: disabled TorsionFit: enabled Torsion backend: cgbs Torsion bonds: auto-select non-ring torsion bonds with proper torsions The mSeminario bond/angle changes table lists each modified BOND and ANGLE term with its type code (atom pairs for BOND, atom triples for ANGLE) and old → new values: ------------------------------------------------------------------------------------------------------------ BONDS ------------------------------------------------------------------------------------------------------------ (1,2) c3-ca k=... r=... | k=... r=... ... ------------------------------------------------------------------------------------------------------------ ANGLES ------------------------------------------------------------------------------------------------------------ (2,1,8) ca-c3-hc k=... theta=... | k=... theta=... ... The TorsionFit dihedral changes table shows per-torsion kPhi / n / phase changes across multiple term slots; NA entries indicate newly added terms: ------------------------------------------------------------------------------------------------------------ DIHEDRALS ------------------------------------------------------------------------------------------------------------ (3,2,1,8) ca-ca-c3-hc term=1 k=... n=1 phase=... | k=... n=1 phase=... (3,2,1,8) ca-ca-c3-hc term=2 k=NA n=NA phase=NA | k=... n=2 phase=... ... The torsion energy trace gives per-dihedral angle-versus-energy profiles and ends with MAE/RMSE. Its columns are the scan reference (MLIP or QM), the original GAFF2 profile ( orig ), the mSeminario-refined starting point ( stage0 ), and the refitted profiles after each TorsionFit stage ( stage1 , stage2 ). A rejected Stage 2 remains visible as an NA column; the final comparison is labelled stage2_final when Stage 2 is accepted and stage1_final when it is rejected: torsion bond (1, 2): angle_deg MLIP_ref orig_ref stage0_ref stage1_ref stage2_ref ... ... ... ... ... NA ... MLIP_ref vs stage1_final: MAE = ... kcal/mol, RMSE = ... kcal/mol The final PARMFIT REFINEMENT RESULT block lists the products, charge provenance, stage timing, and parameter-change counts: Main products: Amber mol2: Toluene_work/Toluene_maple.mol2 Amber frcmod: Toluene_work/Toluene_maple.frcmod ... Charge fitting: method: resp RESP level: HF/6-31G(d) target charge: ... actual charge: ... work MOL2: Toluene_work/chargefit/mlip_route_charged.mol2 final MOL2: Toluene_work/Toluene_maple.mol2","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#refinement"},{"heading":"NCAA","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":15,"text":"The job header identifies the target residue, chirality, charge method, and progress through each stage: Target: _89:HIF (protein) PDB residue templates: matched=516, backbone_only=1, unmatched=0 non-standard (matched backbone only): _89:HIF (target) PDB target charge: _89:HIF = 0 (from your input) [NCAA] MLIP model preparation + reference optimization ... NCAA target selector: HIF89 residue name: HF1 chirality: L net charge / spin multiplicity: 0 1 protein ff: ff14SB bonded refinement: mseminario charge fitting: resp charge level: HF/6-31G(d) [NCAA] atomic charge fitting (resp) ... [NCAA] AmberTools template build ... [NCAA] MLIP Hessian + mSeminario ... [NCAA] TorsionFit skipped ... [NCAA] writing refined templates + tleap input ... [NCAA] tleap validation ... The PARMFIT NCAA RESULT block confirms the charge result and lists the output files, tleap status, and the exact tleap command to run: Status: completed Route: NCAA Target: _89:HIF Residue name: HF1 Chirality: L Protein ff: ff14SB Res charge/spin-multi: 0 1 Charge fitting: resp Charge level: HF/6-31G(d) Target charge: 0 Actual charge: ... Charge MOL2: MaDA_work/ncaa/HIF89/MaDA_capped.mol2 Main products: refined prepin: MaDA_work/HF1_maple.prepin refined frcmod: MaDA_work/HF1_maple.frcmod tleap PDB: MaDA_work/MaDA_ncaa_tleap.pdb tleap input: MaDA_work/MaDA_ncaa_tleap.in Next step: cd MaDA_work tleap -s -f MaDA_ncaa_tleap.in |tee MaDA_ncaa_tleap.out Tleap status: Errors: 0 Warnings: 4 Notes: 0","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#ncaa"},{"heading":"MetalAA","level":3,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":16,"text":"The job header prints the metal target, site parameters, ion charge and multiplicity, and per-stage logs: Target: A462:FE (ion) ion_resids: A462 add_resid: [] cluster_cutoff: 3.00 A donor_cutoff: 2.70 A water ff: tip3p protein ff: ff14SB ion ff: 12_6 ion_charges: 3 ion_mults: 6 ncaa_resids: [] large model charge/mult: -2 6 chgmod: 1 fixchg_resids: [] QM method: PBE1PBE/def2SV [MetalAA] large-model input written. [MetalAA] MLIP large-model optimization ... [MetalAA] large-model RESP ... [MetalAA] site files written. [MetalAA] MLIP Hessian + Seminario + final frcmod ... [MetalAA] final parameter files written. [MetalAA] running tleap validation ... The renamed atom types table shows how MAPLE reassigns types locally: the metal receives M1 , direct donors receive Z1 / Z2 /..., and other atoms keep their original Amber/GAFF types. Verify that the donor list matches the intended coordination environment: Renamed atom types: residue atom old new charge _400:CYM SG SH Z1 -0.329172 A461:HEM NA nc Z2 -0.129187 ... A462:FE FE FE M1 0.439642 The PARMFIT METALAA RESULT block lists core residues, output files, tleap status, any environment warnings, and the tleap command: Status: completed Route: MetalAA Target: A462:FE Protein ff: ff14SB Ions charge: 3 Large model charge/mult: -2 6 Core residues: _400:CYM, A461:HEM, A462:FE Main products: final frcmod: P450_work/P450_metal.frcmod tleap input: P450_work/P450_metal_tleap.in tleap PDB: P450_work/P450_metal_tleap.pdb mol2 files: P450_work/CM1.mol2, P450_work/HM1.mol2, P450_work/FE1.mol2 Next step: cd P450_work tleap -s -f P450_metal_tleap.in |tee P450_metal_tleap.out Tleap status: Errors: 0 Warnings: 8 Notes: 1 Warnings: Potentially charged standard residues within 8 Å of the metal but outside the large model: _398:ARG","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#metalaa"},{"heading":"Troubleshooting","level":2,"page":"tasks/parmfit/parmfit.html","page_entry":false,"page_role":"landing","section_order":17,"text":"Symptom Cause Fix Gaussian executable … was not found The run derives RESP charges or runs a QM reference job, and MAPLE cannot find the Gaussian executable ( g16 or g09 ) on PATH . Put Gaussian on PATH , or run without it as described in Requirements . The first Gaussian job stops with a route syntax error. A hyphenated level such as B3LYP/def2-SVP reached Gaussian; the built-in opt_level default is written this way. Write B3LYP/def2SVP for Gaussian; see Levels of Theory . Duplicate parmfit config key '<key>' at <file>:<line>. The sidecar config sets one key twice, for example after lines were appended to a copied config. Keep one line per key: edit the existing line instead of adding another. Unknown left-hand '<key>' in parmfit config (warning) No builder used the key: a misspelling, a key of another route, or level placed in the sidecar, where it has no effect and the run continues without it. Correct the key. level belongs in the #parmfit(...) header, where its convergence thresholds take effect; the warning line prints either way. A run without input= also reports the four *_th thresholds that MAPLE applies to the atoms — those lines are expected. Invalid parmfit config line <file>:<lineno>; expected key=value. A line in the sidecar config contains no = — often text pasted into the file. Delete the line or turn it into a # comment. Invalid residue selector '…' or Selector … matched multiple residues The selector is malformed, or a residue name and number fit several residues. Use a chain and number ( A462 ) or a name and number ( HIF89 ); when a name and number fit several residues, switch to the chain form. See Target in the NCAA and MetalAA manuals.","title":"ParmFit - MAPLE","trail":["Tasks","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit.html#troubleshooting"},{"heading":"ParmFit MetalAA","level":1,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#parmfit-metalaa"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":1,"text":"MetalAA is the parmfit(method=metalaa) route for a PDB target ion selected with ion_resids . It locates the target ion and identifies its coordination environment: donor atoms are detected among N, O, S, P, Se, F, Cl, Br, I within donor_cutoff (default 2.7 Å). The target ion, its donor residues, and any add_resid entries together form the core . Explicit metal-donor SERIAL pairs can be provided via set_bonded to override automatic recognition. MetalAA then constructs two models. A large model (core + environment residues within cluster_cutoff ) is built for MLIP optimization, RESP charge fitting, and Hessian-based bonded parameterization. Broken peptide boundaries are sealed with ACE/NME caps , and when two selected peptide residues on one chain are at most five sequence positions apart, the intervening residues between them are rewritten as Gly bridges to maintain backbone connectivity. A site model (target metal + final core residues only) is the deployable output; declared NCAA residues outside the site model are folded into the tleap deployment alongside it. RESP charges from the large model are projected onto the site model. In the deployable site model, residue names are changed to compact export codes (e.g. CYM becomes CM1 , HID becomes HD1 ) and atom types are renamed locally: the metal receives M1 / M2 /..., each direct donor atom receives Z1 / Z2 /..., while other atoms retain their original forcefield types. For a worked walkthrough, see the MetalAA tutorial . Initial Prepare How MAPLE reads PDB structures is described once in the Requirements section of the ParmFit hub. What is route-specific here: nonprotein ligands and cofactors near the metal site have no protein template; declare them via lig_resids (small-molecule build) or ncaa_resids (NCAA residue build).","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#overview"},{"heading":"Target","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":2,"text":"ion_resids must identify exactly one ion residue in the input PDB. Use a chain and residue number such as A462 , an ion residue name and number such as FE462 , or append an altloc label when needed, for example A462A for altloc A. The selected residue must contain a single ion atom recognized by MAPLE. It defines the center for donor detection and metal-site construction; add_resid and set_bonded extend that site without changing the target. Charge convention (ion_charges / ion_mults) ion_charges is the formal charge carried by the target metal ion; it drives metal typing and ion frcmod selection. The large-model net charge is computed as Q_large = ion_charges + Σ net_charge(other residues) : every other residue contributes its declared charge ( lig_charges , ncaa_charges ) or the net charge of its Amber graph template. ion_mults is the spin multiplicity of the QM cluster (large model). Residues without a complete Amber template are counted as zero for the time being. Declare unmatched nonprotein residues via lig_resids (or ncaa_resids ) so they are parameterized and charged explicitly rather than left at zero. Site charges are RESP-only MetalAA does not expose chg_fit . Site charges are always derived at runtime — Gaussian evaluates the large-model ESP and AmberTools performs the two-stage RESP fitting. chg_level and chg_route control that calculation, while chgmod and fixchg_resids keep their standard fixed-charge behavior. The projected site charges must close to the integer site charge — a run that finishes has passed that check.","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#target"},{"heading":"Workflow","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":3,"text":"The route in outline: Algorithm 3 — MetalAA: parameterizing a metal site Require: protein PDB; metal ion declaration; ligand / NCAA declarations; config Ensure: site frcmod, per-residue mol2; validated tleap topology Read the PDB with template matching; locate the metal ion. Ligand building: copy each declared ligand, fit charges, type with AmberTools, register the cofactor frcmod. ▹ chgfit: abcg2 , resp , … NCAA building for declared residues. ▹ reuses the residue-build components of Algorithm 2 : one optimized capped conformer, RESP on that conformer, antechamber/parmchk2 template; unlike standalone NCAA, no α/β pair, no Hessian refinement, no TorsionFit. Standard residues may be deliberately rebuilt Construct the cluster: metal, coordinating donors, environment. Optimize the cluster with the MLIP. ▹ optionally QM Fit charges with RESP on the cluster; project onto the site model. Derive bonded terms with Seminario and write the site frcmod. Export the site artifacts and validate with tleap. Metal-site recognition. Locate the target ion, donor atoms, core residues, and optional user-added residues. Ligand building. For each declared ligand ( lig_resids ): copy the residue, fit its charges, type it with AmberTools, and register the cofactor frcmod. NCAA building. Declared residues ( ncaa_resids ) are built with the residue-build components of the NCAA route: one optimized capped conformer, RESP on that conformer, and an antechamber/parmchk2 template — without the α/β pair, Hessian refinement, or TorsionFit of the standalone NCAA route. How the fitted charges enter the deployment depends on placement: a residue that coordinates the metal is fitted freely with the site; a non-coordinating residue inside the large model has its fitted charges frozen into the site RESP; a residue outside the large model keeps its independent charges and is folded into the tleap export. Large model. Build and optimize a large metal-site model for RESP, Hessian, and parameter fitting. RESP charges. Gaussian evaluates the ESP of the optimized large model and AmberTools performs the two-stage RESP fit; the charges are then projected onto the deployable site model. Bonded fitting. Use Seminario or modified Seminario to fit metal-related bond and angle terms. Deployment files. Write site mol2, final metal frcmod, tleap PDB/input, and dry/solvated tleap outputs. MetalAA runs tleap itself; the result block prints the command under Next step .","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#workflow"},{"heading":"Core Parameters","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":4,"text":"Parameter Default Description ion_resids Required Unique PDB selector for the central ion residue; see Target . ion_charges 0 Formal charge of the target metal ion, used for ion typing and frcmod selection; see the charge convention above. ion_mults 1 Spin multiplicity of the QM cluster (large model). lig_resids , lig_charges , lig_mults None Coordinating ligand/cofactor residue selectors, their 1:1 formal charges, and their spin multiplicities (default 1); ligands are parameterized as small molecules in lig/<tag>/ . lig_chgfit abcg2 Charge method for declared ligands ( lig_chglevel defaults to HF/6-31G(d) ; lig_chgroute is empty). ncaa_resids , ncaa_charges None Noncanonical residues — or standard residues deliberately rebuilt — in the site, built with the NCAA residue-build components; pair ncaa_charges 1:1, optionally ncaa_resnames / ncaa_mults . A coordinating residue is fitted freely with the site; a non-coordinating one inside the large model has its charges frozen into the site RESP, and one outside the large model is folded into the tleap export. ncaa_chgfit , ncaa_chglevel , ncaa_chgroute resp , HF/6-31G(d) , empty Charge route for NCAA-built residues and its Gaussian level/route; the fitted charges follow the placement rules under ncaa_resids . add_resid None Additional residues to force into the metal-site core; core membership puts a residue into the RESP charge fit, the Hessian-bonded fitting, and the deployed site model. set_bonded Auto Explicit metal-donor serial pairs, written as SERIAL-SERIAL tokens. keep None Chooses which alternate conformation to build when the PDB lists several for a residue: append the altloc letter to the selector ( A181B ) to build that residue from its altloc-B atoms; an entry without a letter keeps the default resolution (altloc A, else the highest-occupancy set). cluster_cutoff 3.0 Cutoff in Angstrom for collecting large-model environment residues. Environment residues participate in large-model optimization, RESP, and Hessian evaluation; during RESP each non-core residue is constrained to its reference net charge, and these residues are excluded from the deployed site model. donor_cutoff 2.7 Cutoff in Angstrom for automatic metal-donor detection. chgmod 1 RESP fixed-charge policy for standard backbone atoms. fixchg_resids None Residues whose charges should be fixed to standard Amber references during RESP. iqm false QM reference for geometry optimization and Hessian work. See the main ParmFit page for details. chg_level PBE1PBE/def2SVP Gaussian level for RESP ESP generation. Always active regardless of iqm . chg_route Empty Additional Gaussian route text for RESP ESP jobs. pro_ff , wat_ff , ion_ff ff14SB , tip3p , 12_6 Protein, water, and ion parameter models for tleap deployment. MetalAA validates ion_ff against hfe , cm , iod , 12_6 , and 12_6_4 . bonded mseminario Metal-related bond/angle fitting: mseminario or seminario . vib_scale 1.0 Vibrational frequency scale factor for Hessian-based fitting. For qm_engine , opt_level , QM job resources, and MLIP optimization controls, see the General Settings and QM Reference sections of the main ParmFit page.","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#parameters"},{"heading":"ChargeFit","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":5,"text":"","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#chargefit"},{"heading":"RESP Fixed Charges (chgmod)","level":3,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":6,"text":"The chgmod parameter controls which standard backbone atoms are fixed to their Amber reference charges during RESP fitting. Higher values include more atoms in the fixed set: chgmod Fixed atoms Description 0 (none) No automatic backbone fixing; user controls charges through fixchg_resids 1 N, CA, C, O, OXT Fix backbone heavy atoms to Amber reference charges 2 N, H, HA, CA, C, O, OXT Add amide H and alpha H 3 N, H, HA, CA, CB, C, O, OXT Add CB (sidechain anchor) Use fixchg_resids to lock entire residues to standard Amber reference charges regardless of the chgmod policy. A listed residue outside the large model is skipped with a warning. Specifying a non-standard residue that lacks a reference charge entry stops the run with an error at the RESP stage.","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#chgmod"},{"heading":"Input Files","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":7,"text":"","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#parmfit-input"},{"heading":"Simple Input","level":3,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":8,"text":"A simple MetalAA job declares method=metalaa inline and lists its ParmFit options in a sidecar config. The ion_resids selector picks the metal ion; ion_charges / ion_mults give the metal formal charge and the cluster multiplicity, and lig_resids / lig_charges declare the cofactor. The example is Case 1 of the MetalAA tutorial , which provides the input files and 4ZF6.pdb . There the heme carries −4 — the porphyrin dianion (−2) plus two deprotonated propionates — and Fe(III) +3 with the thiolate −1 gives the large-model charge −2; use the charge that matches the protonation state of your own cofactor. #model=uma(size=uma-s-1p1) #parmfit(method=metalaa,input=MetalAA1.in) #device=gpu0 PDB 4ZF6.pdb MetalAA1.in # MetalAA route settings; declare method=metalaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. ion_resids=A462 ion_charges=3 ion_mults=6 lig_resids=A461 lig_charges=-4 bonded=seminario chg_level=PBE1PBE/def2SV","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#simple-input"},{"heading":"Full External Input","level":3,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":9,"text":"For a more complex setup, keep the MAPLE launcher short and move ParmFit parameters into an external .parmfit file. Declare method=metalaa inline together with input= ; the external config must not set method= . The PDB remains in the MAPLE input. #model=uma(size=uma-s-1p1) #parmfit(method=metalaa,input=MetalAA.parmfit) #device=gpu0 PDB 4ZF6.pdb Full ParmFit config MetalAA.parmfit # QM reference iqm=false qm_engine=g16 opt_level=B3LYP/def2SVP opt_route= qm_nproc=8 qm_mem=24 # RESP charges resp_backend=gaussian chg_level=PBE1PBE/def2SVP chg_route= chgmod=1 fixchg_resids= # Force field, water, ion, and bonded fitting pro_ff=ff14SB wat_ff=tip3p ion_ff=12_6 bonded=mseminario vib_scale=1.0 # MLIP geometry optimization controls opt_max_iter=256 opt_max_step=0.2 # MetalAA site selection ion_resids=A462 ion_charges=3 ion_mults=6 add_resid= set_bonded= cluster_cutoff=3.0 donor_cutoff=2.7 keep= # Coordinating ligands, built as small molecules lig_resids=A461 lig_charges=-4 lig_mults=1 lig_chgfit=abcg2 lig_chglevel=HF/6-31G(d) lig_chgroute= # Noncanonical residues in the site, built with the NCAA residue-build components ncaa_resids= ncaa_charges= ncaa_resnames= ncaa_mults= ncaa_chgfit=resp ncaa_chglevel=HF/6-31G(d) ncaa_chgroute=","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#full-external-input"},{"heading":"Output Files","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":10,"text":"<base>_work/<base>_metal_large_raw.pdb and <base>_work/<base>_metal_large_opt.pdb : Large model before and after optimization. <base>_work/<base>_metal_site_opt.pdb and <base>_work/<base>_metal_site.mol2 : Deployable metal-site model. <base>_work/<base>_metal.frcmod : Final metal/cofactor frcmod file. <base>_work/<base>_metal_tleap.pdb , <base>_work/<base>_metal_tleap.in , and <base>_work/<base>_metal_tleap.out : tleap deployment and validation files. <base>_work/<base>_metal_tleap_dry.* and <base>_work/<base>_metal_tleap_solvated.* : dry and solvated topology/coordinate outputs. <base>_work/metalaa/ : Gaussian ESP, RESP, and intermediate charge-fitting files. <base>_work/lig/<tag>/ : Per-ligand small-molecule parameterization (antechamber build and parmchk2 frcmod). <base>_work/ncaa/<tag>/ : Per-residue NCAA builds for declared ncaa_resids entries.","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#output-files"},{"heading":"Requirements and Limits","level":2,"page":"tasks/parmfit/parmfit_metalaa.html","page_entry":false,"page_role":"content","section_order":11,"text":"Current MetalAA is intended for a single metal center; a second ion inside the donor cutoff is not supported. Ligand or cofactor residues without reliable atom types should be declared through lig_resids (small-molecule build) or ncaa_resids (NCAA residue build: one conformer, RESP, AmberTools template). When automatic donor detection is not sufficient, use set_bonded to provide explicit metal-donor serial pairs.","title":"ParmFit MetalAA - MAPLE","trail":["Tasks","ParmFit","MetalAA"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa.html#requirements"},{"heading":"MetalAA Tutorial","level":1,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#metalaa-tutorial"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":false,"page_role":"content","section_order":1,"text":"This tutorial walks through the MetalAA route of parmfit(method=metalaa) in three cases on a cytochrome P450 BM3 pentamutant (Protein Data Bank ID 4ZF6), in which the heme iron is coordinated by four porphyrin nitrogen atoms and the thiolate sulfur of a proximal cysteine. The input structure 4ZF6.pdb places the Fe ion at A462 , the heme cofactor at A461 , and the coordinating cysteine at _400 . Case 1 declares the site and builds it with default cutoffs; Case 2 widens the environment around the unchanged site; Case 3 declares a standard amino acid for deliberate rebuilding, builds its template with the residue-build components of the NCAA (noncanonical amino acid) route, and carries the result into the deployment. Every excerpt below is taken from verified runs of the inputs shown here ( MetalAA1–3.inp plus their sidecar configs). Fig. 1 — Overall structure of 4ZF6 showing the heme site. Every run writes a <base>.parmfitrun.in file next to the output that echoes your configuration with defaults filled in; watch the log for Unknown left-hand warnings, which flag keys that no builder consumed. The reference definition of every key lives in the MetalAA manual page and the shared sections of the ParmFit hub ; software and input requirements are summarized in the hub's Requirements section.","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#overview"},{"heading":"Example Files","level":2,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":false,"page_role":"content","section_order":2,"text":"A linked file name on this page opens the original file from the verified runs, hosted in the MAPLE-Tutorial repository; every input and output file is linked where it is used in the cases below. Save the input files of one case into one folder; Case 1 starts from MetalAA1.inp . The complete run archive, including every _work/ directory, is on Zenodo: 10.5281/zenodo.23126309 . It has one zip per case — Case1.zip (54 MB), Case2.zip (153 MB), and Case3.zip (156 MB) — and each unpacks to a folder of the same name. The Refinement and NCAA archives use the same zip names, so keep each tutorial in its own folder. Software. Every case needs AmberTools and Gaussian 16 on PATH : MetalAA always derives the site charges by RESP — Gaussian evaluates the ESP — even with iqm=false — see the hub's Requirements and QM Reference sections.","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#example-files"},{"heading":"Case 1 — The basic input: parameterizing the Fe–heme site","level":2,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":false,"page_role":"content","section_order":3,"text":"Goal. Parameterize the Fe site with the metal ion and its heme cofactor declared explicitly and every cutoff left at its default: donor detection at 2.7 Å, environment at 3.0 Å. Charges come from RESP (restrained electrostatic potential) at PBE1PBE/def2SV with the default chgmod=1 , and bonded terms from seminario rather than the default mseminario . The split-valence def2SV basis is a deliberate step down from the manual's PBE1PBE/def2SVP default — it keeps the RESP job on the 95-atom large model affordable. Input. MetalAA configs tend to list many keys, so the example uses a sidecar config file referenced with input= from the very first case; the method itself stays in the inline #parmfit(...) header. ion_resids selects the central ion, and lig_resids / lig_charges declare the heme as a cofactor built as a small molecule. MetalAA1.inp reads the structure from 4ZF6.pdb #model=uma(size=uma-s-1p1) #parmfit(method=metalaa,input=MetalAA1.in) #device=gpu0 PDB 4ZF6.pdb MetalAA1.in # MetalAA route settings; declare method=metalaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. ion_resids=A462 ion_charges=3 ion_mults=6 lig_resids=A461 lig_charges=-4 bonded=seminario chg_level=PBE1PBE/def2SV Run. In the folder that holds MetalAA1.inp , MetalAA1.in , and 4ZF6.pdb : maple MetalAA1.inp MetalAA1.out # or simply: maple MetalAA1.inp The second argument names the log; without it, MAPLE derives the log name from the input, so both forms write MetalAA1.out . The run also writes the resolved configuration MetalAA1.parmfitrun.in and the work directory MetalAA1_work/ . A run has finished normally when the result block reads Status: completed and the log ends with a TOTAL RUN TIME line; on the tutorial hardware Case 1 takes about 33 min. What happens. Site recognition. Template graph-matching flags the heme as the one unmatched residue — seemingly not protein , with a hint to declare it, which the lig_resids declaration above already handles. Donor atoms are detected among N, O, S, P, Se, and halogens within donor_cutoff : the cysteine SG and the four heme nitrogens. The ion plus donor residues form the core. Large model. Environment residues within cluster_cutoff are collected into a 95-atom model; broken peptide boundaries are sealed with ACE/NME (acetyl/N-methylamide) caps and sequence gaps with Gly bridges. Ligand build. The declared heme is typed and charged in lig/HEM461/ through antechamber (default lig_chgfit=abcg2 , which runs an internal sqm job) and parmchk2, producing HEM461.mol2 and HEM461.frcmod . MLIP optimization. The large model relaxes with the MLIP (machine-learned interatomic potential); its net charge is computed as Q_large = ion_charges + Σ net charges of all other residues — here -2 , with multiplicity 6. RESP. Gaussian evaluates the large-model ESP (electrostatic potential); AmberTools performs the two-stage RESP fitting, with backbone heavy atoms fixed to Amber references ( chgmod=1 ). Site model. The core-only model receives the projected charges; residues are renamed to export codes (CYM→CM1, HEM→HM1, FE→FE1) and coordinating atoms are retyped: donors receive Z1 / Z2 /..., the metal M1 . Bonded fit and deployment. An MLIP Hessian + Seminario fit the metal-related bond/angle terms; the final frcmod and tleap files are written and validated. Charge ledger. The large-model charge of −2 adds up from the declared and matched residues: Residue Charge Source A462 Fe +3 ion_charges=3 : Fe(III) A461 HEM −4 lig_charges=-4 : porphyrin dianion (−2) plus two deprotonated propionates (−1 each); the heme in 4ZF6.pdb carries 30 H and no carboxylic H _400 CYM −1 Matched template: the thiolate bound to Fe ACE/NME caps 0 Neutral caps that seal the large model Large model −2 Banner: large model charge/mult: -2 6 ; the multiplicity 6 of high-spin Fe(III) comes from ion_mults=6 The run also prints a hint about charge elsewhere in the protein: Warnings: Potentially charged standard residues within 8 Å of the metal but outside the large model: _398:ARG The hint is a near-field check: residues within cluster_cutoff are already in the large model with net-charge group constraints, so the reminder names only potentially charged standard residues in the near field — within 8 Å of the metal but outside the large model. Here that is exactly one residue, ARG398 . Treat it as a prompt to check the charge model, not as the list of residues that a wider cutoff would add (Case 2 shows those). The resolved configuration. Next to MetalAA1.out , MAPLE writes MetalAA1.parmfitrun.in : # parmfitrun.in - resolved parmfit configuration for method=metalaa # Generated by MAPLE parmfit; values are the user config entries with defaults filled in. # This file is itself a valid parmfit config and can be referenced via input=. # metal ion residue selector (chain+resseq or resname+resseq) ion_resids = A462 # coordinating ligand residue selectors lig_resids = A461 # (ff14SB, ff19SB) pro_ff = ff14SB # (mseminario, seminario, none) bonded = seminario # (0-3) chgmod = 1 # charge level METHOD/BASIS (engine syntax) chg_level = PBE1PBE/def2SV ... (open the real file after a run to see every resolved key) Reading the output. The header prints the full site configuration — verify the cutoffs, the ion charge, and the computed large-model charge before anything else: ====================================================================== Parmfit MetalAA ====================================================================== Target: A462:FE (ion) PDB residue templates: matched=460, backbone_only=0, unmatched=1 not matched (seemingly not protein): A461:HEM declare them via lig_resids (or ncaa_resids) to build parameters as small molecules ion_resids: A462 add_resid: [] cluster_cutoff: 3.00 A donor_cutoff: 2.70 A water ff: tip3p protein ff: ff14SB ion ff: 12_6 ion_charges: 3 ion_mults: 6 ncaa_resids: [] large model charge/mult: -2 6 chgmod: 1 fixchg_resids: [] QM method: PBE1PBE/def2SV [MetalAA] large-model input written. [MetalAA] MLIP large-model optimization ... [MetalAA] large-model RESP ... [MetalAA] site files written. [MetalAA] MLIP Hessian + Seminario + final frcmod ... [MetalAA] final parameter files written. [MetalAA] running tleap validation ... [MetalAA] route completed; final summary follows. The result block lists the site products, the renamed atom types, the timings, and the deployment command: ====================================================================== PARMFIT METALAA RESULT ====================================================================== Status: completed Route: MetalAA Target: A462:FE Protein ff: ff14SB Ions charge: 3 Large model charge/mult: -2 6 Core residues: _400:CYM, A461:HEM, A462:FE Main products: final frcmod: MetalAA1_work/MetalAA1_metal.frcmod tleap input: MetalAA1_work/MetalAA1_metal_tleap.in tleap PDB: MetalAA1_work/MetalAA1_metal_tleap.pdb mol2 files: MetalAA1_work/CM1.mol2, MetalAA1_work/HM1.mol2, MetalAA1_work/FE1.mol2 Renamed atom types: residue atom old new charge _400:CYM SG SH Z1 -0.329172 A461:HEM NA nc Z2 -0.129187 A461:HEM NB nd Z3 -0.181075 A461:HEM ND nc Z4 -0.152740 A461:HEM NC nd Z5 -0.118203 A462:FE FE FE M1 0.439642 Stage timing: RESP fitting 27m 22s ligand building 3m 29s Hessian + Seminario 59s model optimization 29s tleap validation 5s ... Next step: cd MetalAA1_work tleap -s -f MetalAA1_metal_tleap.in |tee MetalAA1_metal_tleap.out Tleap status: Errors: 0 Warnings: 8 Notes: 1 Fig. 2 — The Case-1 site in the processed tleap PDB: the five donors typed Z1 – Z5 coordinate the Fe ( M1 ). Metal-site parameters. MetalAA1_metal.frcmod holds the fitted terms of the site. Every Fe term is new: no Fe–donor parameters exist before the fit, so there is no “before” value. MAPLE fits the force constants from the MLIP Hessian with the Seminario method ( bonded=seminario ) and takes r 0 and θ 0 from the MLIP-optimized model, so r 0 agrees with that model by construction. The distances in the input crystal structure are an independent reference, not a validation of the force constants. Bond Atoms K b (kcal mol −1 Å −2 ) r 0 (Å) In 4ZF6 (Å) Z1-M1 SG (CYM400)–Fe 80.99 2.300 2.30 Z2-M1 NA (HEM)–Fe 50.68 2.071 2.05 Z3-M1 NB (HEM)–Fe 51.18 2.104 2.09 Z4-M1 ND (HEM)–Fe 55.89 2.070 2.05 Z5-M1 NC (HEM)–Fe 49.48 2.087 2.04 Angle Atoms K θ (kcal mol −1 rad −2 ) θ 0 (°) Z1-M1-Z2 SG–Fe–NA 34.68 109.01 Z1-M1-Z3 SG–Fe–NB 39.16 103.01 Z1-M1-Z4 SG–Fe–ND 40.49 107.70 Z1-M1-Z5 SG–Fe–NC 36.95 99.52 Z2-M1-Z3 NA–Fe–NB 64.29 86.89 Z2-M1-Z4 NA–Fe–ND 65.41 85.35 Z2-M1-Z5 NA–Fe–NC 38.01 151.45 Z3-M1-Z4 NB–Fe–ND 49.96 149.20 Z3-M1-Z5 NB–Fe–NC 52.24 85.75 Z4-M1-Z5 ND–Fe–NC 69.01 86.98 The file also holds 9 angles of the form X–Z–M1 (for example CT-Z1-M1 ) and the terms that the retyped donor atoms inherit from their original types (for example CT-Z1 ). The tleap warnings. Tleap status counts the warnings of the validation run, logged in MetalAA1_metal_tleap.out ; the count is unrelated to the environment hint above. The 8 warnings and the note are: tleap message Cause Action One sided connection. Residue (CM1) missing connect0 atom. and … Residue (default_name) missing connect1 atom. CM1 , the renamed Cys400, comes from its own mol2 and carries no chain-connection atoms, so the peptide links on both sides are not made automatically. None: the tleap input adds both bonds explicitly ( bond mol.399.C mol.400.N , bond mol.400.C mol.401.N ). Converting N-terminal residue name to PDB format: NTHR -> THR (twice) Saving the dry and the solvated PDB writes the standard terminal names. None. Converting C-terminal residue name to PDB format: CSER -> SER (twice) The same for the C terminus. None. The unperturbed charge of the unit (-11.000000) is not zero. and the note Ignoring the warning from Unit Checking. Net charge of the dry system before ions are added. None for tleap, which adds 11 Na + next. addIons: 1st Ion & target unit have charges of the same sign: The script also requests Cl − after the Na + ions have neutralized the unit. None. Checkpoint Before moving on, confirm: the renamed atom types table lists exactly the intended coordination — here five donors (thiolate SG + four heme nitrogens as Z1 – Z5 ) plus M1 ; large model charge/mult: -2 6 matches the charge ledger above; Core residues contains exactly CYM, HEM, and FE; lig/HEM461/ holds the cofactor build and metalaa/ the RESP intermediates. The environment hint is one MAPLE warning; the 8 tleap warnings are the ones listed above.","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#case-1"},{"heading":"Case 2 — Widening the environment","level":2,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":false,"page_role":"content","section_order":4,"text":"What changed. This case changes exactly one key: cluster_cutoff goes from the default 3.0 Å to 5.0 Å. Charge fitting should account for the environment around the site. The large model used for the RESP stage keeps every non-water residue within cluster_cutoff of the metal, so the fitted site charges account for the electrostatic influence of those neighbors. The residues that the wider cutoff actually adds are listed below. The two cutoffs answer different questions. The donor_cutoff setting defines the site: which atoms count as donors, which residues enter the core, which Z types are assigned — that is coordination chemistry. cluster_cutoff only extends the model beyond that core for the charge-fitting and relaxation stages. Case 2 changes only the second of these. Input. MetalAA2.inp differs from MetalAA1.inp only in input=MetalAA2.in : MetalAA2.inp reads the structure from 4ZF6.pdb #model=uma(size=uma-s-1p1) #parmfit(method=metalaa,input=MetalAA2.in) #device=gpu0 PDB 4ZF6.pdb MetalAA2.in is MetalAA1.in plus these lines: # Wider automatic environment: residues with any atom within 5.0 A of the metal # join the large model as RESP/MLIP context; core and site model stay unchanged cluster_cutoff=5.0 MetalAA2.in # MetalAA route settings; declare method=metalaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. ion_resids=A462 ion_charges=3 ion_mults=6 lig_resids=A461 lig_charges=-4 bonded=seminario chg_level=PBE1PBE/def2SV # Wider automatic environment: residues with any atom within 5.0 A of the metal # join the large model as RESP/MLIP context; core and site model stay unchanged cluster_cutoff=5.0 Run. maple MetalAA2.inp MetalAA2.out , as in Case 1; on the tutorial hardware it takes about 2 h 01 min, and MetalAA2.parmfitrun.in records the one key that separates it from Case 1: cluster_cutoff=5.0 . What happens. The header of MetalAA2.out now reads cluster_cutoff: 5.00 A and the large model grows from 95 to 175 atoms; the core, the site model, and the product list are untouched. The site model is just the core with the caps removed — it exists for export and deployment, while every fitting stage runs in the large model. The cost concentrates in the RESP stage: MetalAA1 (3.0 A) MetalAA2 (5.0 A) --------------------------------------------------------------------- large model: 95 atoms large model: 175 atoms Z1 charge: -0.329172 Z1 charge: -0.332890 Z2 charge: -0.129187 Z2 charge: -0.069716 Z3 charge: -0.181075 Z3 charge: -0.124553 Z4 charge: -0.152740 Z4 charge: -0.115343 Z5 charge: -0.118203 Z5 charge: -0.068541 M1 charge: 0.439642 M1 charge: 0.369515 RESP fitting 27m 22s RESP fitting 1h 44m 56s ligand building 3m 29s ligand building 10m 17s Hessian + Seminario 59s Hessian + Seminario 4m 14s whole run 32m 37s whole run 2h 00m 59s Core residues: CYM, HEM, FE Core residues: CYM, HEM, FE (unchanged) Fig. 3 — The large model at cluster_cutoff 3.0 Å (95 atoms) versus 5.0 Å (175 atoms), viewed from above and flipped; widening adds the surrounding environment to the model while the core stays unchanged. What the wider cutoff adds. Comparing the two large models ( MetalAA1_work/MetalAA1_metal_large_raw.pdb and MetalAA2_work/MetalAA2_metal_large_raw.pdb ), the wider cutoff adds four residues, together with the ACE/NME caps built from their flanking residues 263, 265, 392, 394, and 403: Residue Closest atom to Fe (Å) Formal charge GLY402 3.91 0 PHE393 4.17 0 ALA264 4.29 0 ILE401 4.42 0 All of them are neutral, the large-model charge stays −2, and the residue flagged in Case 1 ( ARG398 ) remains outside the model. The fitted charges barely move: at most 0.06 e for the donors and 0.07 e for Fe. Widening the environment thus has only a small effect on the fit — when you want the environment accounted for, choose cluster_cutoff as your case requires. The options that change the model act differently: Option or message What it does cluster_cutoff Extends the large model by distance: residues with any atom within the cutoff of the metal join the RESP/MLIP context. The core and the site model do not change. add_resid Forces residues into the core, with or without donor atoms. This changes what is fitted and what is deployed. Environment hint (Case 1) Names potentially charged standard residues within 8 Å of the metal but outside the large model. 3 Å vs 5 Å comparison Lists the residues actually added and how the site charges respond, so you can weigh sensitivity against cost. Checkpoint cluster_cutoff controls context only. With automatic selection, a residue in the core has donated an atom within donor_cutoff — that is coordination chemistry, not something the cluster cutoff controls; add_resid can also put residues without donors into the core. Weigh the near-quadrupled RESP cost against how little the site charges actually moved — here at most 0.07 e, although every added residue is neutral.","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#case-2"},{"heading":"Case 3 — Handling an NCAA in the metalloprotein","level":2,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":false,"page_role":"content","section_order":5,"text":"ILE401 is a standard residue with an Amber template; it is rebuilt here only to show how an NCAA declaration reaches the deployment, and in real work you normally declare only residues that need it. What changed. The addition on top of Case 2 is an NCAA declaration: with ncaa_resids=ILE401 , a standard amino acid — ILE, renamed ILE→ ILM on export — is rebuilt with the residue-build components of the NCAA route, and its fitted charges freeze into the site RESP. Bold lines are new in this case. Input. MetalAA3.inp differs from MetalAA2.inp only in input=MetalAA3.in : MetalAA3.inp reads the structure from 4ZF6.pdb #model=uma(size=uma-s-1p1) #parmfit(method=metalaa,input=MetalAA3.in) #device=gpu0 PDB 4ZF6.pdb MetalAA3.in is MetalAA2.in plus these lines: # ILE401 (axial-loop heme-pocket neighbor) built through the native NCAA flow and renamed ILE->ILM; # its charges are frozen into the site RESP ncaa_resids=ILE401 ncaa_charges=0 ncaa_resnames=ILM ncaa_mults=1 MetalAA3.in # MetalAA route settings; declare method=metalaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. ion_resids=A462 ion_charges=3 ion_mults=6 lig_resids=A461 lig_charges=-4 bonded=seminario chg_level=PBE1PBE/def2SV # Wider automatic environment: residues with any atom within 5.0 A of the metal # join the large model as RESP/MLIP context; core and site model stay unchanged cluster_cutoff=5.0 # ILE401 (axial-loop heme-pocket neighbor) built through the native NCAA flow and renamed ILE->ILM; # its charges are frozen into the site RESP ncaa_resids=ILE401 ncaa_charges=0 ncaa_resnames=ILM ncaa_mults=1 Run. maple MetalAA3.inp MetalAA3.out , as in Case 1; on the tutorial hardware it takes about 1 h 04 min, and MetalAA3.parmfitrun.in resolves the NCAA declaration into its full block: ncaa_resids=ILE401 , charge 0, exported name ILM , and the charge-route keys. What happens. The NCAA declaration tells MetalAA to build a fresh reference template for a site-adjacent residue: a capped model of ILE401 is optimized, Gaussian evaluates its ESP, AmberTools runs the two-stage RESP, and the fitted charges are frozen into the site charge problem. This build reuses the residue-build components of the NCAA route but is lighter than the standalone NCAA route: it optimizes one capped conformer instead of the α/β pair, fits RESP on that single conformer, and builds the template with antechamber and parmchk2 only — with no Hessian/mSeminario refinement and no TorsionFit. The intermediates land in MetalAA3_work/ncaa/ILE401/ ( MetalAA3_capped.mol2 , the ESP job, resp1/resp2 outputs, ILM.mol2 , ILM.frcmod ), and the banner gains the declaration: ncaa_resids: ['ILE401'] . Because ILE401 does not coordinate the metal, it does not enter the core — the result block still reports Core residues: _400:CYM, A461:HEM, A462:FE . The template surfaces in the deployment instead: the tleap input MetalAA3_metal_tleap.in now loads ILM.mol2 and ILM.frcmod alongside the site files, and the processed PDB carries ILM at residue 401. In MetalAA3.out , the banner registers the declaration, the stage timing gives the build its own entry, and the tleap status comes back clean: ncaa_resids: ['ILE401'] ... ncaa building 7s ... Errors: 0 MetalAA3_work/MetalAA3_metal_tleap.in MetalAA3_work/MetalAA3_metal_tleap.pdb --------------------------------------- --------------------------------------- addAtomTypes { ATOM 6405 N ILM A 401 { \"Z1\" \"S\" \"sp3\" } ATOM 6406 CA ILM A 401 { \"Z2\" \"N\" \"sp3\" } ATOM 6407 C ILM A 401 { \"Z3\" \"N\" \"sp3\" } ATOM 6408 O ILM A 401 { \"Z4\" \"N\" \"sp3\" } ATOM 6409 CB ILM A 401 { \"Z5\" \"N\" \"sp3\" } ATOM 6410 CG1 ILM A 401 { \"M1\" \"Fe\" \"sp3\" } ... } ... CM1 = loadmol2 CM1.mol2 HM1 = loadmol2 HM1.mol2 FE1 = loadmol2 FE1.mol2 ILM = loadmol2 ILM.mol2 loadamberparams frcmod.ions234lm_126_tip3p loadamberparams MetalAA3_metal.frcmod loadamberparams ILM.frcmod mol = loadpdb MetalAA3_metal_tleap.pdb bond mol.461.NA mol.462.FE ... (4 more coordination bonds) bond mol.399.C mol.400.N # backbone repair bond mol.400.C mol.401.N # backbone repair bond mol.401.C mol.402.N # backbone repair savepdb mol MetalAA3_metal_tleap_dry.pdb solvatebox mol TIP3PBOX 10.0 ... Checkpoint ILE401 is absent from Core residues yet appears as ILM at residue 401 in the tleap PDB; ILM = loadmol2 ILM.mol2 and the ILM and metal-site loadamberparams lines are both present in the tleap input; tleap reports Errors: 0 . Use NCAA declarations only for residues you genuinely want rebuilt — coordinating non-protein species belong in lig_resids , and plain standard residues never need declaring unless you deliberately want them rebuilt, as ILE401 is here.","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#case-3"},{"heading":"Where to Go Next","level":2,"page":"tasks/parmfit/parmfit_metalaa_tutorial.html","page_entry":false,"page_role":"content","section_order":6,"text":"The deployment is validated for you: the route ran tleap itself and reported Errors: 0 , and the charge ledger above closes to −2. Take the solvated topology into your simulation after reading its warnings; the manual has the charge-convention details. MetalAA manual — parameter reference, charge convention, chgmod table, and limits. ChargeFit and the QM (quantum-mechanical) reference on the ParmFit hub — the stages these routes share, documented once on the hub. NCAA tutorial — the standalone NCAA route; this tutorial’s Case 3 rebuilds ILE401 into ILM with the NCAA route’s residue-build components, a lighter build than the standalone route. Refinement tutorial — the small-molecule route. Example files and run archive. See Example Files for the hosted files and the complete Zenodo archive.","title":"MetalAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","MetalAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_metalaa_tutorial.html#where-next"},{"heading":"ParmFit NCAA","level":1,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#parmfit-ncaa"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":1,"text":"NCAA is the parmfit(method=ncaa) route for a noncanonical amino acid whose peptide backbone is recognized but whose complete residue graph does not match an active standard Amber protein template. It caps that residue with ACE and NME and builds the capped models with the backbone and the caps frozen, so that only the sidechain R-group relaxes. The α and β conformers are built by rotating the backbone to target (φ,ψ) values of approximately (−60°, −40°) and (−120°, 140°) for an L residue; the signs are reversed for a D residue. ncaa_resids accepts several comma-separated residues; each one is built in its own work directory and all are deployed together. After charge fitting (see ChargeFit ), AmberTools prepin/frcmod templates are created, and bond/angle terms plus sidechain torsions are refined. Deployment is validated with tleap — the result block prints the command under Next step , and a clean run reports Errors: 0 . Standard residues may also be declared deliberately, to be rebuilt through this flow. For a worked walkthrough, see the NCAA tutorial . Rebuild the topology with ParmEd before SHAKE The exported prepin and frcmod carry MAPLE’s reassigned atom types. tleap identifies hydrogen atoms by the leading character of the atom type, which those types do not provide, so a topology built from them must be normalized with ParmEd before SHAKE ( ntc=2 ): build it with the exported tleap input (the command under Next step ), then pass it through ParmEd and use its output.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#overview"},{"heading":"Target","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":2,"text":"ncaa_resids must identify protein residues in the input PDB, one selector per comma-separated entry: a chain and residue number such as A123 , a residue name and number such as HIF123 , or an appended altloc label when a specific alternate conformation is required (for example, A123A for altloc A). A selector without a chain must still be unique. Declare multiple residues by comma-separating their selectors, as in ncaa_resids=HIF89,TRP482 . Residue selection occurs after the standard-residue graph match and does not change what the matching recognizes. Every selected residue must have a connected N-H-CA-C(=O) peptide backbone and at least one sidechain heavy atom bonded to CA; ncaa_resnames controls only its output residue name. The charges in ncaa_charges apply only to the declared residues. Other backbone-only residues in the same PDB receive neither their charge nor a generated NCAA template; the report lists them explicitly for separate handling.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#target"},{"heading":"Workflow","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":3,"text":"The route in outline: Algorithm 2 — NCAA: building non-standard residues in a protein Require: protein PDB; declared noncanonical and covalently modified residues; config Ensure: refined prepin/frcmod per residue; validated tleap topology Read the PDB with template matching. For each declared residue: build the capped model (ACE + side chain + NME); optimize conformers with the MLIP; fit charges. ▹ resp , or abcg2 , … type with AmberTools (antechamber → prepgen → parmchk2); derive bonded terms and run TorsionFit; write the refined prepin / frcmod. If several residues: rewrite the aggregate tleap PDB and input. Validate with tleap. Target identity. Locate the target residue and detect backbone, sidechain anchor, and chirality. Capped models. Build and optimize α and β ACE-target-NME conformers. Atomic charges. Fit charges on the optimized conformers with the configured chg_fit route and prepare the charged capped mol2. AmberTools template. Use the fitted charges with antechamber, prepgen, and parmchk2 to create the initial prepin/frcmod files. Parameter refinement. Apply Seminario/mSeminario to bond/angle terms and TorsionFit to target-residue sidechain torsions. Deployment. Write refined prepin/frcmod, processed protein PDB, tleap input, and tleap validation outputs.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#workflow"},{"heading":"Core Parameters","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":4,"text":"Parameter Default Description ncaa_resids Required Comma-separated PDB selectors for the protein residues to parameterize; see Target . ncaa_charges 0 Per-residue net charges, pairing 1:1 with ncaa_resids . ncaa_mults 1 Per-residue spin multiplicities, pairing 1:1 with ncaa_resids . ncaa_resnames <RESNAME> Output residue names used in prepin/frcmod and processed PDB files, pairing 1:1 with ncaa_resids . When omitted, each residue falls back to its source residue name. pro_ff ff14SB Protein force field model, ff14SB or ff19SB . wat_ff tip3p Water model for tleap deployment and RESP radii context: tip3p , spce , tip4pew , opc3 , opc , fb3 , or fb4 . keep None Chooses which alternate conformation to build when the PDB lists several for a residue: append the altloc letter to the selector ( A181B ) to build that residue from its altloc-B atoms; an entry without a letter keeps the default resolution (altloc A, else the highest-occupancy set). bonded mseminario Bond/angle refinement: mseminario , seminario , or none . vib_scale 1.0 Vibrational frequency scale factor for Hessian-based fitting. chg_fit resp Charge source: resp , a charge-capable MLIP , or a value passed to antechamber -c . none is invalid for NCAA. chg_level HF/6-31G(d) Gaussian ESP level used only when chg_fit=resp . chg_route Empty Additional Gaussian route text for RESP ESP jobs. iqm false Use external QM reference geometry/Hessian/torsion references. It does not select the charge route. See the main ParmFit page for details. For TorsionFit parameters, QM job resources, MLIP optimization controls, and levels of theory, see the TorsionFit , General Settings , and QM Reference sections of the main ParmFit page. Preserving original GAFF2 parameters Bond/angle and torsion refinement are controlled separately. Setting bonded=none keeps the initial BOND/ANGLE terms; setting torsionfit=false keeps the initial DIHE terms. When either refinement is enabled, atom types are automatically reassigned (MAPLE Z0/Z1, etc.).","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#parameters"},{"heading":"ChargeFit","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":5,"text":"NCAA fits charges on the optimized α and β capped conformers. With chg_fit=resp , Gaussian evaluates the ESP of both conformers and AmberTools performs one joint two-stage RESP fit. A charge-capable MLIP or Antechamber method evaluates the two conformers separately, after which MAPLE averages the two per-atom charge sets with equal weights. For model and Antechamber routes, a final backbone adjustment brings the target-residue charge in the prepin to the ncaa_charges value. chg_fit is independent of iqm . RESP derivation always uses Gaussian for the ESP and AmberTools for the RESP stages; chg_level , chg_route , qm_nproc , and qm_mem control the jobs. NCAA cannot use chg_fit=none because a PDB input does not supply a reusable set of atomic charges. All charge-route files remain under <base>_work/ncaa/<RESNAME><RESSEQ>/ , one directory per declared residue. The resulting charged capped mol2 and target.chg are the inputs to the prepin/GAFF2 template build; the same charges are carried into the Stage 0 parameter set (the bonded-refined starting point) and the TorsionFit baseline. The result block reports Target charge and Actual charge ; with several residues it shows only the last one, so check each <rn>_maple.prepin charge sum against its ncaa_charges value.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#chargefit"},{"heading":"TorsionFit","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":6,"text":"NCAA restricts torsion fitting to rotatable dihedrals in the target residue's sidechain; backbone–backbone and cap dihedrals are excluded. torsion_bonds uses residue-local 1-based indices (ACE/NME caps not counted) and separates per-residue groups with ; , in the same order as ncaa_resids . For a complex sidechain, set torsionfit=false and rely on the original GAFF2 torsion , or use torsion_bonds to refine selected dihedrals. NCAA disables torsion ensemble targets internally; see the main ParmFit page for scan and refinement parameter details.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#torsionfit"},{"heading":"Peptide Boundary Terms","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":7,"text":"When the NCAA residue is inserted as a custom template, MAPLE dynamically generates ProteinFF-GAFF2 cross-terms at both peptide boundaries: the head side ( prev_C – target_N ) and the tail side ( target_C – next_N ). These include exact BOND, ANGLE, and DIHE terms that connect the atom types of the custom template with those of the neighbouring standard residues.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#peptide-boundary"},{"heading":"Input Files","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":8,"text":"","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#parmfit-input"},{"heading":"Simple Input","level":3,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":9,"text":"A simple NCAA job declares method=ncaa inline and lists its ParmFit options in a sidecar config. The ncaa_resids selectors choose which noncanonical protein residues to build, and the PDB block supplies the complete structure. #model=uma(size=uma-s-1p1) #parmfit(method=ncaa,input=NCAA.in) #device=gpu0 PDB ncaa.pdb Example simple ParmFit config ncaa_resids=A123 ncaa_resnames=MOL ncaa_charges=0 ncaa_mults=1 chg_fit=resp bonded=mseminario torsionfit=false","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#simple-input"},{"heading":"Full External Input","level":3,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":10,"text":"For a more complex setup, keep the MAPLE launcher short and move ParmFit parameters into an external .parmfit file. Declare method=ncaa inline together with input= ; the external config must not set method= . The PDB remains in the MAPLE input; do not place pdb , input , or global MAPLE options in the external config. #model=uma(size=uma-s-1p1) #parmfit(method=ncaa,input=NCAA.parmfit) #device=gpu0 PDB ncaa.pdb Full ParmFit config NCAA.parmfit # QM reference iqm=false qm_engine=g16 opt_level=B3LYP/def2SVP sp_level=B3LYP/def2SVP opt_route= sp_route= qm_mode=1 qm_nproc=8 qm_mem=24 # Atomic charges chg_fit=resp resp_backend=gaussian chg_level=HF/6-31G(d) chg_route= # Residue declaration, force field, and bonded fitting ncaa_resids=A123 ncaa_charges=0 ncaa_mults=1 ncaa_resnames=MOL pro_ff=ff14SB wat_ff=tip3p bonded=mseminario vib_scale=1.0 # Choose the altloc conformer for these residues (selector + letter, e.g. PHE393B) keep= # NCAA capped-conformer optimization controls opt_max_iter=256 opt_max_step=0.2 # TorsionFit torsionfit=false torsion_bonds= torsion_steps=36 backend=cgbs constraint_mode=projected stage1_weights=true torsion_refine_rounds=3 torsion_refine_max_iter=256 torsion_refine_tol=1.0e-6 torsion_ensemble=false torsion_ensemble_ratio=0.3 torsion_ensemble_weight=0.5","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#full-external-input"},{"heading":"Output Files","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":11,"text":"<base>_work/<rn>.prepin and <base>_work/<rn>.frcmod : Initial AmberTools residue template files. <base>_work/<rn>_maple.prepin and <base>_work/<rn>_maple.frcmod : Refined MAPLE residue template and parameter files. <base>_work/<base>_ncaa_tleap.pdb , <base>_work/<base>_ncaa_tleap.in , and <base>_work/<base>_ncaa_tleap.out : Processed protein PDB, tleap input, and the tleap validation log. <base>_work/<base>_ncaa.prmtop , <base>_work/<base>_ncaa.inpcrd , and solvated PDB outputs: tleap validation products. <base>_work/ncaa/<RESNAME><RESSEQ>/ — the source residue name and number ( HIF89 style, not the exported <rn> name used by the template files above): per-residue optimized conformers, charge-route files, charged capped mol2, target.chg , and AmberTools template intermediates. <base>_work/torsionfit/<RESNAME><RESSEQ>/ : TorsionFit scans of the declared torsion bonds (scan xyz files and per-bond logs), named with capped-model atom serials.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#output-files"},{"heading":"Requirements and Limits","level":2,"page":"tasks/parmfit/parmfit_ncaa.html","page_entry":false,"page_role":"content","section_order":12,"text":"The declared residues must have a connected peptide backbone and at least one sidechain heavy atom bonded to CA (see Target); standard atom naming is not required. chg_fit=none is unsupported because NCAA has no input mol2 charges to preserve. When chg_fit=resp , RESP uses the Gaussian backend; model and Antechamber charge routes do not require RESP. The final target-residue charge written for model and Antechamber methods is constrained to the ncaa_charges value. TorsionFit is restricted to rotatable dihedrals in the target residue's sidechain and does not fit peptide backbone torsions.","title":"ParmFit NCAA - MAPLE","trail":["Tasks","ParmFit","NCAA"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa.html#requirements"},{"heading":"NCAA Tutorial","level":1,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#ncaa-tutorial"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":false,"page_role":"content","section_order":1,"text":"This tutorial walks through the NCAA route of parmfit(method=ncaa) in three cases on Morus alba Diels–Alderase (MaDA; Protein Data Bank ID 6JQH), a flavin adenine dinucleotide (FAD)-dependent enzyme whose FAD cofactor is covalently linked to a histidine residue. The input structure MaDA.pdb carries that residue as _89:HIF ; it has no force-field template and becomes the exported residue HF1 . Case 1 builds the template with torsion fitting off; Case 2 switches torsion fitting on with explicit bonds; Case 3 declares a second residue alongside the first. Every excerpt below is taken from verified runs of the inputs shown here. Fig. 1 — Overall structure of MaDA showing the covalent linkage between the histidine residue and the FAD. Every run writes a <base>.parmfitrun.in file next to the output that echoes your configuration with defaults filled in; watch the log for Unknown left-hand warnings, which flag keys that no builder consumed. The reference definition of every key lives in the NCAA manual page and the shared sections of the ParmFit hub ; software and input requirements are summarized in the hub's Requirements section.","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#overview"},{"heading":"Example Files","level":2,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":false,"page_role":"content","section_order":2,"text":"A linked file name on this page opens the original file from the verified runs, hosted in the MAPLE-Tutorial repository; every input and output file is linked where it is used in the cases below. Save the input files of one case into one folder; Case 1 starts from NCAA1.inp . The complete run archive, including every _work/ directory, is on Zenodo: 10.5281/zenodo.23126301 . It has one zip per case — Case1.zip (138 MB), Case2.zip (139 MB), and Case3.zip (151 MB) — and each unpacks to a folder of the same name. The Refinement and MetalAA archives use the same zip names, so keep each tutorial in its own folder. To rerun a case, start from its input files in a new folder: inside an unpacked archive folder, TorsionFit would read the archived scans instead of running its own scan (see the hub’s Scan Reuse ). Software. Every case needs AmberTools and Gaussian 16 on PATH : charges are derived from a Gaussian ESP with the default chg_fit=resp , even though these inputs set iqm=false — see the hub's Requirements and QM Reference sections.","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#example-files"},{"heading":"Case 1 — The basic input: building from FAD","level":2,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":false,"page_role":"content","section_order":3,"text":"Goal. Build a deployable Amber template for one noncanonical residue (here HIF89 , exported as HF1 ) with default fitting: chg_fit=resp , bonded=mseminario , pro_ff=ff14SB . Torsion fitting — on by default — is explicitly switched off here so the first run isolates the charge and template pipeline. Input. The selector picks the target residue, ncaa_resnames renames it for export, and ncaa_charges pairs with it one to one. The route keys live in the sidecar: NCAA1.inp reads the structure from MaDA.pdb #model=uma(size=uma-s-1p1) #parmfit(method=ncaa,input=NCAA1.in) #device=gpu0 PDB MaDA.pdb NCAA1.in # NCAA route settings; declare method=ncaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. ncaa_resids=HIF89 ncaa_charges=-2 ncaa_resnames=HF1 chg_level=HF/6-31G(d) torsionfit=false Run. In the folder that holds NCAA1.inp , NCAA1.in , and MaDA.pdb : maple NCAA1.inp NCAA1.out # or simply: maple NCAA1.inp The second argument names the log; without it, MAPLE derives the log name from the input, so both forms write NCAA1.out . The run also writes the resolved configuration NCAA1.parmfitrun.in and the work directory NCAA1_work/ . A run has finished normally when the result block reads Status: completed and the log ends with a TOTAL RUN TIME line; on the tutorial hardware Case 1 takes about 11 min. What happens. Graph matching. Standard residues are matched against the active ff14SB templates, receiving canonical atom names, types, and net charges; whether each cysteine stays CYX or becomes CYM is decided by disulfide detection. Capped models. ACE (acetyl)–target–NME (N-methylamide) α and β conformers are built and optimized with an MLIP (machine-learned interatomic potential), backbone and caps frozen, so only the sidechain relaxes — the backbone is rotated to the α/β targets (φ,ψ) ≈ (−60°, −40°) and (−120°, 140°) for an L residue, with the signs reversed for a D residue. Charges. Gaussian evaluates the ESP (electrostatic potential) of both capped conformers; AmberTools then performs one joint two-stage RESP (restrained electrostatic potential) fit over them. AmberTools template. antechamber/prepgen/parmchk2 build the initial prepin/frcmod. Refinement. An MLIP Hessian + mSeminario update bond/angle terms. TorsionFit is skipped . Deployment. Refined templates, processed PDB (Protein Data Bank), and tleap input are written, and tleap validation runs. Fig. 2 — The conformer build, demonstrated on a simplified ACE–HIS–NME capped model (the covalently linked FAD cofactor is omitted purely to display the conformations): the initial sidechain conformation flips into the α and β conformers, whose joint ESP feeds the two-stage RESP fit. The resolved configuration. Next to NCAA1.out , MAPLE writes NCAA1.parmfitrun.in : # parmfitrun.in - resolved parmfit configuration for method=ncaa # Generated by MAPLE parmfit; values are the user config entries with defaults filled in. # This file is itself a valid parmfit config and can be referenced via input=. # residues declared for the NCAA flow (built, then folded or frozen) ncaa_resids = HIF89 # extra altloc selectors keep = # residues force-added to the site add_resid = # NCAA run # Non-standard amino acid declaration and residue building # 1:1 with ncaa_resids ncaa_charges = -2 # 1:1 with ncaa_resids; keep within 3 characters (PDB limit) ncaa_resnames = HF1 # multiplicity for the NCAA QM jobs ncaa_mults = # (ff14SB, ff19SB) pro_ff = ff14SB ... (open the real file after a run to see every resolved key) Reading the output. The banner's PDB diagnostics sort every residue into one of three buckets. matched counts residues whose complete graph matched an active Amber template — they receive canonical names, atom types, and charges. backbone_only counts residues whose connected peptide backbone was recognized but which matched no complete template — the NCAA candidates; the target appears there. unmatched counts residues with no template at all, typically nonprotein ligands or cofactors — they are reported for explicit declaration ( lig_resids in MetalAA, or a separate NCAA run) rather than guessed. Disulfide decisions appear under template overrides : ====================================================================== Parmfit NCAA ====================================================================== Target: _89:HIF (protein) PDB residue templates: matched=516, backbone_only=1, unmatched=0 non-standard (matched backbone only): _89:HIF (target) template overrides (renamed): _10:CYM (CYX->CYM), _74:CYM (CYX->CYM) PDB target charge: _89:HIF = -2 (from your input) The start lines and stage trace follow : [NCAA] MLIP model preparation + reference optimization ... NCAA target selector: HIF89 residue name: HF1 chirality: L net charge / spin multiplicity: -2 1 protein ff: ff14SB bonded refinement: mseminario charge fitting: resp charge level: HF/6-31G(d) [NCAA] atomic charge fitting (resp) ... [NCAA] AmberTools template build ... [NCAA] MLIP Hessian + mSeminario ... [NCAA] TorsionFit skipped ... [NCAA] writing refined templates + tleap input ... [NCAA] tleap validation ... [NCAA] route completed; final summary follows. The result block closes with the production tleap command and its Tleap status : ====================================================================== PARMFIT NCAA RESULT ====================================================================== Status: completed Route: NCAA Target: _89:HIF Residue name: HF1 Chirality: L Protein ff: ff14SB Res charge/spin-multi: -2 1 Charge fitting: resp Charge level: HF/6-31G(d) Target charge: -2 Actual charge: -2.00000000 Charge MOL2: NCAA1_work/ncaa/HIF89/NCAA1_capped.mol2 Main products: refined prepin: NCAA1_work/HF1_maple.prepin refined frcmod: NCAA1_work/HF1_maple.frcmod tleap PDB: NCAA1_work/NCAA1_ncaa_tleap.pdb tleap input: NCAA1_work/NCAA1_ncaa_tleap.in Stage timing: charge fitting 7m 46s Hessian + mSeminario 1m 30s model preparation + reference 49s tleap validation 11s AmberTools template build 0s final export 0s Next step: cd NCAA1_work tleap -s -f NCAA1_ncaa_tleap.in |tee NCAA1_ncaa_tleap.out Tleap status: Errors: 0 Warnings: 3 Notes: 0 ... The tleap warnings. Tleap status counts the warnings of the validation run, logged in NCAA1_ncaa_tleap.out . In this run none of the three concerns the new template: tleap message Cause Action The unperturbed charge of the unit (-4.000000) is not zero. Net charge of the protein before ions are added: the declared −2 of the target residue plus Cys10 and Cys74, which the run deploys as CYM (−1 each; see template overrides above). The other charged residues cancel. None for tleap, which adds 4 Na + next. Check that the CYM assignment and the declared target charge are what you intend. Converting N-terminal residue name to PDB format: NTHR -> THR Saving a PDB writes the standard name of the terminal residue. None. Converting C-terminal residue name to PDB format: CLEU -> LEU The same for the C terminus. None. Checkpoint Before moving on, confirm: the target residue appears in the diagnostics as backbone_only ; tleap reports Errors: 0 ; the processed PDB ( NCAA1_ncaa_tleap.pdb ) carries the exported name HF1 at position 89; the per-residue work directory NCAA1_work/ncaa/HIF89/ holds the conformers and charge files. Read the tleap warnings of your own run against the table above.","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#case-1"},{"heading":"Case 2 — Fitting torsions over declared bonds","level":2,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":false,"page_role":"content","section_order":4,"text":"What changed. This case changes two things: torsionfit=true returns to the default, and torsion_bonds names the four residue-local bonds to refit — here the two sidechain chi angles, the covalent His–FAD link, and the ribityl chain of the cofactor. Input. NCAA2.inp differs from NCAA1.inp only in input=NCAA2.in : NCAA2.inp reads the structure from MaDA.pdb #model=uma(size=uma-s-1p1) #parmfit(method=ncaa,input=NCAA2.in) #device=gpu0 PDB MaDA.pdb In NCAA2.in , the Case 1 line torsionfit=false is replaced by torsionfit=true , and torsion_bonds is new. Edit the existing line rather than appending a second one: the run stops with a Duplicate parmfit config key error when a key appears twice. The changed lines: # Sidechain torsion fitting on four representative residue-local bonds: # 3-8 chi1 (CA-CB), 8-11 chi2 (CB-imidazole C4), 6-60 covalent His-FAD link (N2-CH2), 22-25 ribityl (C8-C9) torsionfit=true torsion_bonds=3-8,8-11,6-60,22-25 NCAA2.in # NCAA route settings; declare method=ncaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. ncaa_resids=HIF89 ncaa_charges=-2 ncaa_resnames=HF1 chg_level=HF/6-31G(d) # Sidechain torsion fitting on four representative residue-local bonds: # 3-8 chi1 (CA-CB), 8-11 chi2 (CB-imidazole C4), 6-60 covalent His-FAD link (N2-CH2), 22-25 ribityl (C8-C9) torsionfit=true torsion_bonds=3-8,8-11,6-60,22-25 Run. maple NCAA2.inp NCAA2.out , as in Case 1; on the tutorial hardware it takes about 2 h 04 min, and NCAA2.parmfitrun.in shows torsionfit and torsion_bonds resolved alongside their defaults. What happens. Each listed bond is scanned and refitted . All of it is written to NCAA2_work/torsionfit/HIF89/ : NCAA2_work/torsionfit/HIF89/ NCAA2_torsionfit_9-14_scan_final.xyz # 3-8 chi1 NCAA2_torsionfit_14-17_scan_final.xyz # 8-11 chi2 NCAA2_torsionfit_12-66_scan_final.xyz # 6-60 His-FAD link NCAA2_torsionfit_28-31_scan_final.xyz # 22-25 ribityl ... (per-bond .out logs, pos/neg trajectory and optimized xyz variants) Watch the index space: torsion_bonds uses residue-local 1-based indices (ACE/NME caps not counted), but the scan files are named with the capped-model serials — the ACE cap contributes 6 atoms, so residue-local 3-8 appears as 9-14 , 6-60 as 12-66 , and so on. Each i-j entry names the central bond of the scanned dihedral — the order within a pair is free ( 6-10 and 10-6 are the same bond; scan files use the ascending form) — and the scanned dihedral is the proper-dihedral term the topology already defines over that bond. The stage timing in NCAA2.out shows what the switch costs — TorsionFit simply takes far longer, becoming the most time-consuming stage of the run: Stage timing: TorsionFit 1h 53m 07s charge fitting 7m 56s Hessian + mSeminario 1m 35s model preparation + reference 1m 04s tleap validation 7s ... Fig. 3 — Case 2: the four fitted rotatable dihedrals, each highlighted in a different color. Checkpoint Confirm every declared bond has a scan file (translate residue-local to capped serials with the +6 offset of this ACE cap) . Keep the explicit list short and meaningful — each bond costs a full constrained scan.","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#case-2"},{"heading":"Case 3 — When there are multiple NCAA residues","level":2,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":false,"page_role":"content","section_order":5,"text":"TRP482 is a standard residue; it is declared here only to demonstrate a two-residue run, and in real work you normally declare only residues that have no Amber template. What changed. A second residue — TRP482 , exported as WF1 — is declared alongside the first, each with its own charge and exported name. ; now separates per-residue torsion-bond groups. Bold lines are new or have changed in this case. Input. NCAA3.inp reads the structure from MaDA.pdb #model=uma(size=uma-s-1p1) #parmfit(method=ncaa,input=NCAA3.in) #device=gpu0 PDB MaDA.pdb External config. NCAA3.in # NCAA route settings; declare method=ncaa in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. # Two residues declared together; charges/names pair 1:1 with ncaa_resids ncaa_resids=HIF89,TRP482 ncaa_charges=-2,0 ncaa_resnames=HF1,WF1 chg_level=HF/6-31G(d) # Per-residue torsion bond groups separated by ';': # HIF89: 3-8 chi1, 8-11 chi2, 6-60 covalent His-FAD link, 22-25 ribityl # TRP482: 5-6 (CB-CG) torsionfit=true torsion_bonds=3-8,8-11,6-60,22-25;5-6 Run. maple NCAA3.inp NCAA3.out , as in Case 1; on the tutorial hardware it takes about 1 h 41 min, and NCAA3.parmfitrun.in resolves the two-residue declarations — ncaa_resids=HIF89,TRP482 with paired charges, exported names, and the ; -separated bond groups. What happens. MAPLE runs the full Case-1/Case-2 pipeline for each declared residue independently — its own capped conformers, charge fit, template build, and torsion fitting — and the log, NCAA3.out , shows two complete stage blocks, one per selector: Target: _89:HIF, _482:TRP (protein) PDB residue templates: matched=516, backbone_only=1, unmatched=0 non-standard (matched backbone only): _89:HIF (also note) template overrides (renamed): _10:CYM (CYX->CYM), _74:CYM (CYX->CYM) PDB target charges: _89:HIF = -2, _482:TRP = 0 (from your input) [NCAA] MLIP model preparation + reference optimization ... NCAA target selector: HIF89 residue name: HF1 ... [NCAA] route completed; final summary follows. [NCAA] MLIP model preparation + reference optimization ... NCAA target selector: TRP482 residue name: WF1 ... [NCAA] route completed; final summary follows. [NCAA] tleap validation ... Work products are per residue — ncaa/HIF89/ and ncaa/TRP482/ , torsionfit/HIF89/ and torsionfit/TRP482/ , HF1_maple.prepin / HF1_maple.frcmod and WF1_maple.prepin / WF1_maple.frcmod — but the deployment happens once: one combined NCAA3_ncaa_tleap.in loads both templates and validates them together. The result block reports the last residue, then the route adds a one-line build summary: Status: completed Route: NCAA Target: _482:TRP Residue name: WF1 ... Target charge: 0 Actual charge: 0.00000100 Charge MOL2: NCAA3_work/ncaa/TRP482/NCAA3_capped.mol2 Main products: refined prepin: NCAA3_work/WF1_maple.prepin refined frcmod: NCAA3_work/WF1_maple.frcmod tleap PDB: NCAA3_work/NCAA3_ncaa_tleap.pdb tleap input: NCAA3_work/NCAA3_ncaa_tleap.in ... NCAA residues built: _89:HIF -> HF1, _482:TRP -> WF1 Checkpoint The result block reports Actual charge only for the last residue, so check every residue against its deployed template: the charges in HF1_maple.prepin and WF1_maple.prepin sum to −2.000001 and 0.000001 here, matching ncaa_charges=-2,0 — each residue's atoms form one charge group constrained to its own value. Verify both template pairs exist in the work root and that the combined tleap input loads both ( HF1 and WF1 ). If a selector is not unique in the PDB, the run stops with an error before any QM (quantum-mechanical) work starts; add a chain id to disambiguate. Declaring a standard residue like TRP is legitimate when you deliberately want it rebuilt through the NCAA flow — residues with an $AMBERHOME template normally need no declaration.","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#case-3"},{"heading":"Where to Go Next","level":2,"page":"tasks/parmfit/parmfit_ncaa_tutorial.html","page_entry":false,"page_role":"content","section_order":6,"text":"The deployment is validated for you: the route ran tleap itself and reported Errors: 0 , with the charge closure visible as Target charge versus Actual charge in each result block. Take the processed PDB NCAA1_ncaa_tleap.pdb and tleap input NCAA1_ncaa_tleap.in , build the solvated topology from them, and pass it through ParmEd before SHAKE, because the templates carry MAPLE’s reassigned atom types. The manual’s ParmEd note has the reason, and the ChargeFit section has the charge details. NCAA manual — parameter reference, charge-fitting details, peptide boundary terms, and limits. ChargeFit , QM reference , and TorsionFit on the ParmFit hub — the stages these routes share, documented once on the hub. Refinement tutorial and MetalAA tutorial — simple worked examples for the other routes. Example files and run archive. See Example Files for the hosted files and the complete Zenodo archive.","title":"NCAA Tutorial - MAPLE","trail":["Tutorials","ParmFit","NCAA Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_ncaa_tutorial.html#where-next"},{"heading":"ParmFit Refinement","level":1,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#parmfit-refinement"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":1,"text":"Refinement refines the parameters of a molecule supplied as a mol2 topology. MAPLE starts from GAFF2 parameters, optionally optimizes the structure and updates bonded terms from a Cartesian Hessian, applies the selected atomic-charge source, optionally refits proper torsions, and exports Amber and GROMACS files. With the default chg_fit=none , the charges of the input mol2 are kept; charge fitting replaces them at runtime (see ChargeFit ). For a worked walkthrough, see the Refinement tutorial . Rebuild the topology with ParmEd before SHAKE tleap identifies hydrogen atoms by the leading character of their atom type, which MAPLE types do not carry, so tleap writes an empty %FLAG BONDS_INC_HYDROGEN section and SHAKE ( ntc=2 ) would constrain nothing. Run the exported tleap input, then normalize the topology with ParmEd and use its output: tleap -f <base>_maple_tleap.in parmed -p <base>_maple_gas.prmtop <<<$'outparm <base>_maple_gas_parmed.prmtop\\nquit' Initial Prepare The input mol2 must carry GAFF2 atom types. Pre-generate it with antechamber -at gaff2 -fi <fmt> -fo mol2 -i <input> -o <output> , or omit mol2= entirely: MAPLE then writes the inline coordinates to <base>_work/ante.pdb and types them into <base>_work/<base>_ff.mol2 (residue LIG ). The generated mol2 carries zero placeholder charges, so chg_fit then defaults to abcg2 — an explicit resp , MLIP, or Antechamber method is honored unchanged.","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#overview"},{"heading":"Workflow","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":2,"text":"The route in outline: Algorithm 1 — Refinement: small-molecule GAFF2 correction (bond/angle/proper) Require: typed mol2 (GAFF2; auto-generated when omitted); config Ensure: corrected parameters (amber topology files, gromacs topology files) Load the mol2 as the initial parameter set. Optimize the geometry with the MLIP. Optional QM reference: optimize + frequency job. ▹ iqm Derive bonded terms with Seminario / mSeminario. ▹ mseminario , seminario , none Optional charge fitting. ▹ resp , MLIP models, abcg2 , … Optional torsion fitting: constrained MLIP scans per rotatable bond, QM references per qm_mode, then TorsionFit. If qm_compare: run the parallel MLIP-reference charge and torsion branches. Export .mol2/.frcmod and .top/.gro. Initial parameters. Run parmchk2 -s gaff2 -a Y from the input mol2 to build *_original.frcmod . Optimization and reference. Optimize the structure and prepare the MLIP or optional QM reference geometry required by the enabled refinement stages. Bonded correction or skip. Use Seminario or modified Seminario to update bond and angle terms, or retain the original terms when bonded=none . Atomic charges. Preserve the input charges or calculate new charges with RESP, a charge-capable MLIP, or an Antechamber method. TorsionFit. Scan selected proper torsions ; fit the relative profile without changing nonbonded or topology terms. Export. Write refined Amber mol2/frcmod and GROMACS top/gro files. Charge-only operation If bonded=none and torsionfit=false , MAPLE skips geometry optimization and Hessian evaluation. Charge fitting still runs on the supplied coordinates. With chg_fit=none , the input mol2 charges and the original frcmod are kept unchanged; any other charge method updates the final mol2 charges and keeps the original atom types and frcmod.","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#workflow"},{"heading":"Core Parameters","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":3,"text":"Parameter Default Description mol2 Optional Input topology and atom typing. When omitted, MAPLE auto-generates <base>_work/<base>_ff.mol2 from the inline coordinates via antechamber (GAFF2 typing, zero placeholder charges); chg_fit then defaults to abcg2 . bonded mseminario Bond/angle update method: mseminario , seminario , or none . vib_scale 1.0 Vibrational frequency scale factor for Hessian-based fitting. chg_fit none Charge source: input mol2 charges, resp , a charge-capable MLIP , or a value passed to antechamber -c ; defaults to abcg2 when the mol2 is auto-generated. chg_level HF/6-31G(d) Gaussian ESP level used only when chg_fit=resp . chg_route Empty Additional Gaussian route text for RESP ESP jobs. iqm false Use external QM reference optimization/Hessian and torsion references when enabled. See the main ParmFit page for details. torsion_bonds Auto Optional explicit rotatable bonds; otherwise MAPLE selects rotatable single bonds from the mol2 topology. For TorsionFit parameters, QM job resources, MLIP optimization controls, and levels of theory, see the TorsionFit , General Settings , and QM Reference sections of the main ParmFit page. Preserving original GAFF2 parameters Bond/angle and torsion refinement are controlled separately. Setting bonded=none preserves the original BOND/ANGLE terms; setting torsionfit=false preserves the original DIHE terms. With both disabled, Refinement exports the parmchk2/GAFF2 parameters without refinement. When either refinement is enabled, atom types are automatically reassigned (MAPLE Z0/Z1, etc.).","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#parameters"},{"heading":"ChargeFit","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":4,"text":"chg_fit is independent of iqm . RESP derivation always uses Gaussian for the ESP and AmberTools for the RESP stages, reusing qm_nproc and qm_mem . Refinement reads the target charge and multiplicity from the input structure (an inline <charge> <mult> line, e.g. 0 1 , or an XYZ <charge> <mult> <path> block); the report prints both the integer target from the input structure and the actual sum in the charged mol2 so that any mismatch is visible. qm_compare (default false , Refinement only) repeats the charge and torsion branches against MLIP references: with iqm=true , qm_compare=true , and parameter refinement enabled, charge fitting follows both branch geometries. The primary result uses chargefit/qm_route_charged.mol2 , while the MLIP comparison uses chargefit/mlip_route_charged.mol2 . For chg_fit=none , ParmFit uses the charges recorded in the input mol2.","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#chargefit"},{"heading":"TorsionFit","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":5,"text":"Refinement auto-selects rotatable dihedrals from the mol2 topology: proper-torsion terms whose central bond is a single bond outside a ring. Use torsion_bonds to provide explicit overrides (e.g. 6-8,12-14 ). See the main ParmFit page for the two-stage fitting architecture and parameter details.","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#torsionfit"},{"heading":"Input Files","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":6,"text":"","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#parmfit-input"},{"heading":"Simple Input","level":3,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":7,"text":"A simple Refinement job declares method=refinement inline and lists its ParmFit options in a sidecar config. The inline coordinates provide the working geometry, while the mol2 file supplies topology, atom types, and starting charges. #model=uma(size=uma-s-1p1,task=omol) #parmfit(method=refinement,input=Refinement.in) #device=gpu0 C 0.000000 1.520000 0.000000 ... Example simple ParmFit config mol2=toluene_ff.mol2 chg_fit=none bonded=mseminario torsionfit=true","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#simple-input"},{"heading":"Full External Input","level":3,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":8,"text":"For a more complex setup, keep the MAPLE launcher short and move ParmFit parameters into an external .parmfit file. Declare method=refinement inline together with input= ; the external config must not set method= . File paths such as mol2 are resolved relative to the .parmfit file. #model=uma(size=uma-s-1p1,task=omol) #parmfit(method=refinement,input=Refinement.parmfit) #device=gpu0 C 0.000000 1.520000 0.000000 ... Full ParmFit config Refinement.parmfit mol2=toluene_ff.mol2 # QM reference for correction and TorsionFit iqm=false qm_engine=g16 opt_level=B3LYP/def2SVP sp_level=B3LYP/def2SVP opt_route= sp_route= qm_mode=1 qm_compare=false qm_nproc=8 qm_mem=24 # Atomic charges chg_fit=none chg_level=HF/6-31G(d) chg_route= # Bond/angle correction bonded=mseminario vib_scale=1.0 # Geometry optimization LBFGS memory=5 curvature=70.0 max_step=0.2 max_iter=256 write_traj=false traj_every=1 verbose=1 use_projection=false use_line_search=false bond_constraints= angle_constraints= torsion_constraints= # TorsionFit torsionfit=true torsion_bonds= torsion_steps=36 backend=cgbs constraint_mode=projected stage1_weights=true torsion_refine_rounds=3 torsion_refine_max_iter=256 torsion_refine_tol=1.0e-6 torsion_ensemble=false torsion_ensemble_ratio=0.3 torsion_ensemble_weight=0.5","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#full-external-input"},{"heading":"Output Files","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":9,"text":"When mol2= is omitted: <base>_work/ante.pdb and the antechamber-generated <base>_work/<base>_ff.mol2 (zero placeholder charges; chg_fit defaults to abcg2 ). <base>_work/<base>_original.frcmod : Initial AmberTools/GAFF2 frcmod from parmchk2 . <base>_work/<base>_maple.mol2 : Primary final mol2 with the selected charges; refined workflows use MAPLE atom type naming. <base>_work/<base>_mlip_maple.mol2 : Optional MLIP-comparison mol2 when qm_compare is active. <base>_work/<base>_maple.frcmod : Refined Amber parameter file. <base>_work/<base>_maple.top and <base>_work/<base>_maple.gro : GROMACS export for inspection and deployment. <base>_work/<base>_maple_tleap.in : exported tleap input; running it produces the gas-phase topology <base>_maple_gas.prmtop / .inpcrd . <base>_work/chargefit/{qm_route|mlip_route}_charged.mol2 : Route-specific charged mol2 for RESP or charge-capable-MLIP fitting. With chg_fit=none , no charge pipeline runs, so no chargefit/ directory is created; the input charges are carried into the final mol2. Antechamber methods write <base>_work/chargefit/antechamber_charged.mol2 . <base>_work/torsionfit/ : Torsion scan outputs and fit diagnostics.","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#output-files"},{"heading":"Requirements and Limits","level":2,"page":"tasks/parmfit/parmfit_refinement.html","page_entry":false,"page_role":"content","section_order":10,"text":"mSeminario and Seminario update BOND and ANGLE terms only. TorsionFit refits selected proper torsions ; it does not rewrite topology or nonbonded terms. Automatic rotatable-bond selection follows the input mol2 bond typing. Fix incorrect aromatic, amide, or double-bond labels in the mol2 before fitting. The inline coordinates and the mol2 must list the same atoms in the same order, hydrogens included. MAPLE checks only that the atom counts match and then pairs atoms by position; it does not remap two files that were ordered independently. The coordinate values themselves need not match the mol2.","title":"ParmFit Refinement - MAPLE","trail":["Tasks","ParmFit","Refinement"],"type":"Task","url":"tasks/parmfit/parmfit_refinement.html#requirements"},{"heading":"Refinement Tutorial","level":1,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#refinement-tutorial"},{"heading":"Overview","level":2,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":false,"page_role":"content","section_order":1,"text":"This tutorial walks through the Refinement route of parmfit(method=refinement) in four runs on o-iodophenol ( choi001 ), a FreeSolv hydration-benchmark solute, supplied as the GAFF2 (General AMBER Force Field)-typed choi001_gaff2.mol2 , already assigned abcg2 charges by antechamber. Case 1 refines bonded terms and torsions with every default; Case 2 derives RESP (restrained electrostatic potential) charges and adds a Gaussian reference; Case 3 walks the TorsionFit QM (quantum-mechanical) modes 2 and 3 ( Refine3 , Refine4 ). The iodine also raises one detail that light molecules never encounter: Gaussian's built-in Merz–Kollman radius table has no fifth-row entries, and you will see exactly how ParmFit supplies them. Every excerpt below is taken from verified runs of the inputs shown here ( Refine1–4.inp plus their sidecar configs). Fig. 1 — Structure of o-iodophenol (choi001). Every run writes a <base>.parmfitrun.in file next to the output that echoes your configuration with defaults filled in; use it to confirm the keys ParmFit actually read, and watch the log for Unknown left-hand warnings, which flag keys that no builder consumed. The reference definition of every key lives in the Refinement manual page and the shared sections of the ParmFit hub ; software and input requirements are summarized in the hub's Requirements section.","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#overview"},{"heading":"Example Files","level":2,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":false,"page_role":"content","section_order":2,"text":"A linked file name on this page opens the original file from the verified runs, hosted in the MAPLE-Tutorial repository; every input and output file is linked where it is used in the cases below. Save the input files of one case into one folder; Case 1 starts from Refine1.inp . Software. Every case needs AmberTools on PATH . Case 1 needs nothing else; Cases 2 and 3 also need Gaussian 16, which evaluates the ESP for the RESP charges and runs the QM reference — see the hub's Requirements and QM Reference sections. The complete run archive, including every _work/ directory, is on Zenodo: 10.5281/zenodo.23126271 . It has one zip per case — Case1.zip (30 KB), Case2.zip (62 MB), and Case3.zip (1.7 GB; Refine3 and Refine4) — and each unpacks to a folder of the same name. The NCAA and MetalAA archives use the same zip names, so keep each tutorial in its own folder. To rerun a case, start from its input files in a new folder: inside an unpacked archive folder, TorsionFit would read the archived scans instead of running its own scan (see the hub’s Scan Reuse ).","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#example-files"},{"heading":"Case 1 — The basic input: bonded refinement","level":2,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":false,"page_role":"content","section_order":3,"text":"Goal. Refine the bonded terms and torsions of a small molecule provided as a GAFF2-typed mol2, keeping its original charges. This is entirely default behavior: chg_fit=none , bonded=mseminario , torsionfit=true . Input. The inline coordinates are the working geometry; the mol2 file supplies topology, atom types, and charges, and the single key is set in the sidecar. The coordinate block and the mol2 must list the same atoms in the same order, hydrogens included: MAPLE checks only that the atom counts match and then pairs atoms by position, so it cannot reconcile two files whose atom orders differ. The coordinate values themselves need not match the mol2. The header declares the route with method=refinement : No typed mol2 at hand? This tutorial ships choi001_gaff2.mol2 , but mol2= is optional: omit it and ParmFit writes the inline coordinates to <base>_work/ante.pdb , types them with antechamber -at gaff2 into <base>_work/<base>_ff.mol2 (residue LIG ), and fills the charge column with zero placeholders — chg_fit then defaults to abcg2 , so the final charges still come from the charge stage rather than the placeholders. Refine1.inp #model=uma(size=uma-s-1p1,task=omol) #parmfit(method=refinement,input=Refine1.in) #device=gpu0 I 3.54000000 1.42000000 0.00000000 C 3.55600000 1.47900000 -2.08800000 C 4.63400000 0.90600000 -2.76200000 H 5.45500000 0.43700000 -2.22200000 C 4.67700000 0.92700000 -4.15700000 H 5.51600000 0.48000000 -4.68200000 C 3.64100000 1.52200000 -4.87700000 H 3.67400000 1.53800000 -5.96300000 C 2.56300000 2.09500000 -4.20400000 H 1.76000000 2.55700000 -4.77200000 C 2.52000000 2.07400000 -2.80900000 O 1.44800000 2.64500000 -2.18900000 H 1.53600000 2.56400000 -1.22800000 Refine1.in reads the molecule from choi001_gaff2.mol2 Refine1.in # Refinement route settings; declare method=refinement in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. mol2=choi001_gaff2.mol2 Run. In the folder that holds Refine1.inp , Refine1.in , and choi001_gaff2.mol2 : maple Refine1.inp Refine1.out # or simply: maple Refine1.inp The second argument names the log; without it, MAPLE derives the log name from the input, so both forms write Refine1.out . The run also writes the resolved configuration Refine1.parmfitrun.in and the work directory Refine1_work/ . A run has finished normally when the result block reads Status: completed and the log ends with a TOTAL RUN TIME line; on the tutorial hardware Case 1 takes about 22 s. What happens. Initial parameters. parmchk2 -s gaff2 -a Y builds Refine1_work/Refine1_original.frcmod from the input mol2. Optimization. The MLIP (machine-learned interatomic potential; LBFGS) relaxes the inline coordinates. Bonded refinement. An MLIP Cartesian Hessian feeds mSeminario, which updates the bonded terms — including the GAFF2 i-ca bond to the iodine, whose force constant is revised substantially (see the table below). Charges. With chg_fit=none , the charges of the input mol2 are kept unchanged; no chargefit/ directory is created. TorsionFit. Auto-selection finds exactly one rotatable torsion — the exocyclic phenol C–O bond (11, 12) , whose rotation swings the hydroxyl over the ortho-iodine; ring torsions are excluded. This bond is scanned a full circle every 10° by default and fitted in two stages. Export. Amber mol2/frcmod/tleap input and GROMACS top/gro files are written. The resolved configuration. Next to Refine1.out , MAPLE writes Refine1.parmfitrun.in . For this case almost every entry is a filled-in default: # parmfitrun.in - resolved parmfit configuration for method=refinement # Generated by MAPLE parmfit; values are the user config entries with defaults filled in. # This file is itself a valid parmfit config and can be referenced via input=. # refinement run # Site composition, charge source and general refinement settings # input mol2 with GAFF2 atom types mol2 = choi001_gaff2.mol2 # (mseminario, seminario, none) bonded = mseminario # frequency scaling for Seminario constants vib_scale = 1.0 # QM reference # QM reference geometry and Hessian jobs # run QM reference geometry and Hessian jobs iqm = false # (g16, g09, gaussian, orca) qm_engine = g16 ... (open the real file after a run to see every resolved key) Reading the output. The setup header confirms what was consumed — check the QM reference and torsion lines before reading anything else: ====================================================================== Parmfit Refinement Setup ====================================================================== Input mol2: choi001_gaff2.mol2 Initial frcmod: Refine1_work/Refine1_original.frcmod Topology atoms: 13 Topology bonds: 13 Bonded refinement: mSeminario QM reference: disabled QM compare: disabled TorsionFit: enabled Torsion backend: cgbs Torsion constraint:projected Torsion ensemble:false Scan grid: 10.0000 deg x 36 steps Stage2 refine: max_fast_cycles=3, max_iter_per_cycle=256, tol=1e-06 Torsion bonds: auto-select non-ring torsion bonds with proper torsions Assigned terms: bonds: 13 (unmatched: 0) angles: 19 (unmatched: 0) dihedrals: 26 (unmatched: 0) impropers: 6 (unmatched: 0) nonbonds: 13 (unmatched: 0) The stage trace shows the pipeline order. With chg_fit=none , ParmFit deliberately skips the charge-fitting stage : [Refinement] initial parameter assignment ... [Refinement] MLIP geometry optimization ... [Refinement] MLIP Hessian + mSeminario ... [Refinement] TorsionFit ... [Refinement] export GROMACS ... [Refinement] export Amber ... The mSeminario table lists only changed terms, with the old values on the left of | and the new values on the right — the iodine terms first: (1,2) i-ca k=234.900000 r=2.129000 | k=135.307826 r=2.089184 (2,3) ca-ca k=461.100000 r=1.398000 | k=387.211126 r=1.386447 (1,2,3) i-ca-ca k=57.500000 theta=119.1100 | k=43.159181 theta=119.2977 (1,2,11) i-ca-ca k=57.500000 theta=119.1100 | k=42.841349 theta=119.8516 ... The torsion energy trace ends with the number to watch — the MAE (mean absolute error)/RMSE (root-mean-square error) of the fitted profile against the MLIP reference. The rotor profile shows two planar wells (one over the iodine side) separated by twin perpendicular barriers of nearly 6 kcal/mol: Torsion energy trace: torsion bond (11, 12): scan xyz: Refine1_work/torsionfit/Refine1_torsionfit_11-12_scan_final.xyz angle_deg MLIP_ref orig_ref stage0_ref stage1_ref stage2_ref 359.9226 0.000000 0.000000 0.000000 0.000000 0.000000 369.9226 0.159524 0.185740 0.198823 0.154343 0.159719 389.9226 1.331669 1.618097 1.693869 1.273449 1.316369 419.9226 3.992471 5.133502 5.326029 3.919965 3.982378 459.9226 5.892447 8.307398 8.560909 5.939417 5.911643 539.9226 3.331109 7.509462 7.699650 3.483694 3.367189 ... MLIP_ref vs stage2_final: MAE = 0.016114 kcal/mol, RMSE = 0.019326 kcal/mol Fig. 2 — Case 1: the GAFF2 (revUMA) profile tracks the Reference across both barriers; the original GAFF2 profile overshoots both. GAFF2 (revUMA) labels the GAFF2 parameter set after ParmFit’s refit in this run; in Case 1 the Reference is the UMA scan ( MLIP_ref ). Finally, the result block lists the products and the parameter-change counts: ====================================================================== PARMFIT REFINEMENT RESULT ====================================================================== Status: completed Input mol2: choi001_gaff2.mol2 Main products: Amber mol2: Refine1_work/Refine1_maple.mol2 Amber frcmod: Refine1_work/Refine1_maple.frcmod GROMACS top: Refine1_work/Refine1_maple.top GROMACS gro: Refine1_work/Refine1_maple.gro Amber tleap: Refine1_work/Refine1_maple_tleap.in Stage timing: Hessian + mSeminario 7s geometry optimization 2s TorsionFit 0s initial parameter assignment 0s export Amber 0s export GROMACS 0s charge fitting 0s Parameter changes: bonded refinement: mSeminario bonds changed by bonded refine: 13 angles changed by bonded refine: 19 dihedrals changed by TorsionFit: 2 other changes: none TorsionFit: state: enabled torsion bonds: (11, 12) scan files: (11, 12): Refine1_work/torsionfit/Refine1_torsionfit_11-12_scan_final.xyz stage1: completed stage2: enabled, max_fast_cycles=3 fast cycles: executed=2, accepted=1, rejected=1 final parameters: Stage2 fast cycle 1 Warnings: none TorsionFit 0s is not the cost of the scan: this run found the scan file that an earlier run had left in Refine1_work/torsionfit/ and read it instead of running its own scan (see the hub’s Scan Reuse ). A run from an empty folder performs the full scan. The log closes with MAPLE’s reminder about the hydrogen-bond list of the Amber topology — printed on every Refinement run, because topologies written from MAPLE atom types must be normalized with ParmEd before SHAKE (see the manual’s ParmEd note ). This run’s reminder reads: ====================================================================== IMPORTANT ====================================================================== Due to the limitations of custom atom types, the exported topology must be normalized with ParmEd before use. tleap identifies hydrogens by the leading character of the atom type, which MAPLE types do not carry, so it writes an empty BONDS_INC_HYDROGEN section and SHAKE (ntc=2) would constrain nothing. ParmEd rebuilds that section from ATOMIC_NUMBER, e.g.: tleap -f Refine1_maple_tleap.in parmed -p Refine1_maple_gas.prmtop < < < $'outparm Refine1_maple_gas_parmed.prmtop\\nquit' ======================================================================","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#case-1"},{"heading":"Case 2 — RESP charges and a QM geometry","level":2,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":false,"page_role":"content","section_order":4,"text":"What changed. The sidecar gains four keys. With chg_fit=resp , charges are derived at runtime — Gaussian evaluates the ESP (electrostatic potential), then AmberTools performs the two-stage RESP fit. With iqm=true and opt_level=B3LYP/def2SVP , the geometry and Hessian references move to Gaussian. With the default qm_mode=1 , the torsion scan stays MLIP-driven, with a QM single point at each frame. One level choice is iodine-specific: the classic RESP basis HF/6-31G(d) does not exist for iodine, so this case sets chg_level=HF/def2SVP — the def2 family carries iodine with its effective core potential. Note also the level spelling: with qm_engine=g16 , write B3LYP/def2SVP without the hyphen — the engine-spelling rule is documented in the hub's Levels of Theory . Refine2.inp #model=uma(size=uma-s-1p1,task=omol) #parmfit(method=refinement,input=Refine2.in) #device=gpu0 I 3.54000000 1.42000000 0.00000000 C 3.55600000 1.47900000 -2.08800000 C 4.63400000 0.90600000 -2.76200000 H 5.45500000 0.43700000 -2.22200000 C 4.67700000 0.92700000 -4.15700000 H 5.51600000 0.48000000 -4.68200000 C 3.64100000 1.52200000 -4.87700000 H 3.67400000 1.53800000 -5.96300000 C 2.56300000 2.09500000 -4.20400000 H 1.76000000 2.55700000 -4.77200000 C 2.52000000 2.07400000 -2.80900000 O 1.44800000 2.64500000 -2.18900000 H 1.53600000 2.56400000 -1.22800000 Refine2.in reads the molecule from choi001_gaff2.mol2 Refine2.in # Refinement route settings; declare method=refinement in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. mol2=choi001_gaff2.mol2 # Runtime charge derivation: Gaussian ESP + AmberTools two-stage RESP # (def2SVP instead of the classic HF/6-31G(d): iodine has no 6-31G basis; # the def2 family carries iodine with its ECP) chg_fit=resp chg_level=HF/def2SVP # QM reference, qm_mode 1: MLIP drives the scan, QM single point per frame iqm=true opt_level=B3LYP/def2SVP Run. maple Refine2.inp Refine2.out , as in Case 1; on the tutorial hardware it takes about 7 min, and Refine2.parmfitrun.in shows the four new keys resolved against their defaults. What happens. The MLIP pre-optimization still runs, then a QM opt+frequency job supersedes it as the reference geometry and Hessian source for mSeminario. Charge derivation runs regardless of the iqm setting — Gaussian supplies the ESP, AmberTools performs the RESP stages; the Gaussian jobs run with the configured qm_nproc / qm_mem . The iodine radius detail. Open Refine2_work/chargefit/resp.gjf and the route line is not the plain Pop=MK you may know from light molecules: #P HF/def2SVP Pop(MK,ReadRadii) IOp(6/33=2) SCF=Tight ... (molecule specification) I 1.875 Gaussian's built-in Merz–Kollman radius table stops well before the fifth row, and l602 aborts with GetVDW: no radius for atomic number 53 otherwise. ParmFit therefore writes Pop(MK,ReadRadii) and appends a radius line for every element the built-in table lacks — 1.875 Å for iodine, from its UFF van der Waals radius divided by 1.2. Light molecules never need this fallback; without it, a molecule containing iodine cannot run. The setup header and stage trace in Refine2.out show the two new stages — the enabled QM reference and the charge-fitting step: QM reference: enabled, mode=1, engine=g16, opt=B3LYP/def2SVP, sp=B3LYP/def2SVP ... [Refinement] initial parameter assignment ... [Refinement] MLIP geometry optimization ... [Refinement] QM reference optimization ... [Refinement] QM Hessian + mSeminario ... [Refinement] atomic charge fitting ... [Refinement] TorsionFit ... [Refinement] Using QM reference data for TorsionFit (mode=1) ... [Refinement] export GROMACS ... [Refinement] export Amber ... The result block gains a Charge fitting: section: Charge fitting: method: resp RESP level: HF/def2SVP target charge: 0 actual charge: -0.00000000 work MOL2: Refine2_work/chargefit/qm_route_charged.mol2 final MOL2: Refine2_work/Refine2_maple.mol2 Stage timing: TorsionFit 5m 23s Hessian + mSeminario 1m 29s charge fitting 4s geometry optimization 2s The torsion trace now references QM single points — the reference column becomes QM_ref and the scan file is prefixed qm_ : torsion bond (11, 12): scan xyz: Refine2_work/torsionfit/Refine2_qm_torsionfit_11-12_scan_final.xyz angle_deg QM_ref orig_ref stage0_ref stage1_ref stage2_ref 359.9837 0.000000 0.000000 0.000000 0.000000 0.000000 369.9837 0.208213 0.148268 0.159940 0.197624 0.197976 389.9837 1.623683 1.167627 1.280879 1.590847 1.591518 ... QM_ref vs stage2_final: MAE = 0.018492 kcal/mol, RMSE = 0.021605 kcal/mol The stage0/stage1/stage2 columns are the fitted MM (molecular-mechanics) profile after each fitting stage; what matters is that the last column tracks the QM reference over the whole profile; which stage ended up final does not matter here. Checkpoint Compare target charge: with actual charge: — Refinement never rescales fitted charges, so a mismatch is reported, not hidden (here 0 vs −0.00000000).","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#case-2"},{"heading":"Case 3 — Relaxing each frame on the QM surface","level":2,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":false,"page_role":"content","section_order":5,"text":"What changed. The configuration lives in the external sidecar files referenced with input= — the method itself stays in the inline #parmfit(...) header. Case 2 kept the default qm_mode=1 , in which QM single-points score the MLIP scan’s frames; this case makes the choice explicit, running Refinement with qm_mode=2 and qm_mode=3 . The Refine4 header declares level=tight : mode 3 hands the frame relaxation to ParmFit’s own optimizer, and level is MAPLE’s global convergence tier , so the run raises that optimizer’s stopping criteria from the default medium tier to tight — the same depth g16’s own optimizer stops at. Input. Refine3.inp #model=uma(size=uma-s-1p1,task=omol) #parmfit(method=refinement,input=Refine3.in) #device=gpu0 I 3.54000000 1.42000000 0.00000000 C 3.55600000 1.47900000 -2.08800000 C 4.63400000 0.90600000 -2.76200000 H 5.45500000 0.43700000 -2.22200000 C 4.67700000 0.92700000 -4.15700000 H 5.51600000 0.48000000 -4.68200000 C 3.64100000 1.52200000 -4.87700000 H 3.67400000 1.53800000 -5.96300000 C 2.56300000 2.09500000 -4.20400000 H 1.76000000 2.55700000 -4.77200000 C 2.52000000 2.07400000 -2.80900000 O 1.44800000 2.64500000 -2.18900000 H 1.53600000 2.56400000 -1.22800000 External config. Paths such as mol2 are resolved relative to this file. Refine3.in reads the molecule from choi001_gaff2.mol2 Refine3.in # Refinement route settings; declare method=refinement in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. mol2=choi001_gaff2.mol2 # Runtime charge derivation: Gaussian ESP + AmberTools two-stage RESP # (def2SVP instead of the classic HF/6-31G(d): iodine has no 6-31G basis; # the def2 family carries iodine with its ECP) chg_fit=resp chg_level=HF/def2SVP # QM reference, qm_mode 2: MLIP pre-optimization, QM constrained opt per frame iqm=true qm_mode=2 opt_level=B3LYP/def2SVP Refine4 input. The convergence tier lives in the inline header: Refine4.inp #model=uma(size=uma-s-1p1,task=omol) #parmfit(method=refinement,input=Refine4.in,level=tight) #device=gpu0 I 3.54000000 1.42000000 0.00000000 C 3.55600000 1.47900000 -2.08800000 C 4.63400000 0.90600000 -2.76200000 H 5.45500000 0.43700000 -2.22200000 C 4.67700000 0.92700000 -4.15700000 H 5.51600000 0.48000000 -4.68200000 C 3.64100000 1.52200000 -4.87700000 H 3.67400000 1.53800000 -5.96300000 C 2.56300000 2.09500000 -4.20400000 H 1.76000000 2.55700000 -4.77200000 C 2.52000000 2.07400000 -2.80900000 O 1.44800000 2.64500000 -2.18900000 H 1.53600000 2.56400000 -1.22800000 Keep method , input , and level in this header: the sidecar rejects method= and input= , and a level= written there is not applied — the log reports it only as an Unknown left-hand key. The reference run’s input, as archived on Zenodo, had a stray comma ( input=Refine4.in,,level=tight ); the copy on GitHub has it removed. MAPLE ignored that comma: it left only an unnamed : True line under Parsed configuration in Refine4.out . The sidecar Refine4.in sets the same keys as Refine3.in except qm_mode=3 : Refine4.in reads the molecule from choi001_gaff2.mol2 Refine4.in # Refinement route settings; declare method=refinement in #parmfit(...) and reference this file via input= # Only non-default entries are listed; the generated parmfitrun.in shows every resolved value. mol2=choi001_gaff2.mol2 # Runtime charge derivation: Gaussian ESP + AmberTools two-stage RESP # (def2SVP instead of the classic HF/6-31G(d): iodine has no 6-31G basis; # the def2 family carries iodine with its ECP) chg_fit=resp chg_level=HF/def2SVP # QM reference, qm_mode 3: QM energy/forces with the ParmFit optimizer driving the scan iqm=true qm_mode=3 opt_level=B3LYP/def2SVP Run. maple Refine3.inp Refine3.out and maple Refine4.inp Refine4.out , as in Case 1; on the tutorial hardware they take about 28 min and 1 h 36 min, and their resolved configurations Refine3.parmfitrun.in and Refine4.parmfitrun.in differ only in qm_mode , 2 versus 3. What happens. The charge and reference setup is identical to Case 2; only the way QM data enters TorsionFit changes. In mode 2, each scan frame comes from a QM constrained optimization of the torsion; in mode 3, the QM engine evaluates energies and forces directly and MAPLE's own optimizer drives the scan — see the hub's qm_mode table for the full semantics. The header and stage line always report the active mode — here from Refine3.out : QM reference: enabled, mode=2, engine=g16, opt=B3LYP/def2SVP, sp=B3LYP/def2SVP [Refinement] Using QM reference data for TorsionFit (mode=2) ... The three verified runs of this molecule compare like this: Refine2 (mode 1) Refine3 (mode 2) Refine4 (mode 3) scan xyz: Refine2_qm_torsionfit_11-12_scan_final.xyz Refine3_qm_torsionfit_11-12_scan_final.xyz Refine4_mode3_qm_torsionfit_11-12_scan_final.xyz frame relaxation: MLIP scan (medium) g16 Opt (defaults) built-in opt (tight) Gaussian outputs in _work: 39 39 1006 torsion MAE (kcal/mol): 0.018492 0.010873 0.025352 TOTAL RUN TIME: 7m 11s 27m 50s 1h 36m 13s The three scans compared above are hosted alongside the inputs: Refine2_qm_torsionfit_11-12_scan_final.xyz , Refine3_qm_torsionfit_11-12_scan_final.xyz , and Refine4_mode3_qm_torsionfit_11-12_scan_final.xyz . Fig. 3 — Case 3: GAFF2 (revUMA) profiles for qm_mode=1–3, each fitted against its own Reference; the references are not meant to overlay. Here every Reference is a B3LYP/def2SVP scan ( QM_ref ), not UMA; GAFF2 (revUMA) still names the refitted GAFF2 set. The same B3LYP potential-energy surface and the same frozen dihedral underlie all three references — what differs is who relaxes each frame and where the relaxation stops . The rotor couples to the framework — the C–O bond breathes with conjugation, and the framework angles and the I···O contact absorb the steric load of the hydroxyl swinging past the iodine — so relaxed and unrelaxed frames are genuinely different geometries. Mode 1 scores the MLIP scan’s geometries as they are; modes 2 and 3 relax every frame on the QM surface, and with mode 3’s depth set by level=tight the two relaxed scans stop at the same depth. That is why the three profiles in Fig. 3 differ, and depth is what separates the run times in the table above. The Gaussian-output totals in the table are job counts, not gradient-evaluation counts: mode 2 submits one Opt=ModRedundant constrained optimization per frame, while mode 3 submits one Force evaluation at a time as ParmFit’s optimizer steps from frame to frame — the tighter the level , the more evaluations. Checkpoint Pick the mode by what stands behind the reference and what it costs: mode 1 reuses the MLIP scan at single-point cost, mode 2 replaces each frame with a complete constrained QM optimization, mode 3 hands the scan steps to QM at single-force cost — raise its depth with level=tight as here, or accept the default medium tier and its shallower frames. Every product path above is relative to the run’s <base>_work/ directory.","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#case-3"},{"heading":"Where to Go Next","level":2,"page":"tasks/parmfit/parmfit_refinement_tutorial.html","page_entry":false,"page_role":"content","section_order":6,"text":"Everything you need for MD is now in Refine n _work/ : the Amber mol2 and frcmod (plus GROMACS files) carry the refined parameters. One deployment step remains, and Case 1 demonstrated it: run the exported tleap input, then pass the topology through ParmEd — MAPLE atom types leave tleap’s hydrogen-bond section empty, and SHAKE needs it rebuilt — before you take Refine1_maple_gas_parmed.prmtop into your simulation. The manual’s ParmEd note has the reference wording. Refinement manual — parameter reference, output files, and limits. ChargeFit , QM reference , and TorsionFit on the ParmFit hub — the stages these routes share, documented once on the hub. NCAA (noncanonical amino acid) tutorial and MetalAA tutorial — simple worked examples for the PDB (Protein Data Bank) routes. Example files and run archive. See Example Files for the hosted files and the complete Zenodo archive.","title":"Refinement Tutorial - MAPLE","trail":["Tutorials","ParmFit","Refinement Tutorial"],"type":"Task","url":"tasks/parmfit/parmfit_refinement_tutorial.html#where-next"},{"heading":"ParmFit Tutorials","level":1,"page":"tasks/parmfit/parmfit_tutorial.html","page_entry":true,"page_role":"landing","section_order":0,"text":"Get to know ParmFit’s parameterization workflow by solving a few simple examples.","title":"ParmFit Tutorials - MAPLE","trail":["Tutorials","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit_tutorial.html#parmfit-tutorials"},{"heading":"The Systems","level":2,"page":"tasks/parmfit/parmfit_tutorial.html","page_entry":false,"page_role":"landing","section_order":1,"text":"Refinement","title":"ParmFit Tutorials - MAPLE","trail":["Tutorials","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit_tutorial.html#systems"},{"heading":"o-Iodophenol","level":3,"page":"tasks/parmfit/parmfit_tutorial.html","page_entry":false,"page_role":"landing","section_order":2,"text":"A phenol with an iodine beside its hydroxyl. Start the tutorial → NCAA","title":"ParmFit Tutorials - MAPLE","trail":["Tutorials","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit_tutorial.html#o-iodophenol"},{"heading":"FAD in 6JQH","level":3,"page":"tasks/parmfit/parmfit_tutorial.html","page_entry":false,"page_role":"landing","section_order":3,"text":"A histidine residue carrying a covalent FAD cofactor. Start the tutorial → MetalAA","title":"ParmFit Tutorials - MAPLE","trail":["Tutorials","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit_tutorial.html#fad-in-6jqh"},{"heading":"HEME in 4ZF6","level":3,"page":"tasks/parmfit/parmfit_tutorial.html","page_entry":false,"page_role":"landing","section_order":4,"text":"A cysteine-ligated heme iron site. Start the tutorial →","title":"ParmFit Tutorials - MAPLE","trail":["Tutorials","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit_tutorial.html#heme-in-4zf6"},{"heading":"Before You Start","level":2,"page":"tasks/parmfit/parmfit_tutorial.html","page_entry":false,"page_role":"landing","section_order":5,"text":"Requirements. Software and input needs are summarized in the ParmFit hub’s Requirements section . Only Refinement Case 1 runs without Gaussian; every other case needs it for its RESP charges — the Refinement cases also for their QM reference. Model. Every run in these tutorials uses the same checkpoint — UMA-S-1.1, selected with #model=uma(size=uma-s-1p1) (the Refinement launchers add task=omol ). Hardware. Every excerpt and timing in these tutorials comes from runs on an RTX 3060 Laptop GPU and an 8-core AMD CPU — sufficient for every run shown here. Every Gaussian job used the defaults qm_nproc=8 and qm_mem=24 (GB); set lower values in the sidecar config on a smaller machine (see General Settings ). Example files. Right after its Overview, each tutorial links every input and output file where it is used, followed by its complete Zenodo run archive.","title":"ParmFit Tutorials - MAPLE","trail":["Tutorials","ParmFit"],"type":"Task","url":"tasks/parmfit/parmfit_tutorial.html#before"},{"heading":"Potential Energy Surface Scanning","level":1,"page":"tasks/scan/scan.html","page_entry":true,"page_role":"landing","section_order":0,"text":"","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#potential-energy-surface-scanning"},{"heading":"Overview","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":1,"text":"The PES Scan module performs systematic exploration of the potential energy surface along user-specified internal coordinates. It supports one-dimensional (1D), two-dimensional (2D), and three-dimensional (3D) scans. Two scan modes are available: relaxed scans, where all coordinates except the scanned ones are optimized at each point, and rigid scans, where MAPLE moves the detected connected fragment to satisfy the target scan coordinate without running an optimization. PES scans are commonly used for constructing torsional energy profiles, mapping bond-dissociation curves, exploring conformational landscapes, and generating starting geometries for transition-state searches.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#overview"},{"heading":"Available Methods","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":2,"text":"Relaxed scans reuse MAPLE's geometry optimization dispatcher at each scan point. The following optimizers can be selected via the method parameter; rigid scans do not require an optimizer. Method Keyword Description L-BFGS lbfgs Limited-memory BFGS quasi-Newton method. Default and recommended for routine relaxed scans. RFO rfo Rational Function Optimization with trust-radius control. Useful for difficult scan points or strong curvature changes. SD sd Steepest descent. Robust stabilization for distorted geometries. CG cg Conjugate gradient. Memory-efficient relaxation when starting geometries are already reasonable. SD/CG sdcg Hybrid steepest-descent / conjugate-gradient with optional DIIS acceleration.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#available-methods"},{"heading":"Quick Usage","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":3,"text":"To run a PES scan, add the #scan directive to your input file. The method and scan mode can be specified in parentheses: #scan(method=lbfgs, mode=relaxed) If no options are specified, the defaults method=lbfgs and mode=relaxed are used: #scan Rigid scans skip optimization and only move the detected connected fragment to satisfy the target coordinate: #scan(mode=rigid)","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#quick-usage"},{"heading":"Scan Coordinate Syntax","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":4,"text":"Scan coordinates are specified with the S command at the end of the input file, after the molecular geometry. The format depends on the type of internal coordinate being scanned: Distance scan (2 atoms): S atom1 atom2 step_size n_steps Angle scan (3 atoms): S atom1 atom2 atom3 step_size n_steps Dihedral scan (4 atoms): S atom1 atom2 atom3 atom4 step_size n_steps Where: atom1 , atom2 , ... — 1-based atom indices defining the internal coordinate to scan. step_size — increment per step (in Angstroms for bonds, degrees for angles/dihedrals). Negative values scan in the decreasing direction. n_steps — number of increments to apply after the initial point; each scan coordinate therefore produces n_steps + 1 values.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#scan-coordinate-syntax"},{"heading":"Scan Modes","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":5,"text":"MAPLE supports two scan modes, selected via the mode parameter: Mode Description Use Case relaxed Optimizes all degrees of freedom except the scanned coordinates at each scan point. Produces a minimum-energy path along the scan coordinate. Torsional profiles, bond dissociation curves, conformational analysis. rigid Moves the detected connected fragment as a rigid body to satisfy each target scan coordinate. No geometry optimization is performed. Quick energy profiles, repulsive wall scans, initial survey of PES topology.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#scan-modes"},{"heading":"Input Example","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":6,"text":"The checked-in MAPLE example examples/scan/da.inp is a two-coordinate relaxed scan with the ANI-1xnr model on a GPU. Only the long coordinate block is elided below; in a real input file the S scan commands must come after the molecular coordinates because MAPLE parses them as post-processing commands: #model=ANI-1xnr #scan #device=gpu0 [XYZ coordinates from examples/scan/da.inp] S 11 52 -0.1 15 S 14 51 -0.1 15 The two S lines define scanned distances, each with 15 increments of −0.1 Å, producing a 16 × 16 = 256 point grid. Because #scan defaults to method=lbfgs and mode=relaxed , the header above is equivalent to #scan(method=lbfgs, mode=relaxed) . At each grid point MAPLE constrains both target coordinates and optimizes the remaining degrees of freedom with the selected optimizer.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#input-example"},{"heading":"Common Parameters","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":7,"text":"These parameters are shared across all scan calculations. Individual optimizers may accept additional method-specific parameters (see each method's sub-page). Parameter Default Description mode relaxed Scan mode: relaxed (optimize at each point) or rigid (rigid-body fragment motion without optimization). method lbfgs Optimizer used for relaxed scans. Supported: lbfgs , rfo , sd , cg , sdcg . Ignored for rigid scans. level medium Convergence preset passed to the underlying optimizer (relaxed scans only). Options: extratight , tight , medium , loose , extraloose , superloose . max_iter 256 Maximum number of optimization cycles per scan point (relaxed scans only). verbose 0 Per-point optimizer output verbosity. Scan keeps this low by default to keep the scan log readable; the overall scan progress is always reported.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#common-parameters"},{"heading":"Output Files","level":2,"page":"tasks/scan/scan.html","page_entry":false,"page_role":"landing","section_order":8,"text":"The scan module produces the following output files: *_scan_final.xyz — Multi-frame XYZ file containing the final geometry at each scan point. Can be visualized as a trajectory in standard molecular viewers. *.out — Main text output with scan progress, energies, coordinates, and optimizer diagnostics when applicable. The scan trajectory file uses the standard multi-frame XYZ format, with one frame per scan point. Each frame header includes the scan combination index, target values of the scanned internal coordinates, and the energy. Tip For routine relaxed scans, the default L-BFGS optimizer with level=medium is sufficient. Use mode=rigid for quick initial PES surveys when geometry optimization at each point is not needed.","title":"PES Scan - MAPLE","trail":["Tasks","PES Scan"],"type":"Task","url":"tasks/scan/scan.html#output-files"},{"heading":"PES Scan with CG Optimization","level":1,"page":"tasks/scan/scan_cg.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"PES Scan: CG - MAPLE","trail":["Tasks","PES Scan","CG"],"type":"Task","url":"tasks/scan/scan_cg.html#pes-scan-with-cg-optimization"},{"heading":"Overview","level":2,"page":"tasks/scan/scan_cg.html","page_entry":false,"page_role":"content","section_order":1,"text":"Conjugate Gradient (CG) is available for relaxed PES scans through #scan(method=cg) . It reuses the CG-only mode of MAPLE's SD/CG optimizer family at each constrained scan point. CG is more efficient than pure SD when the starting geometry is already reasonable, while still keeping memory usage low.","title":"PES Scan: CG - MAPLE","trail":["Tasks","PES Scan","CG"],"type":"Task","url":"tasks/scan/scan_cg.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/scan/scan_cg.html","page_entry":false,"page_role":"content","section_order":2,"text":"Per-point CG settings reuse the same controls as #opt(method=cg) . With method=cg the SD phase is disabled at each scan point; the scan driver keeps per-point optimizer verbosity quiet. Parameter Type Default Description max_step float 0.2 Maximum step length in Angstrom. max_iter int 256 Maximum CG iterations per scan point. cg_restart_threshold float 0.2 Restart CG directions when the gradient change ratio exceeds this value. cg_beta_method str \"prp+\" Conjugate gradient beta formula. prp+ (Polak–Ribière-Plus) is recommended for molecular optimization. diis_enabled bool True Enable DIIS extrapolation acceleration. diis_store_every int 5 Store a DIIS snapshot every N steps. diis_min_snapshots int 3 Minimum snapshots required before DIIS extrapolation is attempted. diis_memory int 6 Maximum number of DIIS snapshots stored. verbose int 0 in scans Per-point optimizer verbosity. Scan keeps this low so the scan log stays readable.","title":"PES Scan: CG - MAPLE","trail":["Tasks","PES Scan","CG"],"type":"Task","url":"tasks/scan/scan_cg.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/scan/scan_cg.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/scan/cg/butane_torsion.inp . This is the relaxed butane torsion scan shown in the visualization below: #model=aimnet2nse #scan(method=cg,mode=relaxed) #device=gpu0 C -0.52081539 1.11161504 -0.13989751 C 0.59078300 0.29318923 -0.77842290 C 1.32746823 -0.60957381 0.21152861 C 0.45259197 -1.70775275 0.79614860 H -0.94949784 1.80049876 -0.87488523 H -1.32977057 0.47261032 0.22606643 H -0.14081339 1.70426027 0.69821742 H 1.31638081 0.98145785 -1.22807656 H 0.17655991 -0.30881448 -1.59557540 H 1.74762224 -0.00673639 1.02502995 H 2.17359552 -1.07649793 -0.30658812 H 1.05410451 -2.37229845 1.42471640 H -0.00260239 -2.31098551 0.00433108 H -0.34575942 -1.29510299 1.41986360 S 1 2 3 4 5.0 72 The final S line is a dihedral scan: four atom indices followed by a 5.0 degree step and 72 increments, producing 73 scan points including the initial geometry.","title":"PES Scan: CG - MAPLE","trail":["Tasks","PES Scan","CG"],"type":"Task","url":"tasks/scan/scan_cg.html#input-example"},{"heading":"Scan Visualization","level":2,"page":"tasks/scan/scan_cg.html","page_entry":false,"page_role":"content","section_order":4,"text":"The animation below pairs the generated scan geometries with the energy profile for a relaxed butane torsion scan using CG. Fig. 1 — Butane torsion relaxed scan (CG)","title":"PES Scan: CG - MAPLE","trail":["Tasks","PES Scan","CG"],"type":"Task","url":"tasks/scan/scan_cg.html#visualization"},{"heading":"When to Use CG Scans","level":2,"page":"tasks/scan/scan_cg.html","page_entry":false,"page_role":"content","section_order":5,"text":"Smooth scan regions: CG converges much faster than SD on well-behaved scan-point surfaces by exploiting gradient history to build conjugate search directions. Memory-constrained scans: CG stores only the previous gradient vector, making it more memory-efficient than L-BFGS for very large systems. Reasonable starting geometries: CG is most effective when initial per-point forces are moderate. For severely distorted structures, prefer SD or SD/CG for a more robust initial phase. Note For most scans, SD/CG (which runs SD first and automatically switches to CG) is preferable to pure CG, as it combines robust initial descent with efficient final convergence. Pure CG is best when scan-point starting geometries are already reasonable.","title":"PES Scan: CG - MAPLE","trail":["Tasks","PES Scan","CG"],"type":"Task","url":"tasks/scan/scan_cg.html#when-to-use"},{"heading":"PES Scan with L-BFGS Optimization","level":1,"page":"tasks/scan/scan_lbfgs.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"PES Scan: L-BFGS - MAPLE","trail":["Tasks","PES Scan","L-BFGS"],"type":"Task","url":"tasks/scan/scan_lbfgs.html#pes-scan-with-l-bfgs-optimization"},{"heading":"Overview","level":2,"page":"tasks/scan/scan_lbfgs.html","page_entry":false,"page_role":"content","section_order":1,"text":"The L-BFGS (Limited-memory Broyden–Fletcher–Goldfarb–Shanno) method is the default geometry optimizer used in relaxed PES scans. At each scan point, after the scanned internal coordinates are constrained to their target values, L-BFGS optimizes all remaining degrees of freedom to find the nearest local minimum on the constrained surface. L-BFGS builds a low-rank approximation to the inverse Hessian from a short history of past displacements and gradient changes, enabling efficient convergence without storing or inverting the full Hessian matrix. This makes it well suited for systems of any size, from small molecules to large biomolecular fragments.","title":"PES Scan: L-BFGS - MAPLE","trail":["Tasks","PES Scan","L-BFGS"],"type":"Task","url":"tasks/scan/scan_lbfgs.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/scan/scan_lbfgs.html","page_entry":false,"page_role":"content","section_order":2,"text":"Relaxed scans use the same L-BFGS optimizer as #opt(method=lbfgs) . The requested internal coordinates are fixed at each scan point while the remaining geometry is relaxed. Parameter Type Default Description memory int 5 Number of previous steps retained for the approximate inverse Hessian. curvature float 70.0 Initial diagonal Hessian estimate before optimization history is accumulated. max_step float 0.2 Maximum allowed atomic displacement per step (Angstroms). max_iter int 256 Maximum number of L-BFGS iterations per scan point. verbose int 0 in scans Output verbosity level. Scan sets this internally to suppress per-point optimizer detail and keep the scan log readable. Note Because relaxed scans use the same L-BFGS optimizer as geometry optimization, L-BFGS parameter names match the optimization L-BFGS page. Use level on #scan for the shared convergence preset; scan output keeps per-point optimizer verbosity quiet by design.","title":"PES Scan: L-BFGS - MAPLE","trail":["Tasks","PES Scan","L-BFGS"],"type":"Task","url":"tasks/scan/scan_lbfgs.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/scan/scan_lbfgs.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/scan/lbfgs/ethanol_torsion.inp . This is the relaxed ethanol torsion scan shown in the visualization below: #model=aimnet2nse #scan(method=lbfgs,mode=relaxed) #device=gpu0 C 0.00000000 0.00000000 0.00000000 C 1.52000000 0.00000000 0.00000000 O 2.07000000 1.21000000 0.00000000 H 2.94000000 1.20000000 0.00000000 H -0.54000000 0.94000000 0.00000000 H -0.54000000 -0.47000000 0.81400000 H -0.54000000 -0.47000000 -0.81400000 H 1.92000000 -0.52000000 0.89000000 H 1.92000000 -0.52000000 -0.89000000 S 1 2 3 4 5.0 72 The final S line is a dihedral scan: four atom indices followed by a 5.0 degree step and 72 increments, producing 73 scan points including the initial geometry.","title":"PES Scan: L-BFGS - MAPLE","trail":["Tasks","PES Scan","L-BFGS"],"type":"Task","url":"tasks/scan/scan_lbfgs.html#input-example"},{"heading":"Scan Visualization","level":2,"page":"tasks/scan/scan_lbfgs.html","page_entry":false,"page_role":"content","section_order":4,"text":"The animation below pairs the generated scan geometries with the energy profile for a relaxed ethanol torsion scan using L-BFGS. Fig. 1 — Ethanol torsion relaxed scan (L-BFGS)","title":"PES Scan: L-BFGS - MAPLE","trail":["Tasks","PES Scan","L-BFGS"],"type":"Task","url":"tasks/scan/scan_lbfgs.html#visualization"},{"heading":"When to Use","level":2,"page":"tasks/scan/scan_lbfgs.html","page_entry":false,"page_role":"content","section_order":5,"text":"L-BFGS is the recommended default method for relaxed PES scans. Use it when: You need a general-purpose relaxed scan with reliable convergence. The system is well-behaved and does not exhibit strong anharmonicity or near-degenerate states at the scan points. You want efficient optimization without explicit Hessian computation at each scan point. If L-BFGS has difficulty converging at certain scan points (for example, near transition states or in flat regions of the PES), consider reducing the scan step size, tightening the convergence level, or switching the relaxed scan to method=rfo .","title":"PES Scan: L-BFGS - MAPLE","trail":["Tasks","PES Scan","L-BFGS"],"type":"Task","url":"tasks/scan/scan_lbfgs.html#when-to-use"},{"heading":"PES Scan with RFO Optimization","level":1,"page":"tasks/scan/scan_rfo.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"PES Scan: RFO - MAPLE","trail":["Tasks","PES Scan","RFO"],"type":"Task","url":"tasks/scan/scan_rfo.html#pes-scan-with-rfo-optimization"},{"heading":"Overview","level":2,"page":"tasks/scan/scan_rfo.html","page_entry":false,"page_role":"content","section_order":1,"text":"RFO (Rational Function Optimization) is available as a relaxed PES scan optimizer through #scan(method=rfo) . At each scan point, MAPLE constrains the requested internal coordinates and reuses the same RFO minimizer used by #opt(method=rfo) to relax the remaining degrees of freedom. RFO is more expensive than L-BFGS because it uses Hessian information and a trust-region step, but it can be more stable when the scan passes through regions with strong curvature changes or difficult convergence.","title":"PES Scan: RFO - MAPLE","trail":["Tasks","PES Scan","RFO"],"type":"Task","url":"tasks/scan/scan_rfo.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/scan/scan_rfo.html","page_entry":false,"page_role":"content","section_order":2,"text":"Per-point RFO settings reuse the same controls as #opt(method=rfo) . The shared level preset on #scan supplies the scan-point convergence thresholds; the scan driver sets per-point optimizer verbosity to quiet by default. Parameter Type Default Description max_iter int 256 Maximum number of RFO iterations per scan point. trust_radius_init float 0.2 Initial trust radius in Angstrom. trust_radius_min float 1e-3 Minimum trust radius. trust_radius_max float 1.0 Maximum trust radius. eta_shrink float 0.75 Trust radius shrink factor when step quality is poor. eta_expand float 1.75 Trust radius expansion factor when step quality is good. evals_eps float 1e-10 Eigenvalue epsilon for numerical stability. mu_margin float 1e-8 Margin for the level-shift parameter mu. max_bisect_it int 60 Maximum bisection iterations for level-shift optimization. verbose int 0 in scans Per-point optimizer verbosity. Scan keeps this low so the scan log stays readable.","title":"PES Scan: RFO - MAPLE","trail":["Tasks","PES Scan","RFO"],"type":"Task","url":"tasks/scan/scan_rfo.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/scan/scan_rfo.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/scan/rfo/methanol_oh_torsion.inp . This is the relaxed methanol O-H torsion scan shown in the visualization below: #model=aimnet2nse #scan(method=rfo,mode=relaxed) #device=gpu0 C -0.46276972 1.15067867 0.42624477 O -0.32124714 -0.24861552 0.26422771 H -1.51133868 1.39211728 0.61684893 H -0.13712321 1.64920740 -0.48974849 H 0.15713375 1.48625319 1.26124710 H -0.61759765 -0.66356677 1.09214997 S 3 1 2 6 5.0 72 The final S line is a dihedral scan: four atom indices followed by a 5.0 degree step and 72 increments, producing 73 scan points including the initial geometry.","title":"PES Scan: RFO - MAPLE","trail":["Tasks","PES Scan","RFO"],"type":"Task","url":"tasks/scan/scan_rfo.html#input-example"},{"heading":"Scan Visualization","level":2,"page":"tasks/scan/scan_rfo.html","page_entry":false,"page_role":"content","section_order":4,"text":"The animation below pairs the generated scan geometries with the energy profile for a relaxed methanol torsion scan using RFO. Fig. 1 — Methanol torsion relaxed scan (RFO)","title":"PES Scan: RFO - MAPLE","trail":["Tasks","PES Scan","RFO"],"type":"Task","url":"tasks/scan/scan_rfo.html#visualization"},{"heading":"When to Use RFO Scans","level":2,"page":"tasks/scan/scan_rfo.html","page_entry":false,"page_role":"content","section_order":5,"text":"L-BFGS struggles at selected scan points: RFO's Hessian-based trust-region step accepts/rejects per step, providing a built-in safeguard against bad moves through strong curvature regions. Smaller systems or high-value scan regions: RFO stores and manipulates the full Hessian, so its cost is worth it only where the added robustness pays off. Routine large scans: Start with L-BFGS scan and switch to RFO only at scan points or regions where convergence fails. Tip For large systems where per-point RFO is too expensive, fall back to L-BFGS scan with a reduced max_step as a compromise between robustness and efficiency.","title":"PES Scan: RFO - MAPLE","trail":["Tasks","PES Scan","RFO"],"type":"Task","url":"tasks/scan/scan_rfo.html#when-to-use"},{"heading":"PES Scan with SD Optimization","level":1,"page":"tasks/scan/scan_sd.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"PES Scan: SD - MAPLE","trail":["Tasks","PES Scan","SD"],"type":"Task","url":"tasks/scan/scan_sd.html#pes-scan-with-sd-optimization"},{"heading":"Overview","level":2,"page":"tasks/scan/scan_sd.html","page_entry":false,"page_role":"content","section_order":1,"text":"Steepest Descent (SD) is available for relaxed PES scans through #scan(method=sd) . It reuses the SD-only mode of MAPLE's SD/CG optimizer family at every scan point. SD is robust for distorted geometries and high-force regions, but it usually converges more slowly near a minimum. It is most useful as a stabilizing scan optimizer for rough starting structures or problematic scan points.","title":"PES Scan: SD - MAPLE","trail":["Tasks","PES Scan","SD"],"type":"Task","url":"tasks/scan/scan_sd.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/scan/scan_sd.html","page_entry":false,"page_role":"content","section_order":2,"text":"Per-point SD settings reuse the same controls as #opt(method=sd) . With method=sd the CG phase is disabled at each scan point; the scan driver keeps per-point optimizer verbosity quiet. Parameter Type Default Description max_step float 0.2 Maximum step length in Angstrom. max_iter int 256 Maximum SD iterations per scan point. sd_max_iter int 50 Maximum SD iterations before stopping (when used as a standalone method). diis_enabled bool True Enable DIIS extrapolation acceleration. diis_store_every int 5 Store a DIIS snapshot every N steps. diis_min_snapshots int 3 Minimum snapshots required before DIIS extrapolation is attempted. diis_memory int 6 Maximum number of DIIS snapshots stored. verbose int 0 in scans Per-point optimizer verbosity. Scan keeps this low so the scan log stays readable.","title":"PES Scan: SD - MAPLE","trail":["Tasks","PES Scan","SD"],"type":"Task","url":"tasks/scan/scan_sd.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/scan/scan_sd.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/scan/sd/dimethyl_peroxide_torsion.inp . This is the relaxed dimethyl peroxide torsion scan shown in the visualization below: #model=aimnet2nse #scan(method=sd,mode=relaxed) #device=gpu0 C -0.38846526 -0.54120852 0.47889724 O -0.43299775 -0.36385918 -0.93087360 O 0.57946000 0.64373500 -1.22768354 C 1.45974812 0.03203524 -2.16138925 H 0.59947954 -0.89956469 0.78229810 H -1.13763115 -1.28584057 0.75935167 H -0.61851510 0.40189440 0.98297169 H 2.23953829 0.75053877 -2.42607962 H 1.92682619 -0.85102187 -1.71579499 H 0.91182580 -0.24730864 -3.06593618 S 1 2 3 4 5.0 72 The final S line is a dihedral scan: four atom indices followed by a 5.0 degree step and 72 increments, producing 73 scan points including the initial geometry.","title":"PES Scan: SD - MAPLE","trail":["Tasks","PES Scan","SD"],"type":"Task","url":"tasks/scan/scan_sd.html#input-example"},{"heading":"Scan Visualization","level":2,"page":"tasks/scan/scan_sd.html","page_entry":false,"page_role":"content","section_order":4,"text":"The animation below pairs the generated scan geometries with the energy profile for a relaxed dimethyl peroxide torsion scan using SD. Fig. 1 — Dimethyl peroxide torsion relaxed scan (SD)","title":"PES Scan: SD - MAPLE","trail":["Tasks","PES Scan","SD"],"type":"Task","url":"tasks/scan/scan_sd.html#visualization"},{"heading":"When to Use SD Scans","level":2,"page":"tasks/scan/scan_sd.html","page_entry":false,"page_role":"content","section_order":5,"text":"Severely distorted scan geometries: When early scan points have large steric clashes or unreasonable bond lengths, SD rapidly reduces the worst per-point forces without requiring Hessian information. Robust pre-relaxation: A short SD scan can stabilise structures before switching to L-BFGS , CG , or SD/CG . Avoid for large production grids: SD's slow convergence near the minimum makes it inefficient when a faster optimizer would converge reliably. Note Pure SD is rarely the best choice for a complete scan. Consider SD/CG to automatically transition to conjugate gradient once large initial forces have been reduced.","title":"PES Scan: SD - MAPLE","trail":["Tasks","PES Scan","SD"],"type":"Task","url":"tasks/scan/scan_sd.html#when-to-use"},{"heading":"PES Scan with SD/CG Optimization","level":1,"page":"tasks/scan/scan_sdcg.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"PES Scan: SD/CG - MAPLE","trail":["Tasks","PES Scan","SD/CG"],"type":"Task","url":"tasks/scan/scan_sdcg.html#pes-scan-with-sd-cg-optimization"},{"heading":"Overview","level":2,"page":"tasks/scan/scan_sdcg.html","page_entry":false,"page_role":"content","section_order":1,"text":"SD/CG is available for relaxed PES scans through #scan(method=sdcg) . It reuses MAPLE's hybrid SD-to-CG optimizer at each scan point: the SD phase first stabilizes high-force geometries, then the CG phase improves convergence near the constrained minimum. This method is useful when a scan contains both rough and smooth regions, or when you want a single optimizer that can handle changing scan-point difficulty.","title":"PES Scan: SD/CG - MAPLE","trail":["Tasks","PES Scan","SD/CG"],"type":"Task","url":"tasks/scan/scan_sdcg.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/scan/scan_sdcg.html","page_entry":false,"page_role":"content","section_order":2,"text":"Per-point SD/CG settings reuse the same controls as #opt(method=sdcg) . The scan driver keeps per-point optimizer verbosity quiet. Parameter Type Default Description max_step float 0.2 Maximum step length in Angstrom. max_iter int 256 Maximum optimization cycles per scan point. sd_max_iter int 50 Maximum iterations in the initial SD phase before switching to CG. cg_switch_fmax float 0.0 Switch from SD to CG when the maximum force drops below this value (Hartree/Angstrom). The default 0.0 enables the runtime auto-threshold: 0.5 × the initial maximum force. cg_restart_threshold float 0.2 Restart CG directions when the gradient change ratio exceeds this value. cg_beta_method str \"prp+\" Conjugate gradient beta formula. diis_enabled bool True Enable DIIS extrapolation acceleration. diis_store_every int 5 Store a DIIS snapshot every N steps. diis_min_snapshots int 3 Minimum snapshots required before DIIS extrapolation is attempted. diis_memory int 6 Maximum number of DIIS snapshots stored. verbose int 0 in scans Per-point optimizer verbosity. Scan keeps this low so the scan log stays readable.","title":"PES Scan: SD/CG - MAPLE","trail":["Tasks","PES Scan","SD/CG"],"type":"Task","url":"tasks/scan/scan_sdcg.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/scan/scan_sdcg.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/scan/sdcg/glycine_backbone_torsion.inp . This is the relaxed glycine backbone torsion scan shown in the visualization below: #model=aimnet2nse #scan(method=sdcg,mode=relaxed) #device=gpu0 N -1.64695360 -1.29691911 -0.90833498 C -0.45216594 -0.59642464 -1.41625210 C -0.84033589 0.54283507 -2.34787441 O -1.97257790 0.87393427 -2.66478245 O 0.22929521 1.20487418 -2.83060947 H -2.25086549 -0.60633338 -0.45686313 H -2.19402852 -1.61340515 -1.71207045 H 0.17205835 -1.30686984 -1.96558531 H 0.10890908 -0.18794943 -0.57097223 H -0.15752184 1.89889132 -3.40493371 S 6 1 2 3 5.0 72 The final S line is a dihedral scan: four atom indices followed by a 5.0 degree step and 72 increments, producing 73 scan points including the initial geometry.","title":"PES Scan: SD/CG - MAPLE","trail":["Tasks","PES Scan","SD/CG"],"type":"Task","url":"tasks/scan/scan_sdcg.html#input-example"},{"heading":"Scan Visualization","level":2,"page":"tasks/scan/scan_sdcg.html","page_entry":false,"page_role":"content","section_order":4,"text":"The animation below pairs the generated scan geometries with the energy profile for a relaxed glycine backbone torsion scan using SD/CG. Fig. 1 — Glycine backbone torsion relaxed scan (SD/CG)","title":"PES Scan: SD/CG - MAPLE","trail":["Tasks","PES Scan","SD/CG"],"type":"Task","url":"tasks/scan/scan_sdcg.html#visualization"},{"heading":"When to Use SD/CG Scans","level":2,"page":"tasks/scan/scan_sdcg.html","page_entry":false,"page_role":"content","section_order":5,"text":"Scan points vary strongly in difficulty: The SD phase rapidly reduces large forces without requiring any history, then hands off to CG for efficient final convergence — combining the robustness of SD with the speed of CG. Distorted scans where pure CG starts too aggressively: SD/CG is a robust default that avoids the early oscillations pure CG can show on rough geometries. Well-behaved large scans: L-BFGS may still be faster for routine production grids when starting geometries are already reasonable. Note For production-quality scans, L-BFGS (the default) is generally preferred due to its superior per-point convergence near minima. SD/CG is most useful as a robust scan optimizer for severely distorted structures or when L-BFGS has difficulty converging at certain scan points.","title":"PES Scan: SD/CG - MAPLE","trail":["Tasks","PES Scan","SD/CG"],"type":"Task","url":"tasks/scan/scan_sdcg.html#when-to-use"},{"heading":"Single Point Energy","level":1,"page":"tasks/singlepoint.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#single-point-energy"},{"heading":"Overview","level":2,"page":"tasks/singlepoint.html","page_entry":false,"page_role":"content","section_order":1,"text":"A single point (SP) calculation evaluates a fixed molecular geometry without moving any atoms. MAPLE always reports the parsed coordinates, charge/multiplicity metadata, and electronic energy; verbose=1 adds per-atom gradients. This is the simplest and fastest task type available in MAPLE, making it the foundation upon which more complex workflows are built.","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#overview"},{"heading":"Usage","level":2,"page":"tasks/singlepoint.html","page_entry":false,"page_role":"content","section_order":2,"text":"The single point task is invoked by including the #sp header command in the input file. No method or convergence parameters are used because there is no iterative procedure. #sp Use the optional verbose parameter when you need gradients. MAPLE accepts only verbose=0 and verbose=1 ; verbose=2 is rejected, and the older spelling verbosity is not valid for SP jobs. Tip SP is the default task type. If no job type is specified in the input file (i.e., no #sp , #opt , #freq , etc.), MAPLE will automatically perform a single point energy calculation.","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#usage"},{"heading":"Input Example","level":2,"page":"tasks/singlepoint.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/sp/sp3.inp . It requests verbose=1 so the output includes charge/multiplicity, energy, and gradients. #model=ANI-2x #sp(verbose=1) C 0.65365800 1.02013500 0.25040200 C -0.95129600 -1.02931400 0.57474200 C 1.95888600 -0.93622000 0.00515500 N 0.79077500 -0.14946600 -0.38846900 N -0.42242100 1.80163100 0.01564100 O -1.87211100 -0.71447900 -0.39360600 H -1.49152400 -0.99165700 -1.23718800 H 1.93501500 1.43895500 -0.76274600 H 1.14080200 1.20947000 1.20910000 H -1.06000700 1.56870100 -0.72483100 H -0.64277300 2.56184400 0.62878400 H -1.22475800 -0.59467400 1.53295400 H -0.61313000 -2.06366600 0.60833500 H 1.61854500 -1.95264400 0.20633800 H 2.67877500 -0.97401900 -0.81539800 H 2.47397200 -0.55869000 0.89670300 Run it from the MAPLE source tree with maple examples/sp/sp3.inp . The same example has a D4 variant at examples/sp/sp3_d4.inp .","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#input-example"},{"heading":"Parameters","level":2,"page":"tasks/singlepoint.html","page_entry":false,"page_role":"content","section_order":4,"text":"The single point task accepts the following parameter: Parameter Type Default Description verbose int 0 Output verbosity level. 0 = coordinates, charge/multiplicity, and energy; 1 = verbose=0 output plus gradients. No force-printing verbosity level is exposed.","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#parameters"},{"heading":"Output","level":2,"page":"tasks/singlepoint.html","page_entry":false,"page_role":"content","section_order":5,"text":"The output file from a single point calculation always contains parsed coordinates, charge/multiplicity metadata, and the total energy in Hartree (Eh). Gradients depend on verbose : verbose=0 -- parsed coordinates, charge/multiplicity, and energy. verbose=1 -- verbose=0 output plus per-atom gradients in Hartree/Angstrom. Complete example output from examples/sp/sp3.out : ********************************************************************** * * * M A P L E * * * * MAchine-learning Potential for Landscape Exploration * * * * * * © 2025 University of Pittsburgh. All rights reserved. * * Licensed under CC BY 4.0 for academic use. * * * * Principal Developer: Xujian Wang * * * ********************************************************************** Parsing # commands... Global parameter: model = ANI-2x Task set to 'sp' Parsed configuration: ---------------------------------------- Task: sp model : ani2x verbose : 1 Coordinates ********************************************************************** Group 1 (inline) -------------------- 1 C 0.653658 1.020135 0.250402 2 C -0.951296 -1.029314 0.574742 3 C 1.958886 -0.936220 0.005155 4 N 0.790775 -0.149466 -0.388469 5 N -0.422421 1.801631 0.015641 6 O -1.872111 -0.714479 -0.393606 7 H -1.491524 -0.991657 -1.237188 8 H 1.935015 1.438955 -0.762746 9 H 1.140802 1.209470 1.209100 10 H -1.060007 1.568701 -0.724831 11 H -0.642773 2.561844 0.628784 12 H -1.224758 -0.594674 1.532954 13 H -0.613130 -2.063666 0.608335 14 H 1.618545 -1.952644 0.206338 15 H 2.678775 -0.974019 -0.815398 16 H 2.473972 -0.558690 0.896703 Charge: 0, Multiplicity: 1 Energy: -304.7642932897 Hartree Gradients (Hartree/Angstrom): Gradient = -Force Atom El Gx Gy Gz 1 C -0.10266493 0.02860843 0.11792911 2 C -0.08336351 -0.02371526 0.04541698 3 C 0.03426485 -0.01383988 0.00515845 4 N 0.10547175 0.05071949 -0.09252290 5 N 0.00947110 -0.01377346 0.00264503 6 O 0.02184403 0.00224924 -0.00525583 7 H -0.00991479 -0.00544633 0.00266360 8 H 0.03686071 -0.03305264 -0.05529496 9 H -0.01167883 -0.00082533 -0.01351971 10 H 0.00696653 0.00887080 -0.00033596 11 H 0.00424815 -0.00923034 -0.00473377 12 H -0.00369785 -0.00480554 0.00827175 13 H 0.00377101 0.00490504 -0.00487071 14 H -0.00491144 0.00881686 -0.00243353 15 H -0.00285685 0.00055546 0.00761027 16 H -0.00380990 -0.00003653 -0.01072782 Program started: 2026-05-24 11:56:03 ====================================================================== TIMING SUMMARY ====================================================================== Input Reading....................................... 0.001 s ( 0.2 %) Settings Parsing.................................... 0.000 s ( 16.7 %) Coordinate Section Parsing.......................... 0.000 s ( 22.8 %) Post-Processing Expansion........................... 0.000 s ( 0.3 %) MLP Initialization.................................. 0.119 s ( 25.7 %) Job Dispatching..................................... 0.342 s ( 74.0 %) Single Point Energy Calculation..................... 0.342 s ( 99.8 %) ====================================================================== Total wall time: 0.462 s Total CPU time: 0.729 s ====================================================================== Program ended: 2026-05-24 11:56:03 TOTAL RUN TIME: 0 days 0 hours 0 minutes 0 seconds 462 msec The energy value represents the total electronic energy of the system at the given geometry as predicted by the specified ML potential.","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#output"},{"heading":"Use Cases","level":2,"page":"tasks/singlepoint.html","page_entry":false,"page_role":"content","section_order":6,"text":"Single point calculations are useful in a variety of scenarios: Benchmarking -- comparing energies from different ML models or against reference DFT/ab initio values for the same geometry. Energy comparisons -- evaluating relative energies of conformers, isomers, or reaction intermediates at their respective geometries. Post-optimization checks -- verifying the energy at an optimized geometry using a different or higher-level model than was used during optimization. Gradient analysis -- use verbose=1 to inspect whether a structure is close to a stationary point. Workflow building blocks -- SP calculations serve as the fundamental energy/force evaluation used internally by optimization, frequency, TS search, and other iterative tasks.","title":"Single Point Energy - MAPLE","trail":["Tasks","Single Point"],"type":"Task","url":"tasks/singlepoint.html#use-cases"},{"heading":"Transition State Search","level":1,"page":"tasks/ts/ts.html","page_entry":true,"page_role":"landing","section_order":0,"text":"","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#transition-state-search"},{"heading":"Overview","level":2,"page":"tasks/ts/ts.html","page_entry":false,"page_role":"landing","section_order":1,"text":"A transition state (TS) is a first-order saddle point on the potential energy surface (PES). It is characterized by exactly one imaginary vibrational frequency, corresponding to the reaction coordinate that connects reactant and product basins. Finding accurate TS geometries is essential for computing activation energies, predicting reaction rates, and understanding reaction mechanisms. Unlike local minima, a TS is a maximum along one direction (the reaction coordinate) and a minimum along all remaining degrees of freedom. The unique imaginary mode of the mass-weighted Hessian at the TS defines the direction of bond breaking and bond forming.","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#overview"},{"heading":"Available Methods","level":2,"page":"tasks/ts/ts.html","page_entry":false,"page_role":"landing","section_order":2,"text":"MAPLE provides six transition state search algorithms, each suited to different problem types: Method Keyword Description P-RFO prfo Partitioned Rational Function Optimization. Refines a guess geometry near the TS using trust-region steps that maximize along one Hessian mode while minimizing along all others. NEB neb Nudged Elastic Band. Requires reactant and product structures. Builds a minimum energy path (MEP) using a chain of images connected by spring forces. Dimer dimer Minimum-mode following method. No endpoint structures needed. Uses two images separated by a small distance to estimate and follow the lowest curvature mode. String/GSM string Growing String Method. Adaptive path growth from both endpoints followed by the current String-TS finalization path. DMF dmf Direct MaxFlux. Requires reactant and product structures. Optimizes a B-spline path with a finite-temperature MaxFlux objective and extracts t_max as the TS guess. AutoNEB autoneb Automated multi-step NEB workflow. Recursively subdivides the reaction path to discover all intermediates and transition states in complex multi-step reactions.","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#available-methods"},{"heading":"Choosing a Method","level":2,"page":"tasks/ts/ts.html","page_entry":false,"page_role":"landing","section_order":3,"text":"The best method depends on what information you have and the complexity of the reaction: You have a good TS guess (e.g., from a previous NEB or chemical intuition) → Use P-RFO for fast local refinement. You have both reactant and product structures → Use NEB , String/GSM , or DMF to find the MEP and locate the TS along it. You only have one structure and no product → Use the Dimer method to explore the PES landscape from a single starting point. The reaction has multiple steps or intermediates → Use AutoNEB to automatically discover all stationary points along the pathway. Large systems with many atoms → String/GSM is often more efficient than NEB due to adaptive path growth, while DMF can use a compact B-spline path and an optional torch backend.","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#choosing-a-method"},{"heading":"General Workflow","level":2,"page":"tasks/ts/ts.html","page_entry":false,"page_role":"landing","section_order":4,"text":"A typical transition state search workflow follows these steps: Optimize endpoints. Ensure your reactant and product geometries are properly optimized local minima. Poorly optimized endpoints can cause path-based methods to fail or converge to spurious saddle points. Run the TS search. Choose an appropriate method ( neb , string , dmf , dimer , or prfo ) and run the calculation. For path-based methods, the highest-energy image (HEI) or DMF t_max point provides an initial TS estimate. Refine the TS. For NEB, use refine=cineb or refine=nebts . For String/GSM, use refine=cistring or refine=stringts . For DMF, use refine=prfo or refine=dimer ; other TS methods reject refine . Verify with a frequency calculation. Confirm the TS has exactly one imaginary frequency. If there are zero or more than one imaginary frequencies, the geometry is not a true first-order saddle point. Run IRC. Perform an intrinsic reaction coordinate (IRC) calculation from the TS to confirm that it connects the expected reactant and product.","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#general-workflow"},{"heading":"Refine Options Lookup","level":2,"page":"tasks/ts/ts.html","page_entry":false,"page_role":"landing","section_order":5,"text":"refine is an optional parameter inside the #ts(...) command. It is not a separate header line. Use it only with methods that accept a second refinement stage; omit it when you want the base TS search workflow. # Base NEB path search #ts(method=neb) # NEB path search followed by NEBTS refinement #ts(method=neb,refine=nebts) # String/GSM path search followed by String-TS refinement #ts(method=string,refine=stringts) # DMF path search followed by P-RFO refinement #ts(method=dmf,refine=prfo) # P-RFO, Dimer, and AutoNEB do not accept refine #ts(method=prfo) Use this table to match each accepted refine value with the TS workflow it triggers. Unsupported method/refine combinations are rejected during input parsing. TS Method refine Value Accepted? Workflow Meaning Main Output neb None Yes Run the base NEB path search and extract the highest-energy image. *_mep.xyz , *_hei.xyz neb cineb Yes Run NEB, then climb the highest-energy image with CI-NEB. *_cineb_*.xyz neb nebts Yes Run NEB, refine the path with CI-NEB, then optimize the TS with P-RFO. *_nebts_mep.xyz , *_nebts_ts.xyz string None Yes Run the base String/GSM path search and extract the highest-energy image. *_gsm_mep.xyz , *_gsm_hei.xyz string cistring Yes Accept the CI-String-style refinement setting for the String/GSM workflow. *_gsm_mep.xyz , *_gsm_hei.xyz string stringts Yes Run String/GSM, select the highest-energy image, then optimize the TS with P-RFO. *_stringts_mep.xyz , *_stringts_ts.xyz dmf None Yes Run the base Direct MaxFlux path optimization and extract the highest-energy t_max point. *_dmf_mep.xyz , *_dmf_tmax.xyz dmf prfo Yes Run DMF, then optimize the t_max structure with P-RFO. *_dmf_refine_prfo_ts.xyz dmf dimer Yes Run DMF, then refine the t_max structure with the Dimer method. *_dmf_refine_dimer_ts.xyz prfo , dimer , autoneb Any value No These methods do not accept refine ; run them without a refine keyword. Method-specific TS/search outputs","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#refine-options"},{"heading":"Visualization Gallery","level":2,"page":"tasks/ts/ts.html","page_entry":false,"page_role":"landing","section_order":6,"text":"The gallery below uses the checked-in TS example outputs rendered with MAPLE Visual Lab. Atom indices are hidden in these web-ready figures. Path and search animations on the method pages include energy traces, while single-geometry TS snapshots are shown as structure-only figures. Fig. 1 — Structure-only overview of TS example visualizations. Note TS refinement keywords are method-specific. MAPLE validates them during input parsing: NEB accepts cineb and nebts ; String/GSM accepts cistring and stringts ; DMF accepts prfo and dimer ; P-RFO, Dimer, and AutoNEB do not accept refine .","title":"Transition State Search - MAPLE","trail":["Tasks","Transition State"],"type":"Task","url":"tasks/ts/ts.html#visualization-gallery"},{"heading":"AutoNEB (Automated NEB)","level":1,"page":"tasks/ts/ts_autoneb.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#autoneb-automated-neb"},{"heading":"Overview","level":2,"page":"tasks/ts/ts_autoneb.html","page_entry":false,"page_role":"content","section_order":1,"text":"AutoNEB is an automated multi-step NEB workflow designed for complex reactions that involve multiple intermediates and transition states. Rather than requiring the user to manually identify each elementary step, AutoNEB recursively subdivides the reaction path between a given reactant and product, automatically discovering all stationary points along the way. This method is particularly valuable for multi-step reaction mechanisms where the number and nature of intermediates are not known in advance. AutoNEB handles the entire workflow automatically: running NEB calculations, identifying intermediates, and recursively refining each segment of the path until all transition states and intermediates have been located.","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#overview"},{"heading":"How It Works","level":2,"page":"tasks/ts/ts_autoneb.html","page_entry":false,"page_role":"content","section_order":2,"text":"The AutoNEB algorithm proceeds through the following stages: Initial NEB. A standard NEB calculation is performed between the overall reactant and product structures, producing an initial minimum energy path. Identify highest-energy images. The highest-energy images (HEIs) along the converged path are identified as candidate transition states. Images in local energy minima along the path are identified as candidate intermediates. Optimize intermediates. Candidate intermediate structures are optimized to true local minima using geometry optimization. Recursive subdivision. New NEB calculations are launched between each pair of adjacent stationary points (minima). This process repeats recursively, building a tree of NEB calculations that progressively resolves the full reaction mechanism. Collect results. All transition state and intermediate structures are collected into a unified global MEP. The recursion terminates when no new intermediates are found in any segment, or when the maximum tree depth is reached.","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#how-it-works"},{"heading":"Parameters","level":2,"page":"tasks/ts/ts_autoneb.html","page_entry":false,"page_role":"content","section_order":3,"text":"Parameter Type Default Description n_images int 20 Number of initial NEB images. k_min float 0.03 Minimum spring constant (Eh/Ang²). k_max float 0.3 Maximum spring constant (Eh/Ang²). use_dynamic_k bool True Enable dynamic spring constants. k_decay float 0.5 Dynamic spring constant decay factor. max_iter int 256 Maximum NEB iterations per sub-path. lbfgs_m int 10 L-BFGS memory for band optimization. step0 float 2e-2 Initial L-BFGS step size. ifidpp int 1 IDPP interpolation flag (1=IDPP, 0=linear). ang_max float 0.3 Max distance between adjacent images (Angstrom). ang_iter int 20 Check for image insertion every N iterations. path_iter int 50 Check for local minima every N iterations. min_e_drop float 0.001 Energy drop threshold for minima detection (Eh). ep_iter int 30 Check endpoint updates every N iterations. ep_e_drop float 0.0005 Energy drop for endpoint update (Eh). autoneb_f_max_th float 9.5e-3 Max force convergence threshold. autoneb_f_rms_th float 5e-3 RMS force convergence threshold. max_depth int 5 Maximum recursion depth for path subdivision. max_paths int 10 Maximum number of sub-paths. do_final_refine bool True Perform final global NEB refinement on the merged path. final_refine_factor float 2.0 Multiplier applied to the AutoNEB force thresholds during final refinement; larger values make the final pass looser. final_refine_max_iter int 200 Max iterations for final refinement. final_refine_ep_iter int 20 Endpoint check interval during final refinement. verbose int 1 Output verbosity level.","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/ts/ts_autoneb.html","page_entry":false,"page_role":"content","section_order":4,"text":"Checked-in MAPLE example: examples/ts/autoneb/inp1.inp . The portable form below is for an input file saved in the MAPLE repository root; if you save the input elsewhere, adjust the XYZ paths because relative paths are resolved from the input file location. A larger multi-step aldol example is available under examples/ts/autoneb/aldol/ . #model=aimnet2nse #ts(method=autoneb) #device=gpu0 XYZ 0 1 examples/ts/autoneb/gauopt_opt.xyz XYZ 0 1 examples/ts/autoneb/gauopt2_opt.xyz","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#input-example"},{"heading":"Output Files","level":2,"page":"tasks/ts/ts_autoneb.html","page_entry":false,"page_role":"content","section_order":5,"text":"*_autoneb_global_mep.xyz — The complete global minimum energy path spanning all elementary steps, from the initial reactant through all intermediates to the final product. *_autoneb_intermediates.xyz — Optimized geometries of all intermediate structures discovered during the recursive search. *_autoneb_ts_list.xyz — All transition state geometries found across every segment of the reaction mechanism. *_autoneb_path_*.xyz — Individual MEP files for each NEB segment in the recursive tree (numbered sequentially). *_autoneb_tree.json — JSON file describing the recursion tree structure, including parent-child relationships between NEB segments, energies, and convergence status.","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#output-files"},{"heading":"Visualization","level":2,"page":"tasks/ts/ts_autoneb.html","page_entry":false,"page_role":"content","section_order":6,"text":"The AutoNEB visualizations summarize the global path from *_autoneb_global_mep.xyz and the collected saddle candidates from *_autoneb_ts_list.xyz . Fig. 1 — AutoNEB global path with energy trace. Fig. 2 — AutoNEB collected TS list with energy trace. Tip AutoNEB is ideal for reactions with multiple intermediates, such as enzyme mechanisms, catalytic cycles, or multi-step organic transformations. If you suspect your reaction has more than one elementary step, AutoNEB can discover the full mechanism automatically without requiring you to guess the intermediates. Warning AutoNEB can be computationally expensive for deep reaction networks. Each level of recursion spawns additional NEB calculations, and the total cost grows with the number of elementary steps discovered. For very complex mechanisms, consider limiting max_depth or using a smaller n_images value for the initial exploration, then tightening selected segments in separate follow-up calculations.","title":"AutoNEB (Automated NEB) - MAPLE","trail":["Tasks","Transition State","AutoNEB"],"type":"Task","url":"tasks/ts/ts_autoneb.html#visualization"},{"heading":"Dimer Method","level":1,"page":"tasks/ts/ts_dimmer.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#dimer-method"},{"heading":"Overview","level":2,"page":"tasks/ts/ts_dimmer.html","page_entry":false,"page_role":"content","section_order":1,"text":"The Dimer method is a minimum-mode following algorithm for locating first-order saddle points on the potential energy surface. Unlike path-based methods such as NEB or String, the Dimer method requires only a single starting structure and does not need knowledge of the product geometry. The method works by rotating a trial direction toward the lowest curvature mode of the PES, then translating the structure along that mode. The current runtime uses calculator Hessian-vector products through get_hvp() for this rotation/translation loop, so Dimer requires a model backend that exposes that capability. Among shipped MAPLE backends, this currently means ANI in gas phase.","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/ts/ts_dimmer.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description use_hvp bool False Compatibility flag. The current Dimer execution path requires calculator get_hvp() support regardless of this setting; shipped support is ANI gas phase only. delta float 0.005 Legacy finite-difference displacement. It is not used by the current get_hvp() -based execution path. rot_max_iter int 5 Maximum rotation iterations per translation step. rot_alpha float 0.5 Rotation step scaling factor. rot_f_max_th float 1.0e-3 Max force threshold for rotation convergence. rot_f_rms_th float 5.0e-4 RMS force threshold for rotation convergence. step0 float 0.2 Initial translation step size. step_max float 0.15 Maximum translation step size. trust_radius float 0.15 Trust radius for translation. f_max_th float 5.0e-3 Max force convergence threshold for overall dimer. f_rms_th float 1.0e-3 RMS force convergence threshold. kappa_to_flip float 0.0 Curvature threshold for mode flipping. max_iter int 200 Maximum dimer translation iterations. use_mass_weight bool False Use mass-weighted coordinates. remove_rigid bool True Remove rigid body translations and rotations. n_init str \"random\" Initial dimer direction: \"random\", \"force\", or \"given\". n_given ndarray None User-supplied initial dimer direction vector. save_traj bool True Save trajectory of dimer steps. save_metrics bool True Save convergence metrics to output.","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/ts/ts_dimmer.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/ts/dimer/inp1.inp . Dimer is single-ended, so the input is one starting geometry rather than reactant/product endpoints. #model=ANI-1xnr #ts(method=dimer) #device=gpu0 C 0.8773307780 0.7831579390 -0.1629806432 H 0.6909163982 1.5540583811 -0.9219751886 O 0.5296065367 0.9762287325 1.1234790578 C 1.3488671845 -0.5563869274 -0.1923254310 H 0.7828987178 -0.2429788233 1.0663324170 H 1.0764966981 -1.2943318365 -0.9583627957 H 2.2951253096 -0.7293808119 0.3397718379 Important Dimer is single-ended, but it is not model-agnostic: the active calculator must implement get_hvp() . If a selected model does not provide Hessian-vector products, choose P-RFO/NEB/String instead or switch to ANI gas phase.","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#input-example"},{"heading":"Output","level":2,"page":"tasks/ts/ts_dimmer.html","page_entry":false,"page_role":"content","section_order":4,"text":"*_dimer_ts.xyz — The final converged transition state geometry. *_dimer_traj.xyz — Multi-frame XYZ trajectory file containing all intermediate structures generated during the search from the initial guess to the saddle point.","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#output"},{"heading":"Visualization","level":2,"page":"tasks/ts/ts_dimmer.html","page_entry":false,"page_role":"content","section_order":5,"text":"The Dimer trajectory visualization uses *_dimer_traj.xyz , while the final TS panel uses *_dimer_ts.xyz . Because Dimer is single-ended, the trajectory shows the search process rather than a reactant-to-product MEP. Fig. 1 — Dimer single-ended TS search trajectory with energy trace. Fig. 2 — Dimer final TS geometry.","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#visualization"},{"heading":"When to Use","level":2,"page":"tasks/ts/ts_dimmer.html","page_entry":false,"page_role":"content","section_order":6,"text":"The Dimer method is the right choice when: The product is unknown. You want to explore what reactions are possible from a given structure without knowing the endpoint geometry in advance. Exploring the PES landscape. You want to systematically discover nearby saddle points from a minimum, for example to enumerate possible decomposition pathways or rearrangement channels. Single-ended search is preferred. You have a reasonable guess for the TS geometry (e.g., from chemical intuition or a constrained scan) but do not have a product structure to use with NEB or String. The reaction path is not well-defined. When the reaction involves complex conformational changes where defining a clear product is difficult, the Dimer method can find the nearest saddle point without requiring path construction.","title":"Dimer Method - MAPLE","trail":["Tasks","Transition State","Dimer"],"type":"Task","url":"tasks/ts/ts_dimmer.html#when-to-use"},{"heading":"Direct MaxFlux (DMF)","level":1,"page":"tasks/ts/ts_dmf.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#direct-maxflux-dmf"},{"heading":"Overview","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":1,"text":"Direct MaxFlux (DMF) is a double-ended transition-state search method for reactions with known reactant and product structures. It is based on the variational MaxFlux formulation of Koda and Saito, where the reaction path is optimized by minimizing a finite-temperature line integral of exp(beta E) . In the large- beta limit this objective approaches a smooth minimax search for the lowest possible path maximum, so the optimized path approaches the MEP and its highest-energy point approaches the TS. MAPLE represents the DMF path as a B-spline curve, builds an initial path with FB-ENM by default, evaluates energies and forces through the selected MAPLE calculator, and can optionally hand the t_max structure to P-RFO or Dimer refinement. Note DMF depends on cyipopt for nonlinear constrained optimization. Install it before running #ts(method=dmf) , for example with conda install -c conda-forge cyipopt .","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#overview"},{"heading":"How It Works","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":2,"text":"Endpoint preparation. DMF starts from reactant and product structures, and can also accept an explicit multi-frame path. Initial path generation. If coefs is not provided, init_path=fbenm builds FB-ENM/CFB-ENM B-spline control points. Use init_path=linear for a lighter linear B-spline initialization. MaxFlux path optimization. IPOPT optimizes the B-spline path variables subject to endpoint constraints. The objective favors high reactive flux across the barrier region rather than spring-balanced image spacing. TS guess selection. MAPLE evaluates the optimized path and writes the highest-energy point as t_max . Optional refinement. With refine=prfo or refine=dimer , MAPLE starts the chosen single-ended TS optimizer from the DMF t_max structure.","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#how-it-works"},{"heading":"Parameters","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":3,"text":"Parameter Type Default Description backend str numpy Tensor backend for DMF path algebra: numpy or torch . The torch backend inherits the calculator device when available. beta float 10.0 Reciprocal temperature used by the MaxFlux objective, in 1/eV . nmove int 10 Number of movable energy-evaluation points along the B-spline path. nsegs int 6 Number of B-spline path segments. Increase together with nmove when the reaction path needs more flexibility. dspl int 3 B-spline polynomial degree. update_teval bool False Adaptively update evaluation points toward the barrier. Keep false for more uniform output spacing. coefs object None Explicit initial B-spline control points, or a .npy file containing them. Shape must be (nsegs + dspl, natoms, 3) . When set, DMF skips FB-ENM and linear path generation. t_eval object None Energy-evaluation grid as a sequence, CSV string, .npy , or .txt file. Custom grids must be one-dimensional, strictly increasing, start at 0, end at 1, and have length nmove + 2 . w_eval object None Quadrature weights matching t_eval . Custom weights require update_teval=false . init_path str fbenm Initial path builder: fbenm or linear . fbenm_correlated bool True Use correlated FB-ENM geometry processing when generating the initial path. mass_weighted bool False Use a mass-weighted velocity norm in the path objective. remove_rotation_and_translation bool True Project global translation and rotation out of the path velocity norm. tol str or float tight IPOPT convergence preset: tight , middle , loose , or an explicit numeric tolerance. max_iter int 200 Maximum IPOPT iterations for the Direct MaxFlux optimization. ipopt_out bool False Write native IPOPT output files for the FB-ENM and final DMF nonlinear optimizations. refine str None Optional local TS refinement from t_max : prfo or dimer .","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":4,"text":"Checked-in MAPLE example: examples/ts/dmf/inp3.inp . The portable form below is for an input file saved in examples/ts/dmf ; if you save it elsewhere, adjust the XYZ paths because relative paths are resolved from the input file location. #model=fennix-bio1m #ts(method=dmf,refine=prfo) #device=gpu0 XYZ react.xyz XYZ prod.xyz For larger systems, the tensor backend can be switched while keeping the calculator/device selection in the usual MAPLE input layer: #ts(method=dmf,backend=torch,refine=prfo,nmove=14,nsegs=8)","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#input-example"},{"heading":"Output Files","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":5,"text":"*_dmf_mep.xyz or *_dmf_mep.pdb : Optimized DMF path written as the MEP/MaxFlux path estimate. *_dmf_tmax.xyz or *_dmf_tmax.pdb : Highest-energy point on the optimized DMF path, used as the TS guess. *_dmf_tmax_traj.xyz or *_dmf_tmax_traj.pdb : History of the t_max structure during DMF optimization. *_dmf_refine_prfo_ts.xyz and *_dmf_refine_prfo_traj.xyz : P-RFO refinement outputs when refine=prfo . *_dmf_refine_dimer_ts.xyz and *_dmf_refine_dimer_traj.xyz : Dimer refinement outputs when refine=dimer . *_dmf_ipopt.out and *_dmf_fbenm_ipopt.out : Native IPOPT logs when ipopt_out=true .","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#output-files"},{"heading":"Refinement","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":6,"text":"DMF itself does not use Hessians. It produces a path-based t_max TS guess, then delegates optional local refinement to the requested single-ended TS method. Use refine=prfo when a local Hessian-based saddle optimizer is appropriate, or refine=dimer when you prefer minimum-mode following from the DMF guess.","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#refinement"},{"heading":"Comparison with NEB and String/GSM","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":7,"text":"NEB, String/GSM, and DMF are all double-ended path methods, but they pose the path problem differently. NEB and String/GSM are direct MEP construction methods based on projected forces or string reparameterization. DMF is a variational MaxFlux optimization: it minimizes a scalar path functional that becomes a smooth approximation to the path minimax problem as beta increases. Aspect NEB String/GSM DMF Core formulation Projected force balance on a chain of images with spring forces along the tangent. String evolution with node redistribution or growth between fixed endpoints. Variational minimization of a MaxFlux line integral, log integral exp(beta E) ds . Path representation Discrete images connected by springs. Discrete string nodes grown or reparameterized along the path. Continuous B-spline path with optimized control points and separate energy-evaluation points. MEP and TS relation Converges toward the MEP; the HEI or CI image gives the TS estimate. Converges toward a reparameterized MEP; the HEI is used for String-TS finalization. Approaches the MEP/TS in the beta -> infinity limit; finite beta gives a practical t_max TS guess. Energy derivatives Uses forces at images; CI-NEB still does not require Hessians. Uses forces at string nodes and local relaxation steps. The objective contains energies only; its analytic gradient uses forces, not Hessians.","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#comparison-with-neb-and-string"},{"heading":"Practical Guidance","level":2,"page":"tasks/ts/ts_dmf.html","page_entry":false,"page_role":"content","section_order":8,"text":"Optimize reactant and product endpoints before running DMF, just as with NEB and String/GSM. Increase nmove for more energy-evaluation points, and increase nsegs when the B-spline path itself needs more geometric flexibility. Keep update_teval=false when you want the written path frames to remain visually smooth and evenly distributed. Use backend=torch when the torch backend is available and path/geometry tensor operations dominate the overhead; energy and force calls still go through the selected MAPLE calculator. Use ipopt_out=true only when you need native IPOPT diagnostics.","title":"Direct MaxFlux (DMF) - MAPLE","trail":["Tasks","Transition State","DMF"],"type":"Task","url":"tasks/ts/ts_dmf.html#practical-guidance"},{"heading":"Nudged Elastic Band (NEB)","level":1,"page":"tasks/ts/ts_neb.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#nudged-elastic-band-neb"},{"heading":"Overview","level":2,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":1,"text":"The Nudged Elastic Band (NEB) method is a chain-of-states approach for finding the minimum energy path (MEP) between a known reactant and product. A series of intermediate images are connected by spring forces and optimized simultaneously. The \"nudging\" procedure projects out the perpendicular component of the spring force and the parallel component of the true force, ensuring that the images converge to the MEP rather than sliding down to the endpoints. MAPLE's NEB implementation uses Image Dependent Pair Potential (IDPP) interpolation to generate a physically reasonable initial path, dynamic spring constants to improve image distribution near the transition state, and an L-BFGS optimizer for efficient band relaxation.","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description n_images int 10 Number of internal images along the path (excluding fixed endpoints). k_min float 0.03 Minimum spring constant (Eh/Ang²). k_max float 0.3 Maximum spring constant (Eh/Ang²). use_dynamic_k bool True Enable energy-weighted dynamic spring constants. k_decay float 0.5 Decay factor for dynamic spring constant weighting. max_iter int 500 Maximum L-BFGS optimization iterations for the NEB band. lbfgs_m int 20 L-BFGS memory for the NEB optimizer. step0 float 2e-2 Initial step length for the L-BFGS optimizer. ifidpp int 1 IDPP interpolation flag (1=IDPP, 0=linear). neb_f_max_th float 9.5e-3 Max force convergence threshold for NEB. neb_f_rms_th float 5e-3 RMS force convergence threshold for NEB. initial_opt bool False Optimize endpoints before building the NEB path. refine str None Post-NEB refinement: None, \"cineb\", or \"nebts\". cineb_f_max_th float 1e-2 Max force threshold for CI-NEB refinement. cineb_f_rms_th float 1e-2 RMS force threshold for CI-NEB refinement. cistep0 float 5e-3 Initial step for CI-NEB optimizer.","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#parameters"},{"heading":"Refinement Options","level":2,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":3,"text":"","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#refinement-options"},{"heading":"CI-NEB (Climbing Image NEB)","level":3,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":4,"text":"When refine=cineb is set, the highest-energy image (HEI) is freed from spring forces and instead climbs along the band tangent toward the true saddle point. The remaining images continue to be optimized with springs. This gives a more accurate TS estimate without requiring a separate local TS optimizer.","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#ci-neb-climbing-image-neb"},{"heading":"NEBTS (NEB + TS Refinement)","level":3,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":5,"text":"When refine=nebts is set, MAPLE first performs CI-NEB to refine the HEI, then applies a P-RFO local TS optimizer starting from the climbing image. NEB only accepts refine=cineb and refine=nebts ; other refine values fail during input parsing.","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#nebts-neb-ts-refinement"},{"heading":"Input Example","level":2,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":6,"text":"Checked-in MAPLE example: examples/ts/neb/inp1.inp . The portable form below is for an input file saved in the MAPLE repository root; if you save the input elsewhere, adjust the XYZ paths because relative paths are resolved from the input file location. If you copy the checked-in file verbatim, update its absolute XYZ paths to your local checkout. #model=ANI-1xnr #ts(method=neb,refine=nebts) #device=gpu0 XYZ examples/ts/neb/react.xyz XYZ examples/ts/neb/prod.xyz","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#input-example"},{"heading":"Output Files","level":2,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":7,"text":"*_mep.xyz — Multi-frame XYZ file containing all images along the converged minimum energy path. *_hei.xyz — The highest-energy image extracted from the converged NEB band. *_cineb_*.xyz — Climbing-image NEB trajectory and converged path (when refine=cineb or refine=nebts ). *_nebts_mep.xyz — Multi-frame MEP after NEBTS refinement. *_nebts_ts.xyz — Final optimized TS geometry from P-RFO refinement (when refine=nebts ).","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#output-files"},{"heading":"Visualization","level":2,"page":"tasks/ts/ts_neb.html","page_entry":false,"page_role":"content","section_order":8,"text":"The NEBTS visualization uses the refined *_nebts_mep.xyz path and *_nebts_ts.xyz final TS output from the checked-in example. Fig. 1 — NEBTS minimum energy path with energy trace. Fig. 2 — NEBTS final refined TS geometry. Important Always ensure your reactant and product endpoint geometries are properly optimized before running NEB. Poorly optimized endpoints introduce artificial forces into the band and can prevent convergence or lead to incorrect MEPs. Use initial_opt=true or run separate optimization calculations beforehand.","title":"Nudged Elastic Band (NEB) - MAPLE","trail":["Tasks","Transition State","NEB"],"type":"Task","url":"tasks/ts/ts_neb.html#visualization"},{"heading":"P-RFO (Partitioned Rational Function Optimization)","level":1,"page":"tasks/ts/ts_prfo.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#p-rfo-partitioned-rational-function-optimization"},{"heading":"Overview","level":2,"page":"tasks/ts/ts_prfo.html","page_entry":false,"page_role":"content","section_order":1,"text":"P-RFO is a second-order saddle point optimizer based on the Partitioned Rational Function Optimization algorithm. It works by partitioning the Hessian eigenspace into one mode to maximize along (the reaction coordinate) and all remaining modes to minimize along. This dual-shift approach, combined with a trust-region framework and mode-following in mass-weighted coordinates, efficiently converges to the nearest first-order saddle point from an initial guess geometry. By default, MAPLE recalculates the exact Hessian at every P-RFO iteration. For larger systems, recalc can be used to recompute the Hessian periodically while updating the working Hessian between recalculations with either the Bofill or BFGS update formula. The default update method is bofill . P-RFO is the local TS optimizer used directly with #ts(method=prfo) and as the final optimization step for NEB-TS/String-TS refinement workflows. It requires a good starting geometry that is already close to the true TS.","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/ts/ts_prfo.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description max_iter int 256 Maximum number of optimization cycles. trust_radius float 0.2 Initial trust radius in Angstrom. trust_min float 1e-3 Minimum trust radius. trust_max float 1.0 Maximum trust radius. eta_shrink float 0.75 Trust radius shrink factor when step is poor. eta_expand float 1.75 Trust radius expansion factor when step is good. evals_eps float 1e-10 Eigenvalue epsilon for numerical stability. mu_margin float 1e-8 Margin for the level-shift parameter. max_bisect_it int 60 Maximum bisection iterations for level-shift. recalc int 1 Exact Hessian recalculation interval. 1 recalculates the Hessian every iteration. hessian_update string bofill Approximate Hessian update used between recalculations. Available options are bofill and bfgs . f_max_th float 9.5e-3 Max force convergence threshold (Hartree/Angstrom). f_rms_th float 5e-3 RMS force convergence threshold. dp_max_th float 1.8e-3 Max displacement convergence threshold (Angstrom). dp_rms_th float 1.2e-3 RMS displacement convergence threshold.","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/ts/ts_prfo.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/ts/prfo/inp1.inp . It uses an inline TS guess geometry and writes inp1_prfo_ts.xyz plus inp1_prfo_traj.xyz . #model=ANI-1xnr #ts(method=prfo) #device=gpu0 C -0.8675 -1.1212 0.1451 C 1.2063 0.0888 0.0375 C -0.8012 1.8039 0.7777 C 1.9270 -0.5238 1.2299 C 2.1735 0.5194 -1.0520 N 0.2436 -0.9006 -0.5570 N -2.0080 -1.5937 -0.4191 O -1.6073 1.4743 -0.2757 H -1.9698 0.5875 -0.1411 H 0.0290 -0.6370 -1.5287 H -0.8978 -0.8021 1.1842 H 0.5985 0.9809 0.3930 H -2.6675 -1.9721 0.2647 H -1.8829 -2.2545 -1.1927 H -0.4288 2.8210 0.7145 H -1.0181 1.4392 1.7832 H 2.6046 0.2089 1.6809 H 1.6503 1.0084 -1.8818 H 2.5096 -1.3982 0.9217 H 1.2101 -0.8363 1.9937 H 2.9111 1.2261 -0.6587 H 2.7050 -0.3554 -1.4408","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#input-example"},{"heading":"Output Files","level":2,"page":"tasks/ts/ts_prfo.html","page_entry":false,"page_role":"content","section_order":4,"text":"*_prfo_ts.xyz — Final optimized TS geometry. *_prfo_traj.xyz — Multi-frame trajectory of the local saddle-point search.","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#output-files"},{"heading":"Visualization","level":2,"page":"tasks/ts/ts_prfo.html","page_entry":false,"page_role":"content","section_order":5,"text":"The P-RFO trajectory visualization uses *_prfo_traj.xyz , while the final TS panel uses *_prfo_ts.xyz . The trajectory is the local saddle-point search history, not a full reaction path. Fig. 1 — P-RFO local TS search trajectory with energy trace. Fig. 2 — P-RFO final optimized TS geometry.","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#visualization"},{"heading":"Tips","level":2,"page":"tasks/ts/ts_prfo.html","page_entry":false,"page_role":"content","section_order":6,"text":"Start from a good guess. The best starting geometry is typically the highest-energy image (HEI) from a converged NEB or String calculation. You can extract this from the *_hei.xyz output file. Verify with a frequency calculation. After P-RFO converges, always run a frequency calculation to confirm exactly one imaginary frequency. If there are multiple imaginary frequencies, the converged structure may be a higher-order saddle point. Use method-specific refinement keywords for automation. Set refine=nebts for NEB workflows, refine=stringts for String/GSM workflows, or refine=prfo for DMF workflows when you want the path calculation to hand its saddle-point guess to the local TS refinement stage. Trust radius adjustment. If P-RFO oscillates or fails to converge, consider providing a geometry closer to the true TS. The trust-region mechanism will automatically adapt the step size, but a poor initial guess can cause the search to wander.","title":"P-RFO (Partitioned Rational Function Optimization) - MAPLE","trail":["Tasks","Transition State","P-RFO"],"type":"Task","url":"tasks/ts/ts_prfo.html#tips"},{"heading":"Growing String Method (GSM)","level":1,"page":"tasks/ts/ts_string.html","page_entry":true,"page_role":"content","section_order":0,"text":"","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#growing-string-method-gsm"},{"heading":"Overview","level":2,"page":"tasks/ts/ts_string.html","page_entry":false,"page_role":"content","section_order":1,"text":"The Growing String Method (GSM) is an adaptive path-based algorithm for finding minimum energy paths and transition states between a given reactant and product. Unlike NEB, which creates all images at once, GSM grows the path incrementally from both endpoints, adding new nodes only where needed. This adaptive growth strategy can be significantly more efficient than NEB for large molecular systems. MAPLE's GSM implementation features Kabsch alignment of endpoints, two-ended adaptive growth with constrained mini-relaxation in the hyperplane orthogonal to the local path direction, energy-weighted tangents, and a dynamic growth policy including side pausing and forced connector pulls. In the current runtime, the equal-arc GSM path is finalized by taking the highest-energy image into the String-TS/P-RFO output path.","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#overview"},{"heading":"Parameters","level":2,"page":"tasks/ts/ts_string.html","page_entry":false,"page_role":"content","section_order":2,"text":"Parameter Type Default Description grow_step float 0.12 Step size for growing new nodes (Angstrom). grow_step_min float 0.02 Minimum growing step size. grow_backtrack float 0.5 Backtracking factor during growth. grow_relax_iters int 10 Relaxation iterations after each growth step. grow_relax_tol float 2.5e-3 Force tolerance for growth relaxation. grow_energy_tol float 1.0e-3 Energy tolerance for growth relaxation (Eh). pause_imbalance int 2 Pause growth from one end if it leads the other by this many nodes. refine_end_every int 3 Re-optimize endpoint images every N growth steps. merge_threshold float 0.5 Distance threshold for merging approaching fronts (Angstrom). n_images int 9 Target number of string images. max_iter_relax int 300 Maximum iterations for full string relaxation. string_f_max_th float 5.0e-3 Max force convergence threshold for string. string_f_rms_th float 1.0e-3 RMS force convergence threshold for string. lbfgs_memory int 7 L-BFGS memory for string relaxation. lbfgs_curvature float 70.0 L-BFGS initial curvature estimate. lbfgs_max_step float 0.2 L-BFGS maximum step. reparam_every int 3 Reparametrize string every N iterations. refine str None Accepted explicit refinement values: \"cistring\" or \"stringts\". Other values, including NEB-only refine keywords, are rejected during input parsing. cistring_f_max_th float 4.0e-3 Compatibility threshold for CI-String-style refinement settings; current String-TS output follows the HEI-to-P-RFO finalization path. cistring_f_rms_th float 2.0e-3 Compatibility threshold for CI-String-style refinement settings; current String-TS output follows the HEI-to-P-RFO finalization path. max_iter_grow int 100 Maximum iterations for the growing phase. log_every int 1 Log progress every N iterations. guide_conn_min float 0.3 Minimum connectivity for geodesic guiding. guide_d_switch float 4.0 Distance switch for geodesic guidance. guide_inc_trigger int 2 Trigger for increasing guidance strength.","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#parameters"},{"heading":"Input Example","level":2,"page":"tasks/ts/ts_string.html","page_entry":false,"page_role":"content","section_order":3,"text":"Checked-in MAPLE example: examples/ts/string/inp1.inp . It uses the same reactant/product endpoint files as the NEB example. The portable form below is for an input file saved in the MAPLE repository root; if you save the input elsewhere, adjust the XYZ paths because relative paths are resolved from the input file location. #model=ANI-1xnr #ts(method=string,refine=stringts) #device=gpu0 XYZ examples/ts/neb/react.xyz XYZ examples/ts/neb/prod.xyz","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#input-example"},{"heading":"Output","level":2,"page":"tasks/ts/ts_string.html","page_entry":false,"page_role":"content","section_order":4,"text":"The current runtime writes the String/GSM path and then the String-TS finalization files from the highest-energy image. *_gsm_grow_final.xyz — The final path after the growth phase is complete, before reparameterization. *_gsm_mep.xyz — The reparameterized minimum energy path with equally spaced images. *_gsm_hei.xyz — The highest-energy image selected from the reparameterized string. *_stringts_mep.xyz — The path with the refined TS inserted after the selected HEI. *_stringts_ts.xyz — The final optimized TS geometry obtained from P-RFO refinement of the highest-energy image along the string.","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#output"},{"heading":"Visualization","level":2,"page":"tasks/ts/ts_string.html","page_entry":false,"page_role":"content","section_order":5,"text":"The String-TS visualization uses *_stringts_mep.xyz for the path and *_stringts_ts.xyz for the refined TS geometry. Fig. 1 — String-TS path with energy trace. Fig. 2 — String-TS final refined TS geometry.","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#visualization"},{"heading":"Comparison with NEB","level":2,"page":"tasks/ts/ts_string.html","page_entry":false,"page_role":"content","section_order":6,"text":"Both GSM and NEB are path-based methods that require reactant and product endpoints. The key differences are: Aspect NEB String/GSM Path construction All images created at once via interpolation Images grown adaptively from both ends Computational cost All images evaluated at every iteration Only frontier images evaluated during growth Large systems Can be expensive due to many simultaneous images More efficient; fewer evaluations needed during growth Path resolution Uniform resolution along entire path Adaptive resolution; concentrates images where needed Robustness Well-established; generally robust Can stall for very large structural differences For small to medium systems with modest structural changes, NEB and GSM typically perform comparably. For large systems (hundreds of atoms) or reactions with large geometric rearrangements, GSM's adaptive growth can provide significant computational savings.","title":"Growing String Method (GSM) - MAPLE","trail":["Tasks","Transition State","String/GSM"],"type":"Task","url":"tasks/ts/ts_string.html#comparison-with-neb"},{"heading":"Input & Output","level":1,"page":"tutorials/input_output.html","page_entry":true,"page_role":"content","section_order":0,"text":"MAPLE input files ( .inp ) follow a simple, human-readable format. This guide covers the complete input file structure, all available header commands, coordinate formats, and the output files produced by each job type.","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#input-output"},{"heading":"Input File Structure","level":2,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":1,"text":"A MAPLE input file consists of two main sections, processed in order: Header commands -- Lines beginning with # that define the calculation type, model, device, and global options. Coordinates -- Atomic coordinates provided inline or referenced from an external file. Here is an example input file showing both sections, adapted from the checked-in Dimer TS example examples/ts/dimer/inp1.inp : #model=ANI-1xnr #ts(method=dimer) #device=gpu0 C 0.8773307780 0.7831579390 -0.1629806432 H 0.6909163982 1.5540583811 -0.9219751886 O 0.5296065367 0.9762287325 1.1234790578 C 1.3488671845 -0.5563869274 -0.1923254310 H 0.7828987178 -0.2429788233 1.0663324170 H 1.0764966981 -1.2943318365 -0.9583627957 H 2.2951253096 -0.7293808119 0.3397718379","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#input-file-structure"},{"heading":"Header Commands","level":2,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":2,"text":"All header commands start with the # symbol. They are parsed first to determine the task type and global settings. Command Description Example #model Select the ML potential model #model=ani2x #sp Run a single point energy calculation; use verbose=1 for gradients #sp(verbose=1) #opt Run a geometry optimization #opt(method=lbfgs) #ts Run a transition state search; the method value is required #ts(method=prfo) #freq Compute vibrational frequencies #freq #irc Run an intrinsic reaction coordinate calculation #irc(method=gs) #scan Perform a potential energy surface scan; relaxed mode supports lbfgs , rfo , sd , cg , and sdcg #scan(method=rfo, mode=relaxed) #device Set the compute device #device=gpu0 Note If no task command ( #opt , #ts , etc.) is specified, MAPLE automatically performs a single-point energy calculation using default settings.","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#header-commands"},{"heading":"Task Parameters","level":3,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":3,"text":"Task commands accept optional parameters in parentheses. Geometry optimization can use defaults, but TS jobs require an explicit method , and SP uses verbose rather than verbosity : # Single point with gradients #sp(verbose=1) # Optimization using defaults (equivalent to #opt(method=lbfgs)) #opt # Transition state search with an explicit method #ts(method=prfo)","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#task-parameters"},{"heading":"Supported Models","level":2,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":4,"text":"MAPLE supports the following machine learning potential models, specified via the #model header command: ani2x ani1x ani1ccx ani1xnr maceoff23s maceoff23m maceoff23l egret aimnet2 uma maceomol aimnet2nse","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#supported-models"},{"heading":"Convergence Levels","level":2,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":5,"text":"MAPLE provides six predefined convergence levels for iterative tasks such as geometry optimizations and transition state searches. Set the level inside the task command parentheses: #opt(method=lbfgs, level=tight) #ts(method=prfo, level=extratight) The available levels, from tightest to loosest, are: extratight tight medium (default) loose extraloose superloose See the Settings page for the exact numerical thresholds of each level.","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#convergence-levels"},{"heading":"Coordinate Formats","level":2,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":6,"text":"MAPLE supports two ways to specify molecular coordinates.","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#coordinate-formats"},{"heading":"Inline Coordinates","level":3,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":7,"text":"The most common method. Specify atom symbol and Cartesian coordinates (in Angstroms) directly in the input file, one atom per line: #model=ani2x C 0.000000 0.000000 0.000000 H 0.629118 0.629118 0.629118 H -0.629118 -0.629118 0.629118 H -0.629118 0.629118 -0.629118 H 0.629118 -0.629118 -0.629118","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#inline-coordinates"},{"heading":"External XYZ File","level":3,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":8,"text":"Reference an external .xyz file containing the coordinates. The XYZ file follows the standard format (atom count on line 1, comment on line 2, coordinates from line 3): #model=ani2x #opt XYZ methane.xyz Where methane.xyz contains: 5 Methane molecule C 0.000000 0.000000 0.000000 H 0.629118 0.629118 0.629118 H -0.629118 -0.629118 0.629118 H -0.629118 0.629118 -0.629118 H 0.629118 -0.629118 -0.629118","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#external-xyz-file"},{"heading":"Dual XYZ for NEB","level":3,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":9,"text":"For methods that require two endpoint structures (e.g., NEB), provide two XYZ references for the reactant and product geometries. Relative XYZ paths are resolved from the input file location; the example below assumes the input file is saved in the MAPLE repository root. #model=ANI-1xnr #ts(method=neb,refine=nebts) XYZ examples/ts/neb/react.xyz XYZ examples/ts/neb/prod.xyz","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#dual-xyz-for-neb"},{"heading":"Output Files","level":2,"page":"tutorials/input_output.html","page_entry":false,"page_role":"content","section_order":10,"text":"MAPLE generates output files whose names and contents depend on the job type. The following table summarizes the primary output files: Job Type Output File Contents Single Point *.out Parsed coordinates, charge/multiplicity, and electronic energy (Eh); gradients with verbose=1 Optimization *_opt.xyz Optimized geometry in XYZ format Optimization *_opt_traj.xyz Full optimization trajectory Frequency *_freq.out Vibrational frequencies, IR intensities, thermochemistry Transition State Method-specific XYZ files Examples include *_prfo_ts.xyz , *_dimer_ts.xyz , *_nebts_ts.xyz , *_stringts_ts.xyz , and MEP/path files for path methods IRC *_irc_forward.xyz Forward IRC path geometries IRC *_irc_reverse.xyz Reverse IRC path geometries PES Scan *_scan_final.xyz Multi-frame geometries for every scan point PES Scan *.out Main scan log with progress, energies, coordinates, and optimizer diagnostics when applicable In the table above, * represents the input file name without the .inp extension. For example, a NEBTS job named inp1.inp writes files such as inp1_nebts_ts.xyz and inp1_nebts_mep.xyz . Important All energies are reported in Hartree (Eh) and all coordinates in Angstroms. Energy differences in iterative output are shown in kcal/mol for convenience.","title":"Input & Output - MAPLE","trail":["Getting Started","Input & Output"],"type":"Tutorial","url":"tutorials/input_output.html#output-files"},{"heading":"Installation Guide","level":1,"page":"tutorials/installation.html","page_entry":true,"page_role":"content","section_order":0,"text":"This guide walks you through installing MAPLE and its dependencies on your system. MAPLE supports Linux and macOS, with optional GPU acceleration via CUDA.","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#installation-guide"},{"heading":"Requirements","level":2,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":1,"text":"Before installing MAPLE, ensure your system meets the following minimum requirements: Requirement Details Python >= 3.10 GPU CUDA-capable GPU recommended (NVIDIA) RAM 4 GB+ (8 GB+ recommended for large systems) Disk Space ~2 GB for MAPLE and model files OS Linux or macOS Tip: GPU Acceleration While MAPLE runs on CPU, a CUDA-capable GPU significantly speeds up ML potential evaluations. If you have an NVIDIA GPU, install PyTorch with CUDA support (see below) for the best performance.","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#requirements"},{"heading":"Install MAPLE","level":2,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":2,"text":"Clone the MAPLE repository and install it in development mode: # Clone the repository git clone https://github.com/ClickFF/MAPLE.git cd MAPLE # Install in editable/development mode pip install -e . This installs MAPLE as a Python package and makes the maple command available in your terminal. The -e flag enables editable mode, so any changes to the source code take effect immediately without reinstalling. For users in China Follow the same installation order above. If PyPI downloads are slow, append the Tsinghua mirror option to the editable install command: # From the MAPLE repository root pip install -e . -i https://pypi.tuna.tsinghua.edu.cn/simple The same -i https://pypi.tuna.tsinghua.edu.cn/simple option can also be appended to later PyPI-based pip install commands on this page, such as the core dependencies or fairchem-core . MAPLE auto-downloads supported MAPLE-hosted model files from https://huggingface.co/Wayne7815/MAPLE_models . If you download model files manually through a reachable mirror, keep the same filenames and place them in maple/function/calculator/model/ . Tip: - If access to Hugging Face is slow in your region, you can use the mirror https://hf-mirror.com/Wayne7815/MAPLE_models/tree/main for manual model file downloads. - If the local model directory does not exist, create maple/function/calculator/model/ before placing files there.","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#install-maple"},{"heading":"Install Dependencies","level":2,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":3,"text":"","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#install-dependencies"},{"heading":"Core Dependencies","level":3,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":4,"text":"The core scientific libraries are installed automatically with pip install -e . , but you can also install them manually: pip install numpy scipy ase","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#core-dependencies"},{"heading":"PyTorch","level":3,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":5,"text":"MAPLE requires PyTorch for ML potential inference. Install the version that matches your hardware: With CUDA support (recommended for GPU): pip install torch --index-url https://download.pytorch.org/whl/cu121 CPU only: pip install torch --index-url https://download.pytorch.org/whl/cpu Note Check your CUDA version with nvidia-smi and choose the matching PyTorch CUDA build (e.g., cu118 , cu121 ). Visit pytorch.org for detailed instructions.","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#pytorch"},{"heading":"ML Potentials","level":3,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":6,"text":"ANI, AIMNet2, MACE, MACE-Polar, and UMA use torch-backed runtimes, so install PyTorch separately for your hardware before using them. Install fairchem-core only when you need UMA or FAIR-Chem-backed/PBC workflows: pip install fairchem-core Install JAX/Flax only when you use FeNNol .fnx models: # CPU pip install -U jax flax # NVIDIA GPU (CUDA 12) pip install -U \"jax[cuda12]\" flax Checkpoint and runtime boundaries: Core install: pip install -e . installs MAPLE plus ase , numpy , and scipy ; it does not select a PyTorch/CUDA stack for you. MAPLE-hosted checkpoints: ANI, AIMNet2, maceoff23m , and egret can be auto-downloaded from MAPLE_models . Local checkpoints: backend-specific files such as maceoff23s , maceoff23l , maceomol , and MACE-Polar checkpoints must be placed in maple/function/calculator/model/ or supplied through model_path . FeNNol : built-in fennix-bio1s and fennix-bio1m resolve shipped .fnx files; generic fennol requires model_path=/path/to/model.fnx . UMA: UMA checkpoints resolve through checkpoint_path , a local maple/function/calculator/model/uma-*.pt file, or FAIR-Chem's official loading path. See the calculator backend matrix for the exact PBC, charge/multiplicity, Hessian, D4, solvent, HVP, and checkpoint support of each backend.","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#ml-potentials"},{"heading":"Verify Installation","level":2,"page":"tutorials/installation.html","page_entry":false,"page_role":"content","section_order":7,"text":"After installation, verify that MAPLE is correctly set up by running: maple --help You should see the MAPLE help output listing available commands and options. If the maple command is not found, ensure your Python environment's bin directory is on your PATH . You can also verify GPU availability: python -c \"import torch; print('CUDA available:', torch.cuda.is_available())\" Warning If torch.cuda.is_available() returns False on a system with a GPU, check that your NVIDIA drivers and CUDA toolkit are properly installed and that you installed the CUDA-enabled version of PyTorch.","title":"Installation Guide - MAPLE","trail":["Getting Started","Installation"],"type":"Tutorial","url":"tutorials/installation.html#verify-installation"},{"heading":"Quick Start Tutorial","level":1,"page":"tutorials/quickstart.html","page_entry":true,"page_role":"content","section_order":0,"text":"This tutorial walks you through your first MAPLE calculations. By the end, you will know how to run a single-point energy calculation, perform a geometry optimization, and read the output files.","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#quick-start-tutorial"},{"heading":"Your First Calculation","level":2,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":1,"text":"Let's start with the simplest task: computing the single-point energy of a water molecule. Create a file named water_sp.inp with the following content: #model = ani2x #device = cpu O 0.000000 0.000000 0.117300 H 0.000000 0.757200 -0.469200 H 0.000000 -0.757200 -0.469200 Run the calculation with: maple water_sp.inp Since no task type is specified, MAPLE defaults to a single-point energy calculation. The output will display the electronic energy in Hartree units: Energy: -76.389412305821 Note The #model command selects the ML potential. Here we use ani2x , which supports H, C, N, O, F, S, and Cl atoms. See the Settings page for all available models.","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#your-first-calculation"},{"heading":"Geometry Optimization","level":2,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":2,"text":"To optimize the geometry of a molecule, add the #opt command. Create a file named water_opt.inp : #model = ani2x #device = cpu #opt O 0.000000 0.000000 0.120000 H 0.000000 0.800000 -0.480000 H 0.000000 -0.800000 -0.480000 Run it: maple water_opt.inp MAPLE will iteratively adjust the atomic positions to minimize the energy. The output shows the progress of each optimization step: Iteration E(Eh) dE(kcal/mol) max(|G|) RMS(G) Convergence thresholds 0.000450 0.000300 0 -76.389012 0.00 0.012345 0.005678 1 -76.389398 -0.24 0.003210 0.001234 2 -76.389412 -0.01 0.000321 0.000142 Optimization converged in 2 steps. You can customize the optimization method and convergence level. For example, to use the L-BFGS optimizer with the tight preset: #model = ani2x #opt(method=lbfgs, level=tight) O 0.000000 0.000000 0.120000 H 0.000000 0.800000 -0.480000 H 0.000000 -0.800000 -0.480000 Tip If no parameters are given to #opt , MAPLE uses the default optimizer (L-BFGS) with standard convergence thresholds. This is sufficient for most routine optimizations.","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#geometry-optimization"},{"heading":"Reading Output","level":2,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":3,"text":"MAPLE writes results to the terminal and to output files. The primary output includes: Energy : The electronic energy in Hartree (Eh) at each step. dE : The energy change from the previous step in kcal/mol. max(|G|) : The maximum component of the gradient (atomic forces). RMS(G) : The root-mean-square of the gradient. Maximum displacement : The largest coordinate displacement in the step. RMS displacement : The root-mean-square coordinate displacement. Convergence is reached only when maximum force, RMS force, maximum displacement, and RMS displacement all fall below their respective thresholds, as shown in the convergence criteria section of the output. For optimization jobs, the optimized geometry is written to an XYZ file that you can visualize with molecular viewers such as ASE GUI, Avogadro, or VMD: # View the optimized structure with ASE ase gui water_opt.xyz","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#reading-output"},{"heading":"Next Steps","level":2,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":4,"text":"Now that you have run your first MAPLE calculations, explore these topics to learn more: Guide","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#next-steps"},{"heading":"Input & Output","level":3,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":5,"text":"Learn the full input file structure, header commands, coordinate formats, and output files. Reference","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#input-output"},{"heading":"Settings","level":3,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":6,"text":"Explore all available models, device options, and global configuration parameters. Tasks","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#settings"},{"heading":"Optimization","level":3,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":7,"text":"Dive deeper into optimization methods: L-BFGS, RFO, steepest descent, and their parameters. Tasks","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#optimization"},{"heading":"Transition States","level":3,"page":"tutorials/quickstart.html","page_entry":false,"page_role":"content","section_order":8,"text":"Learn how to find transition states with P-RFO, NEB, Dimer, String, and AutoNEB methods.","title":"Quick Start Tutorial - MAPLE","trail":["Getting Started","Quick Start"],"type":"Tutorial","url":"tutorials/quickstart.html#transition-states"}],"source_pages":55,"version":2};
